(function () {
var DATA = [{"id":"ggdist-01-slabinterval-family","pkg":"ggdist","num":"01","title":"The slabinterval family (overview figure)","source":"slabinterval vignette, chunk slabinterval_family","img":"catalog/img/ggdist-01-slabinterval-family.png","more":[],"gofish":"const x = dist.normal({ mean: 4, sd: 1 });\nconst cell = [{ mean: 4, sd: 1 }];\nconst dots = sample(cell, { n: 100, at: \"quantiles\" });\n// one row per geom\nspread({ dir: \"y\", spacing: 8 }, [\n  // halfeye\n  chart(cell).mark(layer([slab(x), interval(x)])),\n  // eye\n  chart(cell).mark(\n    layer([\n      slab(x, { side: \"both\" }),\n      // gap: this should sit on the slab's zero line, but a\n      // layer aligns its children's boxes, not their\n      // origins\n      interval(x),\n    ])\n  ),\n  // gradientinterval: opacity from the density, scaled so\n  // the peak is 1\n  chart(cell).mark(\n    layer([gradientinterval(x), interval(x)])\n  ),\n  // ccdfinterval: thickness P(X > v), from the axis start at 0\n  chart(cell).mark(\n    layer([\n      ccdf(x, { density: { range: [0] } }),\n      interval(x),\n    ])\n  ),\n  // cdfinterval: thickness P(X <= v), up to the axis end at 8\n  chart(cell).mark(\n    layer([\n      slab(x, {\n        density: { range: [undefined, 8] },\n        curve: (c) =>\n          c.map((r) => ({ ...r, density: r.cdf })),\n      }),\n      interval(x),\n    ])\n  ),\n  // interval\n  chart(cell).mark(\n    interval(x, {\n      levels: [0.95, 0.8, 0.5],\n      point: false,\n      h: 10,\n      opacity: 1 / 3,\n    })\n  ),\n  // pointinterval\n  chart(cell).mark(interval(x)),\n  // slab\n  chart(cell).mark(slab(x)),\n  // histinterval\n  layer([\n    chart(histDf)\n      .flow(\n        partition({\n          by: field(\"x\").bin(Bin.thresholds(30)),\n          dir: \"x\",\n        })\n      )\n      .mark(rect({ h: field(\"x\").count(), fill: SLAB })),\n    chart(cell).mark(interval(x)),\n  ]),\n  // dots\n  chart(dots)\n    .flow(\n      partition({ by: x.bin(Bin.step(0.1)), dir: \"x\" }), // chosen by hand; ggdist picks the width so the tallest stack fits\n      stack({ dir: \"y\" })\n    )\n    .mark(circle({ r: 2 })),\n  // dotsinterval\n  layer([\n    chart(dots)\n      .flow(\n        partition({ by: x.bin(Bin.step(0.1)), dir: \"x\" }), // chosen by hand; ggdist picks the width so the tallest stack fits\n        stack({ dir: \"y\" })\n      )\n      .mark(circle({ r: 2 })),\n    chart(cell).mark(interval(x)),\n  ]),\n]);","uses_up":"mixed: ccdf and cdf rows: the CDF of the draws as thickness; gradient row: the density curve of the draws read as opacity; slab and interval rows: summaries per cell; dots rows: sample at quantiles, then partition and stack","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"Every row can now be written. Version 1 could not write the gradient row, because a blend has no peak scaling. In version 2 it is the density curve of the draws divided by its peak and read as opacity, and the missing piece is that GoFish has no opacity that varies along one region, so the spec marks it as a gap. The eye row has entry 4's layout gap, and the dots rows have the dot-binning gap of entry 20.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk slabinterval_family --\ndists_df = tibble(\n  # enforce order\n  geom = rev(c(\n    \"halfeye\",\n    \"eye\",\n    \"gradientinterval\",\n    \"ccdfinterval\",\n    \"cdfinterval\",\n    \"interval\",\n    \"pointinterval\",\n    \"slab\",\n    \"histinterval\",\n    \"dots\",\n    \"dotsinterval\"\n  )) %>%\n    factor(., levels = .),\n  dist = dist_normal(4, 1)\n)\n\nhist_df = tibble(\n  geom = \"histinterval\",\n  x = qnorm(ppoints(1000), 4, 1)\n)\n\ndists_df_ = function(geom_) filter(dists_df, geom == geom_)\n\n\n# FAMILY HEADER\n\ndists_xlim = c(0,8)\n\nheader_theme = theme(\n  axis.line.x = element_blank(),\n  plot.background = element_rect(fill = \"gray95\"),\n  panel.background = element_blank(),\n  plot.margin = unit(c(5.5, 0, 5.5, 5.5), \"points\")\n)\n\ndists_header_plot = dists_df_(\"halfeye\") %>%\n  mutate(geom = \"slabinterval\") %>%\n  ggplot(aes(y = geom, xdist = dist)) +\n  stat_slabinterval(position = position_nudge(y = - 0.2)) +\n  scale_x_continuous(limits = dists_xlim, expand = c(0,0), breaks = NULL) +\n  scale_y_discrete(expand = c(0.4,0)) +\n  labs(\n    subtitle = \"The stat_slabinterval / geom_slabinterval family\",\n    x = NULL,\n    y = NULL\n  ) +\n  header_theme\n\nstatgeom_theme = list(\n  labs(y = NULL, x = NULL),\n  theme(\n    axis.line.x = element_blank(),\n    axis.line.y = element_blank(),\n    axis.ticks = element_blank(),\n    plot.margin = unit(c(5.5, 5.5, 5.5, 0), \"points\")\n  )\n)\n\nstatgeom_header_plot = data.frame(\n  geom = factor(\"slabinterval\"),\n  prefix = factor(c(\"stat_...\", \"geom_...\"), levels = c(\"stat_...\", \"geom_...\"))\n) %>%\n  ggplot(aes(x = prefix, y = geom)) +\n  geom_hline(aes(yintercept = as.numeric(geom) - .1), color = \"gray80\", data = . %>% filter(prefix == \"stat_...\")) +\n  geom_point(size = 5, color = \"gray65\", position = position_nudge(y = -.1)) +\n  scale_x_discrete(position = \"top\") +\n  scale_y_discrete(breaks = NULL, expand = c(0.4,0)) +\n  statgeom_theme +\n  header_theme\n\n\n# SHORTCUT STATS\n\ndists_plot = dists_df %>%\n  ggplot(aes(y = geom, xdist = dist)) +\n  geom_blank() + # ensures order\n  stat_eye(data = dists_df_(\"eye\")) +\n  stat_halfeye(data = dists_df_(\"halfeye\"), position = position_nudge(y = -0.2)) +\n  stat_gradientinterval(data = dists_df_(\"gradientinterval\"), scale = .5, fill_type = \"gradient\") +\n  stat_ccdfinterval(data = dists_df_(\"ccdfinterval\"), scale = .5) +\n  stat_cdfinterval(data = dists_df_(\"cdfinterval\"), scale = .5) +\n  stat_interval(\n    data = dists_df_(\"interval\"), color = \"gray65\", alpha = 1/3, linewidth = 10,\n    position = position_nudge(y = -.1)\n  ) +\n  stat_pointinterval(data = dists_df_(\"pointinterval\")) +\n  stat_slab(data = dists_df_(\"slab\"), position = position_nudge(y = - 0.2)) +\n  stat_histinterval(aes(x = x, xdist = NULL), data = hist_df, position = position_nudge(y = - 0.25)) +\n  stat_dotsinterval(data = dists_df_(\"dotsinterval\"), position = position_nudge(y = - 0.35)) +\n  stat_dots(data = dists_df_(\"dots\"), position = position_nudge(y = - 0.35)) +\n  scale_slab_alpha_continuous(guide = \"none\") +\n  scale_x_continuous(limits = dists_xlim, expand = c(0,0)) +\n  labs(\n    x = NULL,\n    y = NULL\n  )\n\nstatgeom_plot = tribble(\n  ~geom,                 ~prefix,\n  \"halfeye\",            \"stat_...\",\n  \"eye\",                \"stat_...\",\n  \"gradientinterval\",   \"stat_...\",\n  \"ccdfinterval\",       \"stat_...\",\n  \"cdfinterval\",        \"stat_...\",\n  \"interval\",         c(\"stat_...\", \"geom_...\"),\n  \"pointinterval\",    c(\"stat_...\", \"geom_...\"),\n  \"slab\",             c(\"stat_...\", \"geom_...\"),\n  \"histinterval\",       \"stat_...\",\n  \"dots\",             c(\"stat_...\", \"geom_...\"),\n  \"dotsinterval\",     c(\"stat_...\", \"geom_...\")\n) %>%\n  unnest(prefix) %>%\n  mutate(\n    geom = factor(geom, levels = levels(dists_df$geom)),\n    prefix = factor(prefix, levels = c(\"stat_...\", \"geom_...\"))\n  ) %>%\n  ggplot(aes(x = prefix, y = geom)) +\n  geom_hline(aes(yintercept = as.numeric(geom) - .1), color = \"gray80\", data = . %>% filter(prefix == \"stat_...\")) +\n  geom_point(size = 5, color = \"gray65\", position = position_nudge(y = -.1)) +\n  scale_x_discrete(breaks = NULL) +\n  scale_y_discrete(breaks = NULL, expand = c(0,.6)) +\n  statgeom_theme\n\ndists_header_plot + statgeom_header_plot +\n  dists_plot + statgeom_plot +\n  plot_layout(ncol = 2, widths = c(0.75, 0.25), heights = c(1, 10))"},{"id":"ggdist-02-slabinterval-components","pkg":"ggdist","num":"02","title":"Properties of geom_slabinterval (annotated diagram)","source":"slabinterval vignette, chunk slabinterval_components","img":"catalog/img/ggdist-02-slabinterval-components.png","more":[],"gofish":"const x = dist.normal({ mean: 4, sd: 1 });\nchart([{ g: 0 }], { axes: { x: { domain: [-1, 10] } } })\n  .mark(\n    layer([\n      slab(x, {\n        fill: \"gray75\",\n        density: { range: [0, 8] },\n        stroke: \"black\",\n        strokeWidth: 1,\n      }),\n      // the definition draws the point in the interval's\n      // fill; ggdist draws it gray75 with a black outline\n      interval(x, {\n        levels: [0.6827],\n        fill: \"black\",\n        h: 3,\n      }),\n    ])\n  )\n  // the red annotations: brackets, reference lines, labels\n  // and curved arrows\n  .layer(\n    chart(annotations).mark(\n      text({\n        x: \"x\",\n        y: \"y\",\n        text: \"label\",\n        fill: \"#d95f02\",\n      })\n    )\n  )\n  .layer(chart(arrows).mark(arrow({ fill: \"#d95f02\" })));","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The halfeye is the slab and interval marks of section 1. The annotation layer needs bracket-ended segments (arrowheads at 90 degrees) placed in data coordinates, which GoFish's arrow mark does not offer.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk slabinterval_components --\nred_ = \"#d95f02\"\ngreen_ = \"#1b9e77\"\nblue_ = \"#7570b3\"\n\nbracket_ = function(..., x, xend = x, y, yend = y, color = red_) {\n  annotate(\"segment\",\n    arrow = arrow(angle = 90, ends = \"both\", length = unit(3, \"points\")),\n    color = color, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nthickness_ = function(x) dnorm(x,4,1) * 0.9 / dnorm(4,4,1)\nthickness_bracket_ = function(x) bracket_(x = x, y = 0, yend = thickness_(x))\nrefline_ = function(..., x, xend = x, y, yend = y, color = red_, linetype = \"solid\", alpha = 0.5) {\n  annotate(\"segment\",\n    color = color, linetype = linetype, alpha = alpha, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nlabel_ = function(..., hjust = 0, color = red_) {\n  annotate(\"text\",\n    color = color, hjust = hjust, lineheight = 1,\n    size = 3.25,\n    ...\n  )\n}\narrow_ = function(..., curvature = 0, x, xend = x, y, yend = y) {\n  annotate(\"curve\",\n    color = red_, arrow = arrow(angle = 45, length = unit(3, \"points\"), type = \"closed\"),\n    curvature = curvature,\n    x = x, xend = xend, y = y, yend = yend\n  )\n}\n\n\ndists_df_(\"halfeye\") %>%\n  ggplot(aes(y = 0, xdist = dist)) +\n  stat_slabinterval(\n    aes(linewidth = NULL),\n    slab_color = \"black\",\n    expand = FALSE,\n    limits = c(0, 8),\n    .width = 1 - 2*pnorm(-1),\n    fill = \"gray75\",\n    point_size = 3,\n    shape = 21,\n    stroke = 1.5,\n    linewidth = 3\n  ) +\n\n  # height\n  refline_(x = 0, xend = 8.4, y = 1) +\n  bracket_(x = 8.4, y = 0, yend = 1) +\n  label_(label = \"height\", x = 8.6, y = 1) +\n\n  # scale\n  refline_(x = 4, xend = 8.6, y = 0.9) +\n  bracket_(x = 8.6, y = 0, yend = 0.9) +\n  label_(label = \"scale = 0.9\", x = 8.8, y = 0.9) +\n\n  # thickness\n  thickness_bracket_(2) +\n  thickness_bracket_(2.2) +\n  thickness_bracket_(2.4) +\n  label_(label = \"thickness\", hjust = 1, x = 1.63, y = thickness_(2.2), vjust = 0) +\n  arrow_(curvature = 0.2, x = 1.67, xend = 1.87, y = thickness_(2.2), yend = thickness_(2) + 0.01) +\n  arrow_(x = 1.67, xend = 2.07, y = thickness_(2.2) + 0.01, yend = thickness_(2.2)) +\n  arrow_(curvature = -0.2, x = 1.67, xend = 2.27, y = thickness_(2.2) + 0.02, yend = thickness_(2.4)) +\n\n  # slab line properties\n  label_(x = 2.5, y = 0.7,\n    label = 'slab_color = \"black\"\\nslab_linewidth = 1\\nslab_linetype = linetype = \"solid\"',\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 2.52, xend = 3.08, y = 0.67, yend = thickness_(3.08) + 0.03, curvature = -0.2) +\n\n  # slab fill\n  label_(x = 5.5, y = 0.7,\n    label = 'slab_fill = fill = \"gray75\"\\nslab_alpha = alpha = 1',\n    vjust = 1\n  ) +\n  arrow_(x = 5.48, xend = 4.5, y = 0.67, yend = thickness_(3), curvature = 0.2) +\n\n  # xmin, x, xmax\n  arrow_(x = 2.65, xend = 3, y = -0.1, yend = -0.01, curvature = -0.2) +\n  label_(x = 2.7, y = -0.1, label = \"xmin\", hjust = 1, vjust = 1) +\n  arrow_(x = 4, y = -0.1, yend = -0.04) +\n  label_(x = 4, y = -0.1, label = \"x\", hjust = 0.5, vjust = 1) +\n  arrow_(x = 5.35, xend = 5, y = -0.1, yend = -0.01, curvature = 0.2) +\n  label_(x = 5.3, y = -0.1, label = \"xmax\", hjust = 0, vjust = 1) +\n\n  # interval properties\n  label_(x = 3.5, y = -0.2,\n    label = paste0(\n      'interval_color = color = \"black\"\\n',\n      'interval_alpha = alpha = 1\\n',\n      'interval_linetype = linetype = \"solid\"\\n',\n      'linewidth = size = 3'\n    ),\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 3.3, xend = 3.4, y = -0.18, yend = -0.01, curvature = -0.1) +\n\n  # point properties\n  label_(x = 4.5, y = -0.2,\n    label = paste0(\n      'point_fill = fill = \"gray75\"\\n',\n      'point_color = color = \"black\"\\n',\n      'point_alpha = alpha = 1\\n',\n      'point_size = size = 3\\n',\n      'shape = 21\\n',\n      'stroke = 1.5'\n    ),\n    vjust = 1, hjust = 0\n  ) +\n  arrow_(x = 4.55, xend = 4.12, y = -0.18, yend = -0.02, curvature = 0.2) +\n\n  coord_cartesian(xlim = c(-1, 10), ylim = c(-0.6, 1)) +\n  labs(subtitle = \"Properties of geom_slabinterval\")"},{"id":"ggdist-03-group-halfeye","pkg":"ggdist","num":"03","title":"stat_halfeye() (or stat_slabinterval())","source":"slabinterval vignette, chunk group_halfeye","img":"catalog/img/ggdist-03-group-halfeye.png","more":[],"gofish":"chart(df)\n  .flow(spread({ by: \"group\", dir: \"y\" }))\n  .mark(layer([slab(\"value\"), interval(\"value\")]));","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A half-eye is a layer of the slab and interval marks of section 1. The slab draws the density curve of each group's rows, which ggdist estimates with a kernel. The interval draws the central intervals of the rows as rects by center and size, and a circle at the median. Version 1 computed the distribution by hand in its derives.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk group_halfeye --\ndf %>%\n  ggplot(aes(y = group, x = value)) +\n  stat_halfeye() +\n  ggtitle(\"stat_halfeye() (or stat_slabinterval())\")"},{"id":"ggdist-04-eye-side","pkg":"ggdist","num":"04","title":"stat_slabinterval() with side = left, both, right (vertical)","source":"slabinterval vignette, chunk eye_side","img":"catalog/img/ggdist-04-eye-side.png","more":[],"gofish":"spread({ dir: \"x\", spacing: 16 }, [\n  // side start\n  chart(df)\n    .flow(spread({ by: \"group\", dir: \"x\" }))\n    .mark(\n      layer([\n        slab(\"value\", { dir: \"y\", side: \"start\" }),\n        // gap: this should sit on the slab's zero line, but\n        // a layer aligns its children's boxes, not their\n        // origins\n        interval(\"value\", { dir: \"y\" }),\n      ])\n    ),\n  // side both\n  chart(df)\n    .flow(spread({ by: \"group\", dir: \"x\" }))\n    .mark(\n      layer([\n        slab(\"value\", { dir: \"y\", side: \"both\" }),\n        // gap: this should sit on the slab's zero line, but\n        // a layer aligns its children's boxes, not their\n        // origins\n        interval(\"value\", { dir: \"y\" }),\n      ])\n    ),\n  // side end\n  chart(df)\n    .flow(spread({ by: \"group\", dir: \"x\" }))\n    .mark(\n      layer([\n        slab(\"value\", { dir: \"y\" }),\n        interval(\"value\", { dir: \"y\" }),\n      ])\n    ),\n]);","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Side start and both need the interval to sit on the slab's zero line, but a GoFish layer aligns its children's boxes, not their origins (elaborations.md, design question 'The line the slab sits on'). Side end works because its origin is its box edge.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk eye_side --\np = df %>%\n  ggplot(aes(x = group, y = value)) +\n  theme(panel.background = element_rect(color = \"grey70\"))\n\n(\n  p + stat_slabinterval(side = \"left\") +\n    labs(title = \"stat_slabinterval()\", subtitle = \"side = 'left'\")\n) + (\n  p + stat_slabinterval(side = \"both\") +\n    labs(subtitle = \"side = 'both'\")\n) + (\n  p + stat_slabinterval(side = \"right\") +\n    labs(subtitle = \"side = 'right'\")\n)"},{"id":"ggdist-05-eyeh-side","pkg":"ggdist","num":"05","title":"stat_slabinterval() with side = bottom, both, top (horizontal)","source":"slabinterval vignette, chunk eyeh_side","img":"catalog/img/ggdist-05-eyeh-side.png","more":[],"gofish":"spread({ dir: \"x\", spacing: 16 }, [\n  // side start\n  chart(df)\n    .flow(spread({ by: \"group\", dir: \"y\" }))\n    .mark(\n      layer([\n        slab(\"value\", { side: \"start\" }),\n        // gap: this should sit on the slab's zero line, but\n        // a layer aligns its children's boxes, not their\n        // origins\n        interval(\"value\"),\n      ])\n    ),\n  // side both\n  chart(df)\n    .flow(spread({ by: \"group\", dir: \"y\" }))\n    .mark(\n      layer([\n        slab(\"value\", { side: \"both\" }),\n        // gap: this should sit on the slab's zero line, but\n        // a layer aligns its children's boxes, not their\n        // origins\n        interval(\"value\"),\n      ])\n    ),\n  // side end\n  chart(df)\n    .flow(spread({ by: \"group\", dir: \"y\" }))\n    .mark(layer([slab(\"value\"), interval(\"value\")])),\n]);","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The horizontal version of entry 4, with the same layout gap for side start and both.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk eyeh_side --\np = df %>%\n  ggplot(aes(x = value, y = group)) +\n  theme(panel.background = element_rect(color = \"grey70\"))\n\n(\n  # side = \"left\" would give the same result\n  p + stat_slabinterval(side = \"left\") +\n    ggtitle(\"stat_slabinterval()\") + labs(subtitle = \"side = 'bottom'\")\n) + (\n  p + stat_slabinterval(side = \"both\") + labs(subtitle = \"side = 'both'\")\n) + (\n  # side = \"right\" would give the same result\n  p + stat_slabinterval(side = \"right\") + labs(subtitle = \"side = 'top'\")\n)"},{"id":"ggdist-06-eye-dodge","pkg":"ggdist","num":"06","title":"stat_eye(position = 'dodge')","source":"slabinterval vignette, chunk eye_dodge","img":"catalog/img/ggdist-06-eye-dodge.png","more":[],"gofish":"chart(df)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      slab(\"value\", {\n        dir: \"y\",\n        side: \"both\",\n        fill: \"subgroup\",\n      }),\n      // gap: this should sit on the slab's zero line, but a\n      // layer aligns its children's boxes, not their\n      // origins\n      interval(\"value\", { dir: \"y\" }),\n    ])\n  );","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Dodge is a nested spread. The eye is side both, so it has entry 4's gap: the interval must sit on the slab's center line.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk eye_dodge --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup)) +\n  stat_eye(position = \"dodge\") +\n  ggtitle(\"stat_eye(position = 'dodge')\")"},{"id":"ggdist-07-dist-eye-dodge-distributional","pkg":"ggdist","num":"07","title":"stat_eye(position = 'dodge') with aes(ydist = dist_normal(mean, sd))","source":"slabinterval vignette, chunk dist_eye_dodge_distributional","img":"catalog/img/ggdist-07-dist-eye-dodge-distributional.png","more":[],"gofish":"const y = dist.normal({ mean: \"mean\", sd: \"sd\" });\nchart(distDf)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      slab(y, { dir: \"y\", side: \"both\", fill: \"subgroup\" }),\n      // gap: this should sit on the slab's zero line, but a\n      // layer aligns its children's boxes, not their\n      // origins\n      interval(y, { dir: \"y\" }),\n    ])\n  );","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Entry 6 with analytic normals. Same layout gap for the eye.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk dist_data --\ndist_df = tribble(\n  ~group, ~subgroup, ~mean, ~sd,\n  \"a\",          \"h\",     5,   1,\n  \"b\",          \"h\",     7,   1.5,\n  \"c\",          \"h\",     8,   1,\n  \"c\",          \"i\",     9,   1,\n  \"c\",          \"j\",     7,   1\n)\n# -- chunk dist_eye_dodge_distributional --\ndist_df %>%\n  ggplot(aes(x = group, ydist = dist_normal(mean, sd), fill = subgroup)) +\n  stat_eye(position = \"dodge\") +\n  ggtitle(\"stat_eye(position = 'dodge')\", \"aes(ydist = dist_normal(mean, sd))\")"},{"id":"ggdist-08-beta-stacked","pkg":"ggdist","num":"08","title":"stat_halfeye() of Beta(alpha, 10), y = alpha (continuous)","source":"slabinterval vignette, chunk beta_stacked","img":"catalog/img/ggdist-08-beta-stacked.png","more":[],"gofish":"const x = dist.beta({ alpha: \"alpha\", beta: 10 });\nchart(betas)\n  .flow(scatter({ by: \"alpha\", y: \"alpha\" }))\n  .mark(layer({ h: 24 }, [slab(x), interval(x)]));","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The halfeyes sit at a continuous y position, which scatter gives. It assumes the dist namespace has a beta family and takes a literal parameter.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk beta_stacked --\ndata.frame(alpha = seq(5, 100, length.out = 10)) %>%\n  ggplot(aes(y = alpha, xdist = dist_beta(alpha, 10))) +\n  stat_halfeye() +\n  labs(\n    title = \"stat_halfeye()\",\n    subtitle = \"aes(xdist = dist_beta(alpha, 10), y = alpha)\",\n    x = \"Beta(alpha,10) distribution\"\n  )"},{"id":"ggdist-09-beta-overplotted-slabh","pkg":"ggdist","num":"09","title":"stat_slab() of ten Beta distributions overplotted, color = alpha","source":"slabinterval vignette, chunk beta_overplotted_slabh","img":"catalog/img/ggdist-09-beta-overplotted-slabh.png","more":[],"gofish":"const x = dist.beta({ alpha: \"alpha\", beta: 10 });\nchart(betas, { color: Color.gradient(\"viridis\") })\n  .flow(group({ by: \"alpha\" }))\n  .mark(slab(x, { fill: \"none\", stroke: \"alpha\" }));","uses_up":"the density curve of the draws per cell (exact on a Dist; a kernel estimate over the rows on a sample)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Overplotted slabs on one baseline share the size scale, which is ggdist's default normalize = 'all'.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk beta_overplotted_slabh --\ndata.frame(alpha = seq(5, 100, length.out = 10)) %>%\n  ggplot(aes(xdist = dist_beta(alpha, 10), color = alpha)) +\n  stat_slab(fill = NA) +\n  coord_cartesian(expand = FALSE) +\n  scale_color_viridis_c() +\n  labs(\n    title = \"stat_slab()\",\n    subtitle = \"aes(xdist = dist_beta(alpha, 10), color = alpha)\",\n    x = \"Beta(alpha,10) distribution\",\n    y = NULL\n  )"},{"id":"ggdist-10-prior-dist-halfeyeh","pkg":"ggdist","num":"10","title":"stat_halfeye() of brms priors with parse_dist() and a density subguide","source":"slabinterval vignette, chunk prior_dist_halfeyeh","img":"catalog/img/ggdist-10-prior-dist-halfeyeh.png","more":[],"gofish":"// priors: one row per prior, with a Dist built from its\n// text, e.g. normal(1, 0.5), gamma(2, 2), and normal(0, 1)\n// truncated at 0\nchart(priors)\n  .flow(spread({ by: \"label\", dir: \"y\" }))\n  .mark(layer([slab(\"dist\"), interval(\"dist\")]));","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The slabs fit if a column may hold Dist values of different families (foldDist accepts that). Missing: the subguide, a small density axis drawn inside each slab, and a truncated Dist for the half-normal prior.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk priors --\n# we want to avoid a brms dependency, so we fake it above and\n# just show the output of brms::prior() here\npriors = data.frame(\n  prior = c(\"normal(1, 0.5)\", \"gamma(2, 2)\", \"normal(0, 1)\"),\n  class = c(\"b\", \"phi\", \"sigma\"),\n  coef = c(\"\", \"\", \"\"),\n  group = c(\"\", \"\", \"\"),\n  resp = c(\"\", \"\", \"\"),\n  dpar = c(\"\", \"\", \"\"),\n  nlpar = c(\"\", \"\", \"\"),\n  lb = c(NA, NA, \"0\"),\n  ub = c(NA, NA, NA),\n  stringsAsFactors = FALSE\n)\npriors\n# -- chunk prior_dist_halfeyeh --\npriors %>%\n  parse_dist(prior) %>%\n  ggplot(aes(y = paste(class, \"~\", format(.dist_obj)), xdist = .dist_obj)) +\n  stat_halfeye(subguide = subguide_inside(position = \"right\", title = \"density\")) +\n  labs(\n    title = \"stat_halfeye()\",\n    subtitle = \"with parse_dist() and brms::prior() to show priors\",\n    x = NULL,\n    y = NULL\n  )"},{"id":"ggdist-11-prior-post","pkg":"ggdist","num":"11","title":"prior (slab) + posterior (halfeye), separate vs shared thickness scale","source":"slabinterval vignette, chunk prior_post","img":"catalog/img/ggdist-11-prior-post.png","more":[],"gofish":"const post = dist.normal({ mean: 0.1, sd: 0.5 });\nconst prior = dist.normal({ mean: 0, sd: 1 });\n// separate: each slab divided by its own peak (ggdist default)\nconst separate = chart([{}]).mark(\n  layer([\n    // the posterior slab, divided by its peak\n    slab(post, { density: { normalize: \"peak\" } }),\n    interval(post),\n    // the prior slab, divided by its peak\n    slab(prior, {\n      fill: \"none\",\n      density: { normalize: \"peak\" },\n      stroke: \"red\",\n    }),\n  ])\n);\n// shared: one size scale for both (scale_thickness_shared)\nconst shared = chart([{}]).mark(\n  layer([\n    slab(post),\n    interval(post),\n    // the prior slab\n    slab(prior, { fill: \"none\", stroke: \"#e41a1c\" }),\n  ])\n);\nspread({ dir: \"x\", spacing: 16 }, [separate, shared]);","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"GoFish's default is ggdist's scale_thickness_shared, because both slabs read one size scale. The separate version divides each density curve by its own peak with the slab's density option, which is normalize: \"group\" in elaborations.md.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk prior_post --\nprior_post = data.frame(\n  prior = dist_normal(0, 1),\n  posterior = dist_normal(0.1, 0.5)\n)\n\nseparate_scale_plot = prior_post %>%\n  ggplot() +\n  stat_halfeye(aes(xdist = posterior)) +\n  stat_slab(aes(xdist = prior), fill = NA, color = \"red\") +\n  labs(\n    subtitle = \"default: no shared thickness scale\"\n  )\n\nshared_scale_plot = prior_post %>%\n  ggplot() +\n  stat_halfeye(aes(xdist = posterior)) +\n  stat_slab(aes(xdist = prior), fill = NA, color = \"#e41a1c\") +\n  scale_thickness_shared() +\n  labs(subtitle = \"with scale_thickness_shared()\")\n\nseparate_scale_plot + shared_scale_plot + plot_annotation(title = \"prior (slab) + posterior (halfeye)\")"},{"id":"ggdist-12-dist-halfeyeh-log-scale","pkg":"ggdist","num":"12","title":"stat_halfeye() of a lognormal on scale_x_log10()","source":"slabinterval vignette, chunk dist_halfeyeh_log_scale","img":"catalog/img/ggdist-12-dist-halfeyeh-log-scale.png","more":[],"gofish":"const x = dist.lognormal({\n  meanlog: Math.log(10),\n  sdlog: 2 * Math.log(10),\n});\nchart([{}], { axes: { x: { scale: \"log\" } } }) // no log axis today\n  .mark(layer([slab(x), interval(x)]));","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"GoFish has no log scale. ggdist draws the density of log10(X), so the density curve would also need to know the axis transform. The quantiles would not, since quantiles move with a monotone transform.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk dist_halfeyeh_log_scale --\ndata.frame(dist = dist_lognormal(log(10), 2*log(10))) %>%\n  ggplot(aes(xdist = dist)) +\n  stat_halfeye() +\n  scale_x_log10(breaks = 10^seq(-5,7, by = 2))"},{"id":"ggdist-13-stat-histinterval-horizontal","pkg":"ggdist","num":"13","title":"stat_histinterval(), vertical and horizontal","source":"slabinterval vignette, chunk stat_histinterval_horizontal","img":"catalog/img/ggdist-13-stat-histinterval-horizontal.png","more":[],"gofish":"// the histogram of each group's rows, as bars\nconst vertical = chart(df)\n  .flow(spread({ by: \"group\", dir: \"x\" }))\n  .mark(\n    layer([\n      chart()\n        .flow(\n          partition({\n            by: field(\"value\").bin(Bin.thresholds(20)),\n            dir: \"y\",\n          })\n        )\n        .mark(\n          rect({ w: field(\"value\").count(), fill: SLAB })\n        ),\n      interval(\"value\", { dir: \"y\" }),\n    ])\n  );\nconst horizontal = chart(df)\n  .flow(spread({ by: \"group\", dir: \"y\" }))\n  .mark(\n    layer([\n      chart()\n        .flow(\n          partition({\n            by: field(\"value\").bin(Bin.thresholds(20)),\n            dir: \"x\",\n          })\n        )\n        .mark(\n          rect({ h: field(\"value\").count(), fill: SLAB })\n        ),\n      interval(\"value\"),\n    ])\n  );\nspread({ dir: \"x\", spacing: 16 }, [vertical, horizontal]);","uses_up":"partition by a bin of the value and count over the rows (finite n); the interval is quantiles and the median of the draws","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A histogram per group of rows, which is the bin-and-count form of the dotplot row at finite n. GoFish's bins are the same for every group (cells over the column's domain), while ggdist picks breaks per group; both are histograms.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk stat_histinterval_horizontal --\np = df %>%\n  ggplot(aes(x = group, y = value)) +\n  theme(panel.background = element_rect(color = \"grey70\"))\n\nph = df %>%\n  ggplot(aes(y = group, x = value)) +\n  theme(panel.background = element_rect(color = \"grey70\"))\n\n(\n  p + stat_histinterval() + labs(title = \"stat_histinterval()\", subtitle = \"horizontal\")\n) + (\n  ph + stat_histinterval() + labs(subtitle = \"vertical\")\n)"},{"id":"ggdist-14-stat-histintervalh-outlines","pkg":"ggdist","num":"14","title":"stat_histinterval(outline_bars = FALSE / TRUE)","source":"slabinterval vignette, chunk stat_histintervalh_outlines","img":"catalog/img/ggdist-14-stat-histintervalh-outlines.png","more":[],"gofish":"// outline_bars = FALSE: one stepped outline over the bar tops\nconst separate = chart(df)\n  .flow(spread({ by: \"group\", dir: \"y\" }))\n  .mark(\n    layer([\n      chart()\n        .flow(\n          partition({\n            by: field(\"value\").bin(Bin.thresholds(20)),\n            dir: \"x\",\n          })\n        )\n        .mark(\n          rect({\n            h: field(\"value\").count(),\n            fill: SLAB,\n            stroke: \"none\",\n          })\n        )\n        .layer(\n          line({ curve: Curve.step(), stroke: \"gray45\" })\n        ),\n      interval(\"value\"),\n    ])\n  );\n// outline_bars = TRUE: every bar outlined\nconst outlined = chart(df)\n  .flow(spread({ by: \"group\", dir: \"y\" }))\n  .mark(\n    layer([\n      chart()\n        .flow(\n          partition({\n            by: field(\"value\").bin(Bin.thresholds(20)),\n            dir: \"x\",\n          })\n        )\n        .mark(\n          rect({\n            h: field(\"value\").count(),\n            fill: SLAB,\n            stroke: \"gray45\",\n          })\n        ),\n      interval(\"value\"),\n    ])\n  );\nspread({ dir: \"x\", spacing: 16 }, [separate, outlined]);","uses_up":"partition by a bin of the value and count over the rows; the interval is quantiles and the median of the draws","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Outlining every bar is a rect stroke; the outline of the whole histogram is a stepped line through the bar tops.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- needs chunk 13 --\np = df %>%\n  ggplot(aes(x = group, y = value)) +\n  theme(panel.background = element_rect(color = \"grey70\"))\n\nph = df %>%\n  ggplot(aes(y = group, x = value)) +\n  theme(panel.background = element_rect(color = \"grey70\"))\n\n(\n  p + stat_histinterval() + labs(title = \"stat_histinterval()\", subtitle = \"horizontal\")\n) + (\n  ph + stat_histinterval() + labs(subtitle = \"vertical\")\n)\n# -- chunk stat_histintervalh_outlines --\n(\n  ph + stat_histinterval(slab_color = \"gray45\", outline_bars = FALSE) +\n    labs(title = \"stat_histinterval\", subtitle = \"outline_bars = FALSE (default)\")\n) + (\n  ph + stat_histinterval(slab_color = \"gray45\", outline_bars = TRUE) +\n    labs(subtitle = \"outline_bars = TRUE\")\n)"},{"id":"ggdist-15-dist-slab-discrete","pkg":"ggdist","num":"15","title":"stat_slab() of Poisson distributions, fill = after_stat(pdf), with a line through lambda","source":"slabinterval vignette, chunk dist_slab_discrete","img":"catalog/img/ggdist-15-dist-slab-discrete.png","more":[],"gofish":"const y = dist.poisson({ lambda: \"lambda\" });\nlayer([\n  chart(sample(pois, { n: Infinity }), {\n    color: Color.gradient([\"#132b43\", \"#56b1f7\"]),\n  })\n    .flow(\n      spread({ by: \"group\", dir: \"x\" }),\n      partition({ by: y.bin(Bin.step(1)), dir: \"y\" })\n    )\n    .mark(\n      rect({ w: y.probability(), fill: y.probability() })\n    ),\n  chart(pois)\n    .flow(spread({ by: \"group\", dir: \"x\" }))\n    .mark(circle({ cy: \"lambda\", r: 3 }))\n    .layer(line({ strokeWidth: 1 })),\n]);","uses_up":"partition by a bin of the drawn value, then the probability of each bin in each bin, n = Infinity","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A discrete slab is one bar per integer whose width is the pmf. At n = Infinity, partition groups the draws into bins and the probability of each bin uses them up, which rule 3.1 allows. Version 1 had no summary for this and needed a grid derive. The line joins plain lambda values, not draws.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk dist_slab_discrete --\ntibble(\n  group = c(\"a\",\"b\",\"c\",\"d\",\"e\"),\n  lambda = c(13,7,4,3,2)\n) %>%\n  ggplot(aes(x = group)) +\n  stat_slab(aes(ydist = dist_poisson(lambda), fill = after_stat(pdf))) +\n  geom_line(aes(y = lambda, group = NA), linewidth = 1) +\n  geom_point(aes(y = lambda), size = 2.5) +\n  labs(fill = \"Pr(y)\") +\n  ggtitle(\"stat_slab()\", \"aes(ydist = dist_poisson(lambda), fill = after_stat(pdf))\")"},{"id":"ggdist-16-ccdf-barplot","pkg":"ggdist","num":"16","title":"stat_ccdfinterval(position = 'dodge') on sample rows","source":"slabinterval vignette, chunk ccdf_barplot","img":"catalog/img/ggdist-16-ccdf-barplot.png","more":[],"gofish":"// df's rows are the draws. On a sample, the cdf column of\n// the curve is the sample's ECDF, so the thickness is the\n// share of rows above v.\nchart(df)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      // the bar starts at the axis's lower limit, 1.5, as\n      // ggdist's does\n      ccdf(\"value\", {\n        dir: \"y\",\n        fill: \"subgroup\",\n        density: { range: [1.5] },\n      }),\n      interval(\"value\", { dir: \"y\" }),\n    ])\n  );","uses_up":"summaries per cell: the sample's ECDF as thickness (ccdf), and quantiles and the median of the rows","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The ccdf mark of section 1: a slab whose thickness is 1 - cdf, the share of the cell's rows above v. The rows are a sample, so the cdf is the sample's ECDF, read off the curve's grid. The bar starts at the axis's lower limit (1.5), as ggdist's does, through the curve's range. The sorted dodged bars of version 1 tend to this picture as the sample grows, but at 1000 rows ggdist draws the CCDF, not the bars. No draw column is needed, since nothing places single draws.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk ccdf_barplot --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup, group = subgroup)) +\n  stat_ccdfinterval(position = \"dodge\") +\n  ggtitle(\"stat_ccdfinterval(position = 'dodge')\")"},{"id":"ggdist-17-ccdf-justification","pkg":"ggdist","num":"17","title":"stat_ccdfinterval(position = 'dodge', justification = 1) with y from 0","source":"slabinterval vignette, chunk ccdf_justification","img":"catalog/img/ggdist-17-ccdf-justification.png","more":[],"gofish":"// df's rows are the draws. On a sample, the cdf column of\n// the curve is the sample's ECDF, so the thickness is the\n// share of rows above v.\nchart(df)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      // the axis starts at 0, so the bar does too\n      ccdf(\"value\", {\n        dir: \"y\",\n        fill: \"subgroup\",\n        density: { range: [0] },\n      }),\n      interval(\"value\", { dir: \"y\" }),\n    ])\n  );","uses_up":"summaries per cell: the sample's ECDF as thickness (ccdf), and quantiles and the median of the rows","fit":"fits","verdict":"ok","v1_fit":"fits","note":"As entry 16, with the axis and the bar from 0. justification = 1 puts the interval at the bar's left edge, which is the layer's alignment of the interval child.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk ccdf_justification --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup)) +\n  stat_ccdfinterval(position = \"dodge\", justification = 1) +\n  expand_limits(y = 0) +\n  coord_cartesian(expand = FALSE) +\n  ggtitle(\"stat_ccdfinterval(position = 'dodge', justification = 1)\")"},{"id":"ggdist-18-gradient-dodge","pkg":"ggdist","num":"18","title":"stat_gradientinterval(position = 'dodge')","source":"slabinterval vignette, chunk gradient_dodge","img":"catalog/img/ggdist-18-gradient-dodge.png","more":[],"gofish":"chart(df)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      gradientinterval(\"value\", {\n        dir: \"y\",\n        fill: \"subgroup\",\n      }),\n      interval(\"value\", { dir: \"y\" }),\n    ])\n  );","uses_up":"the density curve of the draws per cell, divided by its peak and read as opacity along the slab (the second kind of ggdist mark)","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"ggdist sets opacity from the density, rescaled so the densest point is opaque. Version 1 tried a blend and failed: a blend gives the chance of covering a pixel, which has no peak scaling. Version 2 says it is not a picture of draws at all. It is the density curve of the draws, divided by its peak in the derive, read by an ordinary opacity channel. GoFish has no opacity that varies along one region, so the spec marks it as a gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk gradient_dodge --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup)) +\n  stat_gradientinterval(position = \"dodge\") +\n  labs(title = \"stat_gradientinterval(position = 'dodge')\")"},{"id":"ggdist-19-gradient-dodge-nice","pkg":"ggdist","num":"19","title":"stat_gradientinterval(position = 'dodge', fill_type = 'gradient')","source":"slabinterval vignette, chunk gradient_dodge_nice","img":"catalog/img/ggdist-19-gradient-dodge-nice.png","more":[],"gofish":"chart(df)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      gradientinterval(\"value\", {\n        dir: \"y\",\n        fill: \"subgroup\",\n      }),\n      interval(\"value\", { dir: \"y\" }),\n    ])\n  );","uses_up":"the density curve of the draws per cell, divided by its peak and read as opacity along the slab (the second kind of ggdist mark)","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"Entry 18 drawn with a true gradient fill instead of segments. Same spec and the same gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk gradient_dodge_nice --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup)) +\n  stat_gradientinterval(position = \"dodge\", fill_type = \"gradient\") +\n  labs(title = \"stat_gradientinterval(position = 'dodge', fill_type = 'gradient')\")"},{"id":"ggdist-20-dots-dodge-nocolor","pkg":"ggdist","num":"20","title":"stat_dots() dodged, fill and color = subgroup","source":"slabinterval vignette, chunk dots_dodge_nocolor","img":"catalog/img/ggdist-20-dots-dodge-nocolor.png","more":[],"gofish":"chart(df)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" }),\n    partition({\n      by: field(\"value\").bin(Bin.step(0.15)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"y\",\n    }),\n    stack({ dir: \"x\" })\n  )\n  .mark(\n    circle({ r: 1, fill: \"subgroup\", stroke: \"subgroup\" })\n  );","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The dotplot row of the table at finite n, with the rows as draws. GoFish has Bin.step, partition and stack, but not dot-density (Wilkinson) binning or a bin width chosen from the axis scale so the dots touch and the tallest stack fits; the author must match the bin width and r by hand.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk dots_dodge_nocolor --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup, color = subgroup)) +\n  stat_dots(position = \"dodgejust\") +\n  labs(\n    title = \"stat_dots()\",\n    subtitle = \"aes(fill = subgroup, color = subgroup))\"\n  )"},{"id":"ggdist-21-quantile-dots-dodge","pkg":"ggdist","num":"21","title":"stat_dots(quantiles = 50) dodged","source":"slabinterval vignette, chunk quantile_dots_dodge","img":"catalog/img/ggdist-21-quantile-dots-dodge.png","more":[],"gofish":"// stat_dots(quantiles = 50) of a sample: keep every 20th of\n// each cell's 1000 ranks\nchart(withDraw(df), {\n  schema: { value: { draws: \"draw\" } },\n})\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" }),\n    filter(\n      (d) => Math.round(d.level * 1000 + 0.5) % 20 === 10\n    ),\n    partition({\n      by: field(\"value\").bin(Bin.step(0.3)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"y\",\n    }),\n    stack({ dir: \"x\" })\n  )\n  .mark(circle({ r: 3, fill: \"subgroup\" }));","uses_up":"a filter on level keeps 50 of each cell's 1000 rows, then partition by a bin and stack (finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"ggdist takes 50 quantiles of each group's 1000 rows. at: \"quantiles\" applies to a Dist cell, not to a sample, so version 2 has no step that thins a sample to n quantiles. The spec keeps every 20th rank with a filter on level, which is exact for 1000 rows but has to know the row count. It also has entry 16's caveats about the draw key. GoFish has Bin.step, partition and stack, but not dot-density (Wilkinson) binning or a bin width chosen from the axis scale so the dots touch and the tallest stack fits; the author must match the bin width and r by hand.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk quantile_dots_dodge --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup)) +\n  stat_dots(position = \"dodgejust\", quantiles = 50, color = NA) +\n  labs(title = \"stat_dots(quantiles = 50)\")"},{"id":"ggdist-22-ccdf-gradient","pkg":"ggdist","num":"22","title":"stat_ccdfinterval(thickness = 1), aes(slab_alpha = after_stat(f))","source":"slabinterval vignette, chunk ccdf_gradient","img":"catalog/img/ggdist-22-ccdf-gradient.png","more":[],"gofish":"// df has no draw column; withDraw adds a row index, and the\n// schema declares it\nchart(withDraw(df), {\n  schema: { value: { draws: \"draw\" } },\n})\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      chart()\n        .flow(group({ by: \"draw\", blend: \"mean\" }))\n        .mark(rect({ h: \"value\", fill: \"subgroup\" })),\n      interval(\"value\", { dir: \"y\" }),\n    ])\n  );","uses_up":"group({ by: \"draw\", blend: \"mean\" }) over the 1000 rows of each cell","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Full-width bars from 0 to each draw, averaged, have opacity P(Y > y) at height y, which is the CCDF fade of the table. It matches ggdist because the CCDF already runs from 0 to 1, so ggdist's alpha rescaling changes nothing. The same chart is also a summary: opacity 1 - cdf along the bar, from the CDF of the draws. Entry 16's caveats about the draw key apply.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk ccdf_gradient --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup)) +\n  stat_ccdfinterval(aes(slab_alpha = after_stat(f)),\n    thickness = 1, position = \"dodge\", fill_type = \"gradient\"\n  ) +\n  expand_limits(y = 0) +\n  # plus coord_cartesian so there is no space between bars and axis\n  coord_cartesian(expand = FALSE) +\n  ggtitle(\"stat_ccdfinterval(thickness = 1)\", \"aes(slab_alpha = after_stat(f))\")"},{"id":"ggdist-23-norm-vs-t-highlight","pkg":"ggdist","num":"23","title":"stat_halfeye(aes(fill = after_stat(abs(x) < 1.5))) for Normal and Student t","source":"slabinterval vignette, chunk norm_vs_t_highlight","img":"catalog/img/ggdist-23-norm-vs-t-highlight.png","more":[],"gofish":"chart(priors)\n  .flow(spread({ by: \"label\", dir: \"y\" }))\n  .mark(\n    layer([\n      slab(\"dist\", { fill: \"gray85\" }),\n      // the same curve cut to |x| < 1.5, drawn on top\n      slab(\"dist\", {\n        fill: \"skyblue\",\n        curve: (c) => c.filter((r) => Math.abs(r.v) < 1.5),\n      }),\n      interval(\"dist\"),\n    ])\n  );","uses_up":"density curves of the draws per cell, the second cut to |x| < 1.5; quantiles and the median of the draws for the interval","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Coloring a slab by a predicate on x is a second slab whose curve is filtered to the region, drawn on top; both read one size scale so they line up. A partition intersected with the slab, as in the proposal's quantile-ribbon example, would also work.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk norm_vs_t_highlight --\npriors = tibble(\n  dist = c(dist_normal(0, 1), dist_student_t(3, 0, 1))\n)\n\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_halfeye(aes(fill = after_stat(abs(x) < 1.5))) +\n  ggtitle(\"stat_halfeye()\", \"aes(fill = after_stat(abs(x) < 1.5)))\") +\n  # we'll use a nicer palette than the default for highlighting:\n  scale_fill_manual(values = c(\"gray85\", \"skyblue\"))"},{"id":"ggdist-24-norm-vs-t-gradient-eye","pkg":"ggdist","num":"24","title":"stat_eye(fill_type = 'gradient'), slab_alpha = f, fill = x > 1","source":"slabinterval vignette, chunk norm_vs_t_gradient_eye","img":"catalog/img/ggdist-24-norm-vs-t-gradient-eye.png","more":[],"gofish":"chart(priors)\n  .flow(spread({ by: \"label\", dir: \"y\" }))\n  .mark(\n    layer([\n      // fill = x > 1: two eyes cut at 1\n      // an eye cut to x <= 1, divided by its peak; gap: an\n      // opacity that varies along one region\n      slab(\"dist\", {\n        side: \"both\",\n        fill: \"gray75\",\n        density: { normalize: \"peak\" },\n        curve: (c) =>\n          c\n            .filter((r) => r.v <= 1)\n            .map((r) => ({ ...r, alpha: r.density })),\n        opacity: \"alpha\",\n      }),\n      // an eye cut to x > 1, divided by its peak; gap: an\n      // opacity that varies along one region\n      slab(\"dist\", {\n        side: \"both\",\n        fill: \"skyblue\",\n        density: { normalize: \"peak\" },\n        curve: (c) =>\n          c\n            .filter((r) => r.v > 1)\n            .map((r) => ({ ...r, alpha: r.density })),\n        opacity: \"alpha\",\n      }),\n      // gap: this should sit on the slab's zero line, but a\n      // layer aligns its children's boxes, not their\n      // origins\n      interval(\"dist\"),\n    ])\n  );","uses_up":"the density curve of the draws per cell, divided by its peak and read as opacity along the slab (the second kind of ggdist mark)","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"An eye whose opacity is the density divided by its peak. Coloring by x > 1 is two eyes whose curves are filtered at 1, as in entry 23, so the predicate needs no channel. Missing: GoFish has no opacity that varies along one region, so the spec marks it as a gap, and the eye has entry 4's layout gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 23 --\npriors = tibble(\n  dist = c(dist_normal(0, 1), dist_student_t(3, 0, 1))\n)\n\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_halfeye(aes(fill = after_stat(abs(x) < 1.5))) +\n  ggtitle(\"stat_halfeye()\", \"aes(fill = after_stat(abs(x) < 1.5)))\") +\n  # we'll use a nicer palette than the default for highlighting:\n  scale_fill_manual(values = c(\"gray85\", \"skyblue\"))\n# -- chunk norm_vs_t_gradient_eye --\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_eye(aes(slab_alpha = after_stat(f), fill = after_stat(x > 1)), fill_type = \"gradient\") +\n  ggtitle(\n    \"stat_eye(fill_type = 'gradient')\",\n    \"aes(slab_alpha = after_stat(f), fill = after_stat(x > 1)))\"\n  ) +\n  # we'll use a nicer palette than the default for highlighting:\n  scale_fill_manual(values = c(\"gray75\", \"skyblue\"))"},{"id":"ggdist-25-correll-gradient","pkg":"ggdist","num":"25","title":"stat_gradientinterval with slab_alpha = -pmax(abs(1 - 2*cdf), .95) (Correll and Gleicher)","source":"slabinterval vignette, chunk correll_gradient","img":"catalog/img/ggdist-25-correll-gradient.png","more":[],"gofish":"chart(priors)\n  .flow(spread({ by: \"label\", dir: \"y\" }))\n  .mark(\n    layer([\n      // Correll and Gleicher: opacity 1 over the central\n      // 95%, fading to 0 in the tails\n      // gap: an opacity that varies along one region\n      slab(\"dist\", {\n        curve: (c) =>\n          c.map((r) => ({\n            ...r,\n            density: 1,\n            alpha:\n              (1 -\n                Math.max(Math.abs(1 - 2 * r.cdf), 0.95)) /\n              0.05,\n          })),\n        opacity: \"alpha\",\n      }),\n      interval(\"dist\"),\n    ])\n  );","uses_up":"the CDF of the draws per cell, turned into opacity along the slab (the second kind of ggdist mark)","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"The opacity is a function of the CDF that no blend makes, because a blend is linear in the distribution. Version 1 stopped there. In version 2 the CDF is a column of the density curve's rows, the function is ordinary arithmetic on it, and opacity reads the result. Dividing by 0.05 puts the plateau at 1, as ggdist's alpha scale does (ggdist keeps a floor of 0.1). GoFish has no opacity that varies along one region, so the spec marks it as a gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 23 --\npriors = tibble(\n  dist = c(dist_normal(0, 1), dist_student_t(3, 0, 1))\n)\n\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_halfeye(aes(fill = after_stat(abs(x) < 1.5))) +\n  ggtitle(\"stat_halfeye()\", \"aes(fill = after_stat(abs(x) < 1.5)))\") +\n  # we'll use a nicer palette than the default for highlighting:\n  scale_fill_manual(values = c(\"gray85\", \"skyblue\"))\n# -- chunk correll_gradient --\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_gradientinterval(aes(slab_alpha = after_stat(-pmax(abs(1 - 2*cdf), .95))),\n    fill_type = \"gradient\"\n  ) +\n  scale_slab_alpha_continuous(guide = \"none\") +\n  ggtitle(\n    \"stat_gradientinterval(fill_type = 'gradient')\",\n    \"aes(slab_alpha = after_stat(-pmax(abs(1 - 2*cdf), .95)))\"\n  )"},{"id":"ggdist-26-helske-gradient-eye","pkg":"ggdist","num":"26","title":"stat_eye(fill_type = 'gradient') with slab_alpha = -pmax(abs(1 - 2*cdf), .95) (Helske et al.)","source":"slabinterval vignette, chunk helske_gradient_eye","img":"catalog/img/ggdist-26-helske-gradient-eye.png","more":[],"gofish":"chart(priors)\n  .flow(spread({ by: \"label\", dir: \"y\" }))\n  .mark(\n    layer([\n      // an eye with the fade of entry 25 as its opacity\n      // gap: an opacity that varies along one region\n      slab(\"dist\", {\n        side: \"both\",\n        curve: (c) =>\n          c.map((r) => ({\n            ...r,\n            alpha:\n              (1 -\n                Math.max(Math.abs(1 - 2 * r.cdf), 0.95)) /\n              0.05,\n          })),\n        opacity: \"alpha\",\n      }),\n      // gap: this should sit on the slab's zero line, but a\n      // layer aligns its children's boxes, not their\n      // origins\n      interval(\"dist\"),\n    ])\n  );","uses_up":"the density curve of the draws for the shape and their CDF for the opacity, per cell","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"Entry 25's fade on an eye. Missing: GoFish has no opacity that varies along one region, so the spec marks it as a gap, and the eye has entry 4's layout gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 23 --\npriors = tibble(\n  dist = c(dist_normal(0, 1), dist_student_t(3, 0, 1))\n)\n\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_halfeye(aes(fill = after_stat(abs(x) < 1.5))) +\n  ggtitle(\"stat_halfeye()\", \"aes(fill = after_stat(abs(x) < 1.5)))\") +\n  # we'll use a nicer palette than the default for highlighting:\n  scale_fill_manual(values = c(\"gray85\", \"skyblue\"))\n# -- chunk helske_gradient_eye --\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_eye(aes(slab_alpha = after_stat(-pmax(abs(1 - 2*cdf), .95))), fill_type = \"gradient\") +\n  scale_slab_alpha_continuous(guide = \"none\") +\n  ggtitle(\n    \"stat_eye(fill_type = 'gradient')\",\n    \"aes(slab_alpha = after_stat(-pmax(abs(1 - 2*cdf), .95)))\"\n  )"},{"id":"ggdist-27-tukey-pencils","pkg":"ggdist","num":"27","title":"Tukey pencils: stat_slab(side = 'both'), thickness and fill_ramp = pmax(0, abs(1 - 2*cdf) - .95)","source":"slabinterval vignette, chunk tukey_pencils","img":"catalog/img/ggdist-27-tukey-pencils.png","more":[],"gofish":"const y = dist.normal({ mean: \"mean\", sd: \"sd\" });\nchart(distDf)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      // Tukey pencils: thickness max(0, |1 - 2 cdf| -\n      // 0.95), on both sides. gap: fill_ramp by the same\n      // curve\n      slab(y, {\n        dir: \"y\",\n        side: \"both\",\n        fill: \"subgroup\",\n        curve: (c) =>\n          c.map((r) => ({\n            ...r,\n            density: Math.max(\n              0,\n              Math.abs(1 - 2 * r.cdf) - 0.95\n            ),\n          })),\n      }),\n    ])\n  );","uses_up":"the CDF of the draws per cell, turned into thickness","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The thickness is arithmetic on the CDF column of the density curve, and side both with no interval has no alignment problem. Missing: fill_ramp, the fill lightening along the slab, which needs a fill that varies along one ribbon.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk dist_data --\ndist_df = tribble(\n  ~group, ~subgroup, ~mean, ~sd,\n  \"a\",          \"h\",     5,   1,\n  \"b\",          \"h\",     7,   1.5,\n  \"c\",          \"h\",     8,   1,\n  \"c\",          \"i\",     9,   1,\n  \"c\",          \"j\",     7,   1\n)\n# -- chunk tukey_pencils --\ndist_df %>%\n  ggplot(aes(x = group, ydist = dist_normal(mean, sd), fill = subgroup)) +\n  stat_slab(\n    aes(\n      thickness = after_stat(pmax(0, abs(1 - 2*cdf) - .95)),\n      fill_ramp = after_stat(pmax(0, abs(1 - 2*cdf) - .95))\n    ),\n    side = \"both\", position = \"dodge\", fill_type = \"gradient\"\n  ) +\n  labs(\n    title = 'stat_slab(side = \"both\")',\n    subtitle = paste0(\n      \"aes(fill = subgroup,\\n       \",\n      \"fill_ramp and thickness = after_stat(pmax(0, abs(1 - 2*cdf) - .95)))\"\n    )\n  ) +\n  guides(fill_ramp = \"none\") +\n  coord_cartesian(expand = FALSE)"},{"id":"ggdist-28-halfeye-filled-intervals","pkg":"ggdist","num":"28","title":"stat_halfeye(aes(fill = after_stat(level)))","source":"slabinterval vignette, chunk halfeye_filled_intervals","img":"catalog/img/ggdist-28-halfeye-filled-intervals.png","more":[],"gofish":"chart(df)\n  .flow(spread({ by: \"group\", dir: \"y\" }))\n  .mark(\n    layer([\n      // the whole curve\n      slab(\"value\", { fill: \"gray85\" }),\n      // the curve cut to the central 95% interval\n      slab(\"value\", {\n        fill: \"#c6dbef\",\n        curve: (c) =>\n          c.filter(\n            (r) => Math.abs(r.cdf - 0.5) <= 0.95 / 2\n          ),\n      }),\n      // the curve cut to the central 66% interval\n      slab(\"value\", {\n        fill: \"#6baed6\",\n        curve: (c) =>\n          c.filter(\n            (r) => Math.abs(r.cdf - 0.5) <= 0.66 / 2\n          ),\n      }),\n      interval(\"value\"),\n    ])\n  );","uses_up":"density curves of the draws per cell, cut to the central 95% and 66% by quantiles of the draws and drawn nested; quantiles and the median of the draws for the interval","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Each level is the density curve filtered to the central interval, where |cdf - 0.5| <= p / 2, drawn widest first. The cut falls on the curve's grid points, so its ends are as fine as the grid. Bin.quantiles cannot do it, because GoFish computes quantile cells over the whole column, not per group.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk halfeye_filled_intervals --\ndf %>%\n  ggplot(aes(y = group, x = value)) +\n  stat_halfeye(aes(fill = after_stat(level))) +\n  # na.translate = FALSE drops the unnecessary NA from the legend, which covers\n  # slab values outside the intervals. An alternative would be to use\n  # na.value = ... to set the color for values outside the intervals.\n  scale_fill_brewer(na.translate = FALSE) +\n  labs(\n    title = \"stat_halfeye()\",\n    subtitle = \"aes(fill = after_stat(level))\",\n    fill = \"interval\"\n  )"},{"id":"ggdist-29-halfeye-filled-intervals-2","pkg":"ggdist","num":"29","title":"stat_slab(aes(fill = after_stat(level)), .width = c(.66, .95, 1)) + stat_pointinterval()","source":"slabinterval vignette, chunk halfeye_filled_intervals_2","img":"catalog/img/ggdist-29-halfeye-filled-intervals-2.png","more":[],"gofish":"chart(df)\n  .flow(spread({ by: \"group\", dir: \"y\" }))\n  .mark(\n    layer([\n      // the whole curve\n      slab(\"value\", { fill: \"#deebf7\" }),\n      // the curve cut to the central 95% interval\n      slab(\"value\", {\n        fill: \"#9ecae1\",\n        curve: (c) =>\n          c.filter(\n            (r) => Math.abs(r.cdf - 0.5) <= 0.95 / 2\n          ),\n      }),\n      // the curve cut to the central 66% interval\n      slab(\"value\", {\n        fill: \"#3182bd\",\n        curve: (c) =>\n          c.filter(\n            (r) => Math.abs(r.cdf - 0.5) <= 0.66 / 2\n          ),\n      }),\n      interval(\"value\"),\n    ])\n  );","uses_up":"density curves of the draws per cell, cut to the central 95% and 66% by quantiles of the draws and drawn nested; quantiles and the median of the draws for the interval","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Entry 28 with a 100% level in place of the gray remainder.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk halfeye_filled_intervals_2 --\ndf %>%\n  ggplot(aes(y = group, x = value)) +\n  stat_slab(aes(fill = after_stat(level)), .width = c(.66, .95, 1)) +\n  stat_pointinterval() +\n  scale_fill_brewer() +\n  labs(\n    title = \"stat_slab()\",\n    subtitle = \"aes(fill = after_stat(level), .width = c(.66, .95, 1))\",\n    fill = \"interval\"\n  )"},{"id":"ggdist-30-halfeye-qi-vs-hdi","pkg":"ggdist","num":"30","title":"stat_halfeye fill = level: median_qi vs mode_hdci, Beta(10, 2)","source":"slabinterval vignette, chunk halfeye_qi_vs_hdi","img":"catalog/img/ggdist-30-halfeye-qi-vs-hdi.png","more":[],"gofish":"const x = dist.beta({ alpha: 10, beta: 2 });\n// median_qi\nconst qi = chart([{}]).mark(\n  layer([\n    // the whole curve\n    slab(x, { fill: \"gray95\" }),\n    // the curve cut to the central 95% interval\n    slab(x, {\n      fill: \"#deebf7\",\n      curve: (c) =>\n        c.filter((r) => Math.abs(r.cdf - 0.5) <= 0.95 / 2),\n    }),\n    // the curve cut to the central 80% interval\n    slab(x, {\n      fill: \"#9ecae1\",\n      curve: (c) =>\n        c.filter((r) => Math.abs(r.cdf - 0.5) <= 0.8 / 2),\n    }),\n    // the curve cut to the central 50% interval\n    slab(x, {\n      fill: \"#3182bd\",\n      curve: (c) =>\n        c.filter((r) => Math.abs(r.cdf - 0.5) <= 0.5 / 2),\n    }),\n    interval(x, { levels: [0.95, 0.8, 0.5] }),\n  ])\n);\n// mode_hdci\nconst hdci = chart([{}]).mark(\n  layer([\n    // gap: the mode and the highest-density interval,\n    // written as the helper they would most likely be\n    // the whole curve\n    slab(x, { fill: \"gray95\" }),\n    // the curve cut to the 95% highest-density interval\n    slab(x, {\n      fill: \"#deebf7\",\n      curve: (c, rows) => {\n        const [hdi] = highestDensityIntervals(rows, x, [\n          0.95,\n        ]);\n        return c.filter(\n          (r) => Math.abs(r.v - hdi.center) <= hdi.size / 2\n        );\n      },\n    }),\n    // the curve cut to the 80% highest-density interval\n    slab(x, {\n      fill: \"#9ecae1\",\n      curve: (c, rows) => {\n        const [hdi] = highestDensityIntervals(rows, x, [\n          0.8,\n        ]);\n        return c.filter(\n          (r) => Math.abs(r.v - hdi.center) <= hdi.size / 2\n        );\n      },\n    }),\n    // the curve cut to the 50% highest-density interval\n    slab(x, {\n      fill: \"#3182bd\",\n      curve: (c, rows) => {\n        const [hdi] = highestDensityIntervals(rows, x, [\n          0.5,\n        ]);\n        return c.filter(\n          (r) => Math.abs(r.v - hdi.center) <= hdi.size / 2\n        );\n      },\n    }),\n    interval(x, {\n      levels: [0.95, 0.8, 0.5],\n      intervals: highestDensityIntervals,\n      point: \"mode\",\n    }),\n  ])\n);\nspread({ dir: \"y\", spacing: 16 }, [qi, hdci]);","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The quantile-interval panel fits. The second panel needs the mode and the highest-density continuous interval. Neither is in version 2's list of summaries, so the spec writes them as the helper they would most likely be. They are general summaries, not special to draws, so this is a GoFish gap; on draws an HDI is the shortest window of levels.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk halfeye_qi_vs_hdi --\nqi_plot = data.frame(dist = dist_beta(10, 2)) %>%\n  ggplot(aes(xdist = dist)) +\n  stat_halfeye(aes(fill = after_stat(level)), point_interval = median_qi, .width = c(.5, .8, .95)) +\n  scale_fill_brewer(na.value = \"gray95\") +\n  labs(subtitle = \"stat_halfeye(aes(fill = after_stat(level)), point_interval = median_qi)\")\n\nhdi_plot = data.frame(dist = dist_beta(10, 2)) %>%\n  ggplot(aes(xdist = dist)) +\n  stat_halfeye(aes(fill = after_stat(level)), point_interval = mode_hdci, .width = c(.5, .8, .95)) +\n  scale_fill_brewer(na.value = \"gray95\") +\n  labs(subtitle = \"stat_halfeye(aes(fill = after_stat(level)), point_interval = mode_hdci)\")\n\nqi_plot /\n  hdi_plot"},{"id":"ggdist-31-halfeye-qi-vs-hdi-spikes","pkg":"ggdist","num":"31","title":"stat_slab + stat_spike at median and qi vs mode and hdi","source":"slabinterval vignette, chunk halfeye_qi_vs_hdi_spikes","img":"catalog/img/ggdist-31-halfeye-qi-vs-hdi-spikes.png","more":[],"gofish":"const x = dist.beta({ alpha: 10, beta: 2 });\n// a spike: a 1 px rect from 0 to the density at a point, so\n// it shares the slab's size scale\n// median and qi\nconst qi = chart([{}]).mark(\n  layer([\n    // the whole curve\n    slab(x, { fill: \"#deebf7\" }),\n    // the curve cut to the central 95% interval\n    slab(x, {\n      fill: \"#9ecae1\",\n      curve: (c) =>\n        c.filter((r) => Math.abs(r.cdf - 0.5) <= 0.95 / 2),\n    }),\n    // the curve cut to the central 50% interval\n    slab(x, {\n      fill: \"#3182bd\",\n      curve: (c) =>\n        c.filter((r) => Math.abs(r.cdf - 0.5) <= 0.5 / 2),\n    }),\n    // spikes; linetype by kind: no field mapping\n    rect({ x: x.median(), w: 1, h: x.density(x.median()) }),\n    rect({\n      x: x.quantile(0.025),\n      w: 1,\n      h: x.density(x.quantile(0.025)),\n    }),\n    rect({\n      x: x.quantile(0.975),\n      w: 1,\n      h: x.density(x.quantile(0.975)),\n    }),\n  ])\n);\n// mode and hdi\nconst hdi = chart([{}]).mark(\n  layer([\n    // gap: the mode and the highest-density interval,\n    // written as the helper they would most likely be\n    // the whole curve\n    slab(x, { fill: \"#deebf7\" }),\n    // the curve cut to the 95% highest-density interval\n    slab(x, {\n      fill: \"#9ecae1\",\n      curve: (c, rows) => {\n        const [hdi] = highestDensityIntervals(rows, x, [\n          0.95,\n        ]);\n        return c.filter(\n          (r) => Math.abs(r.v - hdi.center) <= hdi.size / 2\n        );\n      },\n    }),\n    // the curve cut to the 50% highest-density interval\n    slab(x, {\n      fill: \"#3182bd\",\n      curve: (c, rows) => {\n        const [hdi] = highestDensityIntervals(rows, x, [\n          0.5,\n        ]);\n        return c.filter(\n          (r) => Math.abs(r.v - hdi.center) <= hdi.size / 2\n        );\n      },\n    }),\n    // spikes at the mode and the ends of the 95% hdi\n    rect({ x: x.mode(), w: 1, h: x.density(x.mode()) }),\n    rect({\n      x: x.hdi(0.95)[0],\n      w: 1,\n      h: x.density(x.hdi(0.95)[0]),\n    }),\n    rect({\n      x: x.hdi(0.95)[1],\n      w: 1,\n      h: x.density(x.hdi(0.95)[1]),\n    }),\n  ])\n);\nspread({ dir: \"y\", spacing: 16 }, [qi, hdi]);","uses_up":"the density curve, the median and quantiles of the draws per cell","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A spike is a 1 px rect from 0 to the density at a point, so it shares the slab's size scale. Missing: the mode and HDI summaries (entry 30), and linetype mapped from a field (strokeDasharray is a literal).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk halfeye_qi_vs_hdi_spikes --\nqi_plot_spikes = data.frame(dist = dist_beta(10, 2)) %>%\n  ggplot(aes(xdist = dist)) +\n  stat_slab(aes(fill = after_stat(level)), point_interval = median_qi, .width = c(.5, .95)) +\n  # stat_spike(at = c(median, qi)) would also work, but this demonstrates how\n  # to re-label the names of the `at` computed variable and use it in an\n  # aesthetic mapping by mapping it to `linetype`\n  stat_spike(aes(linetype = after_stat(at)), at = c(\"median\", \"interval (qi)\" = qi)) +\n  scale_fill_brewer(na.value = \"gray95\") +\n  scale_thickness_shared() +\n  labs(subtitle = \"stat_slab() + stat_spike(at = c(median, qi))\")\n\nhdi_plot_spikes = data.frame(dist = dist_beta(10, 2)) %>%\n  ggplot(aes(xdist = dist)) +\n  stat_slab(aes(fill = after_stat(level)), point_interval = mode_hdi, .width = c(.5, .95)) +\n  stat_spike(aes(linetype = after_stat(at)), at = c(\"mode\" = Mode, \"interval (hdi)\" = hdi)) +\n  scale_fill_brewer(na.value = \"gray95\") +\n  scale_thickness_shared() +\n  labs(subtitle = \"stat_slab() + stat_spike(at = c(Mode, hdi))\")\n\nqi_plot_spikes /\n  hdi_plot_spikes"},{"id":"ggdist-32-halfeye-filled-intervals-subgroup","pkg":"ggdist","num":"32","title":"stat_halfeye(position = 'dodgejust'), fill = subgroup, fill_ramp = level","source":"slabinterval vignette, chunk halfeye_filled_intervals_subgroup","img":"catalog/img/ggdist-32-halfeye-filled-intervals-subgroup.png","more":[],"gofish":"chart(df)\n  .flow(\n    spread({ by: \"group\", dir: \"y\" }),\n    spread({ by: \"subgroup\", dir: \"y\" })\n  )\n  .mark(\n    layer([\n      // gap: fill_ramp, the subgroup's color lightened by level\n      // the curve cut to the central 95% interval\n      slab(\"value\", {\n        fill: \"subgroup\",\n        curve: (c) =>\n          c.filter(\n            (r) => Math.abs(r.cdf - 0.5) <= 0.95 / 2\n          ),\n      }),\n      // the curve cut to the central 80% interval\n      slab(\"value\", {\n        fill: \"subgroup\",\n        curve: (c) =>\n          c.filter((r) => Math.abs(r.cdf - 0.5) <= 0.8 / 2),\n      }),\n      // the curve cut to the central 50% interval\n      slab(\"value\", {\n        fill: \"subgroup\",\n        curve: (c) =>\n          c.filter((r) => Math.abs(r.cdf - 0.5) <= 0.5 / 2),\n      }),\n      interval(\"value\"),\n    ])\n  );","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The geometry fits as nested slabs. Missing: fill_ramp, a color scale on subgroup lightened by a second field (level); Color.mix exists but no scale combines two fields.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk halfeye_filled_intervals_subgroup --\ndf %>%\n  ggplot(aes(y = group, x = value)) +\n  stat_halfeye(\n    aes(fill = subgroup, fill_ramp = after_stat(level)),\n    .width = c(.50, .80, .95),\n    # NOTE: we use position = \"dodgejust\" (a dodge that respects the\n    # justification of intervals relative to slabs) instead of\n    # position = \"dodge\" here because it ensures the topmost slab does\n    # not extend beyond the plot limits\n    position = \"dodgejust\"\n  ) +\n  # a range from 1 down to 0.2 ensures the fill goes dark to light inside-out\n  # and doesn't get all the way down to white (0) on the lightest color\n  scale_fill_ramp_discrete(na.translate = FALSE) +\n  labs(\n    title = \"stat_halfeye(position = 'dodgejust')\",\n    subtitle = \"aes(fill = subgroup, fill_ramp = after_stat(level))\",\n    fill_ramp = \"interval\"\n  )"},{"id":"ggdist-33-dist-interval-color-ramp","pkg":"ggdist","num":"33","title":"stat_interval(aes(color = subgroup, color_ramp = after_stat(level)), position = 'dodge')","source":"slabinterval vignette, chunk dist_interval_color_ramp","img":"catalog/img/ggdist-33-dist-interval-color-ramp.png","more":[],"gofish":"const y = dist.normal({ mean: \"mean\", sd: \"sd\" });\nchart(distDf)\n  .flow(\n    spread({ by: \"group\", dir: \"x\" }),\n    spread({ by: \"subgroup\", dir: \"x\" })\n  )\n  .mark(\n    layer([\n      // gap: color_ramp, the subgroup's color lightened by\n      // level\n      interval(y, {\n        levels: [0.95, 0.8, 0.5],\n        dir: \"y\",\n        point: false,\n        fill: \"subgroup\",\n        w: 4,\n      }),\n    ])\n  );","uses_up":"quantiles and the median of the draws per cell","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Nested intervals are central intervals of the draws. Missing: color_ramp, the subgroup color lightened by level (as in entry 32).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk dist_data --\ndist_df = tribble(\n  ~group, ~subgroup, ~mean, ~sd,\n  \"a\",          \"h\",     5,   1,\n  \"b\",          \"h\",     7,   1.5,\n  \"c\",          \"h\",     8,   1,\n  \"c\",          \"i\",     9,   1,\n  \"c\",          \"j\",     7,   1\n)\n# -- chunk dist_interval_color_ramp --\ndist_df %>%\n  ggplot(aes(x = group, ydist = dist_normal(mean, sd), color = subgroup)) +\n  stat_interval(aes(color_ramp = after_stat(level)), position = \"dodge\") +\n  labs(\n    title = \"stat_interval()\",\n    subtitle = \"aes(color = subgroup, color_ramp = after_stat(level))\"\n  )"},{"id":"ggdist-34-raindrop","pkg":"ggdist","num":"34","title":"Raindrop: stat_eye with thickness = log(pdf) inside the 95% and 99% intervals","source":"slabinterval vignette, chunk raindrop","img":"catalog/img/ggdist-34-raindrop.png","more":[],"gofish":"chart(priors)\n  .flow(spread({ by: \"label\", dir: \"y\" }))\n  .mark(\n    layer([\n      // raindrop: log(pdf) inside the 99% interval\n      slab(\"dist\", {\n        side: \"both\",\n        fill: \"gray85\",\n        curve: (c) => {\n          const k = c\n            .filter(\n              (r) => Math.abs(r.cdf - 0.5) <= 0.99 / 2\n            )\n            .map((r) => ({\n              ...r,\n              density: Math.log(r.density),\n            }));\n          const lo = Math.min(...k.map((r) => r.density));\n          const hi = Math.max(...k.map((r) => r.density));\n          return k.map((r) => ({\n            ...r,\n            density: (r.density - lo) / (hi - lo),\n          }));\n        },\n      }),\n      // and inside the 95% interval\n      slab(\"dist\", {\n        side: \"both\",\n        curve: (c) => {\n          const k = c\n            .filter(\n              (r) => Math.abs(r.cdf - 0.5) <= 0.95 / 2\n            )\n            .map((r) => ({\n              ...r,\n              density: Math.log(r.density),\n            }));\n          const lo = Math.min(...k.map((r) => r.density));\n          const hi = Math.max(...k.map((r) => r.density));\n          return k.map((r) => ({\n            ...r,\n            density: (r.density - lo) / (hi - lo),\n          }));\n        },\n      }),\n      // gap: this should sit on the slab's zero line, but a\n      // layer aligns its children's boxes, not their\n      // origins\n      interval(\"dist\"),\n    ])\n  );","uses_up":"the density curve of the draws per cell, turned into thickness log(pdf) and cut to an interval by quantiles of the draws","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Any function of the density is arithmetic on the density curve's rows. log(pdf) shifted so the interval's edges are at 0 and its peak at 1 is what normalize = 'groups' does. The eye shape has entry 4's gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 23 --\npriors = tibble(\n  dist = c(dist_normal(0, 1), dist_student_t(3, 0, 1))\n)\n\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  stat_halfeye(aes(fill = after_stat(abs(x) < 1.5))) +\n  ggtitle(\"stat_halfeye()\", \"aes(fill = after_stat(abs(x) < 1.5)))\") +\n  # we'll use a nicer palette than the default for highlighting:\n  scale_fill_manual(values = c(\"gray85\", \"skyblue\"))\n# -- chunk raindrop --\npriors %>%\n  ggplot(aes(y = format(dist), xdist = dist)) +\n  # must also use normalize = \"groups\" because min(log(pdf)) will be different for each dist\n  stat_slab(\n    aes(thickness = after_stat(ifelse(.width <= 0.99, log(pdf), NA))),\n    normalize = \"groups\", fill = \"gray85\", .width = .99, side = \"both\"\n  ) +\n  stat_eye(\n    aes(thickness = after_stat(ifelse(.width <= 0.95, log(pdf), NA))),\n    normalize = \"groups\"\n  ) +\n  ggtitle(\n    'stat_eye(normalize = \"groups\")',\n    paste0(\n      \"with aes(thickness = after_stat(ifelse(.width <= 0.95, log(pdf), NA)))\\n\",\n      \"and aes(thickness = after_stat(ifelse(.width <= 0.99, log(pdf), NA)))\"\n    )\n  )"},{"id":"ggdist-35-slab-ridge","pkg":"ggdist","num":"35","title":"Ridgeline: stat_slab(height = 2, color = 'black')","source":"slabinterval vignette, chunk slab_ridge","img":"catalog/img/ggdist-35-slab-ridge.png","more":[],"gofish":"chart(ridgesDf)\n  .flow(\n    spread({\n      by: \"group\",\n      dir: \"y\",\n      anchor: \"baseline\",\n      spacing: 24,\n    })\n  )\n  .mark(layer({ h: 60 }, [slab(\"x\", { stroke: \"black\" })]));","uses_up":"the density curve of the draws per cell (exact on a Dist; a kernel estimate over the rows on a sample)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Overlapping ridges are a baseline spread with a fixed pitch and slabs taller than the pitch, as in GoFish's Ridgeline Chart story.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk slab_ridge --\nset.seed(1234)\n\nridges_df = data.frame(\n  group = letters[7:1],\n  x = rnorm(700, mean = 1:7, sd = 2)\n)\n\nridges_df %>%\n  ggplot(aes(y = group, x = x)) +\n  stat_slab(height = 2, color = \"black\") +\n  ggtitle(\"stat_slab(height = 2, color = 'black')\")"},{"id":"ggdist-36-slab-ridge-ramp","pkg":"ggdist","num":"36","title":"Ridgeline with fill = group, fill_ramp = abs(x), color_ramp = -dnorm(x, 0, 2)","source":"slabinterval vignette, chunk slab_ridge_ramp","img":"catalog/img/ggdist-36-slab-ridge-ramp.png","more":[],"gofish":"chart(ridgesDf, { color: Color.palette(\"viridis\") })\n  .flow(\n    spread({\n      by: \"group\",\n      dir: \"y\",\n      anchor: \"baseline\",\n      spacing: 24,\n    })\n  )\n  .mark(\n    layer({ h: 60 }, [\n      // expand = TRUE: the curve runs over the x axis's\n      // limits, set by hand. gap: fill_ramp and color_ramp\n      // along x\n      slab(\"x\", {\n        fill: \"group\",\n        density: { range: [-6, 14] },\n      }),\n    ])\n  )\n  .layer(\n    chart([{ x: 0 }]).mark(\n      rect({ x: \"x\", w: 1, strokeDasharray: \"4 3\" })\n    )\n  );","uses_up":"the density curve of the draws per cell (exact on a Dist; a kernel estimate over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The ridges fit. Missing: a fill and an outline color that change along one ribbon (fill_ramp by |x| and color_ramp by a density), which needs a gradient along a mark.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 35 --\nset.seed(1234)\n\nridges_df = data.frame(\n  group = letters[7:1],\n  x = rnorm(700, mean = 1:7, sd = 2)\n)\n\nridges_df %>%\n  ggplot(aes(y = group, x = x)) +\n  stat_slab(height = 2, color = \"black\") +\n  ggtitle(\"stat_slab(height = 2, color = 'black')\")\n# -- chunk slab_ridge_ramp --\nridges_df %>%\n  ggplot(aes(\n    y = group, x = x,\n    fill = group, fill_ramp = after_stat(abs(x)),\n    color_ramp = after_stat(-dnorm(x, 0, 2))\n  )) +\n  stat_slab(\n    height = 2, color = \"gray15\",\n    expand = TRUE, trim = FALSE, density = \"unbounded\",\n    fill_type = \"gradient\",\n    show.legend = FALSE\n  ) +\n  geom_vline(xintercept = 0, color = \"gray85\", linetype = \"dashed\") +\n  ggtitle(\n    'stat_slab(height = 2, color = \"black\", expand = TRUE, trim = FALSE)',\n    'aes(fill = group, fill_ramp = after_stat(abs(x)), color_ramp = after_stat(-dnorm(x, 0, 2)))'\n  ) +\n  scale_fill_viridis_d()"},{"id":"ggdist-37-varying-side-dotplot","pkg":"ggdist","num":"37","title":"stat_dotsinterval with side = top / both / bottom per row","source":"slabinterval vignette, chunk varying_side_dotplot","img":"catalog/img/ggdist-37-varying-side-dotplot.png","more":[],"gofish":"const x = dist.normal({ mean: \"mean\", sd: \"sd\" });\nconst cells = distDf.filter((d) => d.subgroup === \"h\");\nconst dots = sample(cells, { n: 100, at: \"quantiles\" });\nspread({ dir: \"y\", spacing: 20 }, [\n  // a\n  layer([\n    chart(dots.filter((d) => d.group === \"a\"))\n      .flow(\n        partition({\n          by: x.bin(Bin.step(0.2)), // chosen by hand; ggdist picks the width so the tallest stack fits\n          dir: \"x\",\n          alignment: \"end\",\n        }),\n        stack({ dir: \"y\" })\n      )\n      .mark(circle({ r: 2 })),\n    chart(cells.filter((d) => d.group === \"a\")).mark(\n      interval(x)\n    ),\n  ]),\n  // b\n  layer([\n    chart(dots.filter((d) => d.group === \"b\"))\n      .flow(\n        partition({\n          by: x.bin(Bin.step(0.2)), // chosen by hand; ggdist picks the width so the tallest stack fits\n          dir: \"x\",\n          alignment: \"middle\",\n        }),\n        stack({ dir: \"y\" })\n      )\n      .mark(circle({ r: 2 })),\n    chart(cells.filter((d) => d.group === \"b\")).mark(\n      layer([\n        // gap: this should sit on the slab's zero line, but\n        // a layer aligns its children's boxes, not their\n        // origins\n        interval(x),\n      ])\n    ),\n  ]),\n  // c\n  layer([\n    chart(dots.filter((d) => d.group === \"c\"))\n      .flow(\n        partition({\n          by: x.bin(Bin.step(0.2)), // chosen by hand; ggdist picks the width so the tallest stack fits\n          dir: \"x\",\n          alignment: \"start\",\n        }),\n        stack({ dir: \"y\" })\n      )\n      .mark(circle({ r: 2 })),\n    chart(cells.filter((d) => d.group === \"c\")).mark(\n      layer([\n        // gap: this should sit on the slab's zero line, but\n        // a layer aligns its children's boxes, not their\n        // origins\n        interval(x),\n      ])\n    ),\n  ]),\n]);","uses_up":"sample(data, { n: 100, at: \"quantiles\" }), then partition by a bin and stack (finite n); the interval is quantiles and the median of the draws on the Dist","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Quantile dots of a Dist are sample at evenly spaced levels, which version 1 needed a derive for. Side as data (one value per row) is not a channel in GoFish, so each row is its own chart. The both and bottom rows need the interval on the dots' baseline (entry 4's gap), plus the dot-binning gap of entry 20.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk dist_data --\ndist_df = tribble(\n  ~group, ~subgroup, ~mean, ~sd,\n  \"a\",          \"h\",     5,   1,\n  \"b\",          \"h\",     7,   1.5,\n  \"c\",          \"h\",     8,   1,\n  \"c\",          \"i\",     9,   1,\n  \"c\",          \"j\",     7,   1\n)\n# -- chunk varying_side_dotplot --\ndist_df %>%\n  filter(subgroup == \"h\") %>%\n  mutate(side = c(\"top\", \"both\", \"bottom\")) %>%\n  ggplot(aes(y = group, xdist = dist_normal(mean, sd), side = side)) +\n  stat_dotsinterval(scale = 2/3) +\n  labs(\n    title = 'stat_dotsinterval(scale = 2/3)',\n    subtitle = 'aes(xdist = dist_normal(mean, sd), side = c(\"top\",\"both\",\"bottom\"))'\n  ) +\n  coord_cartesian()"},{"id":"ggdist-38-halfeye-quantile-dotplot","pkg":"ggdist","num":"38","title":"stat_slab(side = 'left') + stat_dotsinterval(quantiles = 100) + labels, dodged","source":"slabinterval vignette, chunk halfeye_quantile_dotplot","img":"catalog/img/ggdist-38-halfeye-quantile-dotplot.png","more":[],"gofish":"const value = field(\"value\");\nconst drawn = withDraw(df);\nlayer([\n  chart(df)\n    .flow(\n      spread({ by: \"group\", dir: \"x\" }),\n      spread({ by: \"subgroup\", dir: \"x\" })\n    )\n    .mark(\n      layer([\n        slab(\"value\", {\n          dir: \"y\",\n          side: \"start\",\n          fill: \"subgroup\",\n        }),\n        // gap: this should sit on the slab's zero line, but\n        // a layer aligns its children's boxes, not their\n        // origins\n        interval(\"value\", { dir: \"y\" }),\n        text({ y: value.median(), text: \"label\" }),\n      ])\n    ),\n  // 100 quantile dots of each cell's 1000 rows: every 10th rank\n  chart(drawn, { schema: { value: { draws: \"draw\" } } })\n    .flow(\n      spread({ by: \"group\", dir: \"x\" }),\n      spread({ by: \"subgroup\", dir: \"x\" }),\n      filter(\n        (d) => Math.round(d.level * 1000 + 0.5) % 10 === 5\n      ),\n      partition({\n        by: value.bin(Bin.step(0.15)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"y\",\n      }),\n      stack({ dir: \"x\" })\n    )\n    .mark(circle({ r: 1.5, fill: \"subgroup\" })),\n]);","uses_up":"slab and label: the density curve and the median of the draws; dots: a filter on level keeps 100 of 1000 rows, then partition and stack","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A left slab and right dots share one center line, which needs the layer to align children by origin (entry 4's gap), plus the dot-binning gap. The label at the median is a text mark at the median of the draws. The dots thin a sample to 100 quantiles with a filter on level, as in entry 21.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk halfeye_quantile_dotplot --\ndf %>%\n  ggplot(aes(x = group, y = value, fill = subgroup)) +\n  stat_slab(side = \"left\", scale = 0.5, position = \"dodge\") +\n  stat_dotsinterval(scale = 0.5, quantiles = 100, position = \"dodge\") +\n  stat_pointinterval(\n    geom = \"label\",\n    aes(label = paste0(group, subgroup)),\n    .width = .5,  # set to a scalar to draw only one label instead of two\n    position = position_dodge(width = 1),\n    size = 3.5\n  ) +\n  labs(title = paste0(\n    'stat_halfeye(side = \"left\") +\\n',\n    'stat_dotsinterval(quantiles = 100) +\\n',\n    'stat_pointinterval(geom = \"label\")'\n  ))"},{"id":"ggdist-39-slab-and-pointinterval","pkg":"ggdist","num":"39","title":"stat_slab(alpha = .3) overplotted + stat_pointinterval with position_dodgejust","source":"slabinterval vignette, chunk slab_and_pointinterval","img":"catalog/img/ggdist-39-slab-and-pointinterval.png","more":[],"gofish":"layer([\n  chart(df)\n    // one slab per group, overplotted\n    .flow(group({ by: \"group\" }))\n    .mark(slab(\"value\", { fill: \"group\", opacity: 0.3 })),\n  chart(df)\n    .flow(\n      spread({\n        by: \"group\",\n        dir: \"y\",\n        spacing: 4,\n      }).translate({ y: -12 })\n    )\n    .mark(interval(\"value\", { fill: \"group\" })),\n]);","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The overlaid slabs fit. The dodged intervals sit just below the shared baseline, which is the raincloud placement elaborations.md could not express (a layer aligns boxes, not the slab's zero line).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk sample_data --\nset.seed(1234)\ndf = tribble(\n  ~group, ~subgroup, ~value,\n  \"a\",          \"h\", rnorm(1000, mean = 5),\n  \"b\",          \"h\", rnorm(1000, mean = 7, sd = 1.5),\n  \"c\",          \"h\", rnorm(1000, mean = 8),\n  \"c\",          \"i\", rnorm(1000, mean = 9),\n  \"c\",          \"j\", rnorm(1000, mean = 7)\n) %>%\n  unnest(value)\n# -- chunk slab_and_pointinterval --\ndf %>%\n  ggplot(aes(fill = group, color = group, x = value)) +\n  stat_slab(alpha = .3) +\n  stat_pointinterval(position = position_dodgejust(width = .2), justification = 0.1) +\n  labs(\n    title = \"stat_slab() and stat_pointinterval()\",\n    subtitle = \"with position_dodgejust() applied to the intervals\",\n    y = NULL\n  ) +\n  scale_y_continuous(breaks = NULL)"},{"id":"ggdist-40-dotsinterval-components","pkg":"ggdist","num":"40","title":"Properties of geom_dotsinterval (annotated diagram)","source":"dotsinterval vignette, chunk dotsinterval_components","img":"catalog/img/ggdist-40-dotsinterval-components.png","more":[],"gofish":"const x = dist.normal({ mean: 4, sd: 1.2 });\nconst cell = [{}];\nlayer([\n  chart(sample(cell, { n: 100, at: \"quantiles\" }))\n    .flow(\n      partition({ by: x.bin(Bin.step(0.25)), dir: \"x\" }), // chosen by hand; ggdist picks the width so the tallest stack fits\n      stack({ dir: \"y\" })\n    )\n    .mark(\n      circle({ r: 3, fill: \"gray75\", stroke: \"gray50\" })\n    ),\n  chart(cell).mark(\n    layer([\n      // gap: a square point shape\n      interval(x, { levels: [0.6827], h: 5 }),\n    ])\n  ),\n])\n  .layer(\n    chart(annotations).mark(\n      text({\n        x: \"x\",\n        y: \"y\",\n        text: \"label\",\n        fill: \"#d95f02\",\n      })\n    )\n  )\n  .layer(chart(arrows).mark(arrow({ fill: \"#d95f02\" })));","uses_up":"sample(data, { n: 100, at: \"quantiles\" }), then partition by a bin and stack (finite n); the interval is quantiles and the median of the draws","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Quantile dots plus an interval. Missing: the dot-binning gap of entry 20, bracket-ended annotation segments (entry 2), and a square point shape.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk dotsinterval_components --\nred_ = \"#d95f02\"\ngreen_ = \"#1b9e77\"\nblue_ = \"#7570b3\"\n\nbracket_ = function(..., x, xend = x, y, yend = y, color = red_) {\n  annotate(\"segment\",\n    arrow = arrow(angle = 90, ends = \"both\", length = unit(3, \"points\")),\n    color = color, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nthickness_ = function(x) dnorm(x,4,1) * 0.9 / dnorm(4,4,1)\nrefline_ = function(..., x, xend = x, y, yend = y, color = red_, linetype = \"solid\", alpha = 0.5) {\n  annotate(\"segment\",\n    color = color, linetype = linetype, alpha = alpha, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nlabel_ = function(..., hjust = 0, color = red_) {\n  annotate(\"text\",\n    color = color, hjust = hjust, lineheight = 1,\n    size = 3.25,\n    ...\n  )\n}\narrow_ = function(..., curvature = 0, x, xend = x, y, yend = y) {\n  annotate(\"curve\",\n    color = red_, arrow = arrow(angle = 45, length = unit(3, \"points\"), type = \"closed\"),\n    curvature = curvature,\n    x = x, xend = xend, y = y, yend = yend\n  )\n}\n\n\ntibble(dist = dist_normal(4, 1.2)) %>%\n  ggplot(aes(y = 0, xdist = dist)) +\n\n  geom_hline(yintercept = 0:1, color = \"gray95\") +\n\n  stat_dotsinterval(\n    aes(linewidth = NULL),\n    slab_color = \"gray50\",\n    .width = 1 - 2*pnorm(-1, sd = 1.2),\n    fill = \"gray75\",\n    point_size = 5,\n    shape = 22,\n    slab_shape = 21,\n    stroke = 1.5,\n    linewidth = 5,\n    slab_linewidth = 1.5\n  ) +\n\n  # height\n  refline_(x = 0, xend = 8.4, y = 1) +\n  bracket_(x = 8.4, y = 0, yend = 1) +\n  label_(label = \"height\", x = 8.6, y = 1) +\n\n  # scale\n  refline_(x = 4, xend = 8.6, y = 0.9) +\n  bracket_(x = 8.6, y = 0, yend = 0.9) +\n  label_(label = \"scale = 0.9\", x = 8.8, y = 0.9) +\n\n  # slab line properties\n  label_(x = 2.5, y = 0.7,\n    label = 'slab_color = \"gray50\"\\nslab_linewidth = 1.5',\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 2.52, xend = 3, y = 0.67, yend = thickness_(3.1) + 0.03, curvature = -0.2) +\n\n  # slab fill\n  label_(x = 5.5, y = 0.7,\n    label = 'slab_fill = fill = \"gray75\"\\nslab_alpha = alpha = 1\\nslab_shape = 21',\n    vjust = 1\n  ) +\n  arrow_(x = 5.48, xend = 4.81, y = 0.67, yend = thickness_(3.1) + 0.01, curvature = 0.2) +\n\n  # xmin, x, xmax\n  arrow_(x = 2.65, xend = 3, y = -0.1, yend = -0.01, curvature = -0.2) +\n  label_(x = 2.7, y = -0.1, label = \"xmin\", hjust = 1, vjust = 1) +\n  arrow_(x = 4, y = -0.1, yend = -0.05) +\n  label_(x = 4, y = -0.1, label = \"x\", hjust = 0.5, vjust = 1) +\n  arrow_(x = 5.35, xend = 5, y = -0.1, yend = -0.01, curvature = 0.2) +\n  label_(x = 5.3, y = -0.1, label = \"xmax\", hjust = 0, vjust = 1) +\n\n  # interval properties\n  label_(x = 3.5, y = -0.2,\n    label = paste0(\n      'interval_color = color = \"black\"\\n',\n      'interval_alpha = alpha = 1\\n',\n      'interval_linetype = linetype = \"solid\"\\n',\n      'linewidth = size = 5'\n    ),\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 3.3, xend = 3.4, y = -0.18, yend = -0.015, curvature = -0.1) +\n\n  # point properties\n  label_(x = 4.5, y = -0.2,\n    label = paste0(\n      'point_fill = fill = \"gray75\"\\n',\n      'point_color = color = \"black\"\\n',\n      'point_alpha = alpha = 1\\n',\n      'point_size = size = 5\\nshape = 22\\nstroke = 1.5'\n    ),\n    vjust = 1, hjust = 0\n  ) +\n  arrow_(x = 4.55, xend = 4.2, y = -0.18, yend = -0.03, curvature = 0.2) +\n\n  coord_cartesian(xlim = c(-1, 10), ylim = c(-0.6, 1)) +\n  labs(subtitle = \"Properties of geom_dotsinterval\", x = NULL, y = NULL)"},{"id":"ggdist-41-dots-components","pkg":"ggdist","num":"41","title":"Properties of geom_dots (annotated diagram)","source":"dotsinterval vignette, chunk dots_components","img":"catalog/img/ggdist-41-dots-components.png","more":[],"gofish":"const x = dist.normal({ mean: 4, sd: 1.2 });\nchart(sample([{}], { n: 100, at: \"quantiles\" }))\n  .flow(\n    partition({ by: x.bin(Bin.step(0.25)), dir: \"x\" }), // chosen by hand; ggdist picks the width so the tallest stack fits\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 3, fill: \"gray75\", stroke: \"gray50\" }))\n  .layer(\n    chart(annotations).mark(\n      text({\n        x: \"x\",\n        y: \"y\",\n        text: \"label\",\n        fill: \"#d95f02\",\n      })\n    )\n  )\n  .layer(chart(arrows).mark(arrow({ fill: \"#d95f02\" })));","uses_up":"sample(data, { n: 100, at: \"quantiles\" }), then partition by a bin and stack (finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"As entry 40 without the interval.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 40 --\nred_ = \"#d95f02\"\ngreen_ = \"#1b9e77\"\nblue_ = \"#7570b3\"\n\nbracket_ = function(..., x, xend = x, y, yend = y, color = red_) {\n  annotate(\"segment\",\n    arrow = arrow(angle = 90, ends = \"both\", length = unit(3, \"points\")),\n    color = color, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nthickness_ = function(x) dnorm(x,4,1) * 0.9 / dnorm(4,4,1)\nrefline_ = function(..., x, xend = x, y, yend = y, color = red_, linetype = \"solid\", alpha = 0.5) {\n  annotate(\"segment\",\n    color = color, linetype = linetype, alpha = alpha, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nlabel_ = function(..., hjust = 0, color = red_) {\n  annotate(\"text\",\n    color = color, hjust = hjust, lineheight = 1,\n    size = 3.25,\n    ...\n  )\n}\narrow_ = function(..., curvature = 0, x, xend = x, y, yend = y) {\n  annotate(\"curve\",\n    color = red_, arrow = arrow(angle = 45, length = unit(3, \"points\"), type = \"closed\"),\n    curvature = curvature,\n    x = x, xend = xend, y = y, yend = yend\n  )\n}\n\n\ntibble(dist = dist_normal(4, 1.2)) %>%\n  ggplot(aes(y = 0, xdist = dist)) +\n\n  geom_hline(yintercept = 0:1, color = \"gray95\") +\n\n  stat_dotsinterval(\n    aes(linewidth = NULL),\n    slab_color = \"gray50\",\n    .width = 1 - 2*pnorm(-1, sd = 1.2),\n    fill = \"gray75\",\n    point_size = 5,\n    shape = 22,\n    slab_shape = 21,\n    stroke = 1.5,\n    linewidth = 5,\n    slab_linewidth = 1.5\n  ) +\n\n  # height\n  refline_(x = 0, xend = 8.4, y = 1) +\n  bracket_(x = 8.4, y = 0, yend = 1) +\n  label_(label = \"height\", x = 8.6, y = 1) +\n\n  # scale\n  refline_(x = 4, xend = 8.6, y = 0.9) +\n  bracket_(x = 8.6, y = 0, yend = 0.9) +\n  label_(label = \"scale = 0.9\", x = 8.8, y = 0.9) +\n\n  # slab line properties\n  label_(x = 2.5, y = 0.7,\n    label = 'slab_color = \"gray50\"\\nslab_linewidth = 1.5',\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 2.52, xend = 3, y = 0.67, yend = thickness_(3.1) + 0.03, curvature = -0.2) +\n\n  # slab fill\n  label_(x = 5.5, y = 0.7,\n    label = 'slab_fill = fill = \"gray75\"\\nslab_alpha = alpha = 1\\nslab_shape = 21',\n    vjust = 1\n  ) +\n  arrow_(x = 5.48, xend = 4.81, y = 0.67, yend = thickness_(3.1) + 0.01, curvature = 0.2) +\n\n  # xmin, x, xmax\n  arrow_(x = 2.65, xend = 3, y = -0.1, yend = -0.01, curvature = -0.2) +\n  label_(x = 2.7, y = -0.1, label = \"xmin\", hjust = 1, vjust = 1) +\n  arrow_(x = 4, y = -0.1, yend = -0.05) +\n  label_(x = 4, y = -0.1, label = \"x\", hjust = 0.5, vjust = 1) +\n  arrow_(x = 5.35, xend = 5, y = -0.1, yend = -0.01, curvature = 0.2) +\n  label_(x = 5.3, y = -0.1, label = \"xmax\", hjust = 0, vjust = 1) +\n\n  # interval properties\n  label_(x = 3.5, y = -0.2,\n    label = paste0(\n      'interval_color = color = \"black\"\\n',\n      'interval_alpha = alpha = 1\\n',\n      'interval_linetype = linetype = \"solid\"\\n',\n      'linewidth = size = 5'\n    ),\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 3.3, xend = 3.4, y = -0.18, yend = -0.015, curvature = -0.1) +\n\n  # point properties\n  label_(x = 4.5, y = -0.2,\n    label = paste0(\n      'point_fill = fill = \"gray75\"\\n',\n      'point_color = color = \"black\"\\n',\n      'point_alpha = alpha = 1\\n',\n      'point_size = size = 5\\nshape = 22\\nstroke = 1.5'\n    ),\n    vjust = 1, hjust = 0\n  ) +\n  arrow_(x = 4.55, xend = 4.2, y = -0.18, yend = -0.03, curvature = 0.2) +\n\n  coord_cartesian(xlim = c(-1, 10), ylim = c(-0.6, 1)) +\n  labs(subtitle = \"Properties of geom_dotsinterval\", x = NULL, y = NULL)\n# -- chunk dots_components --\ntibble(dist = dist_normal(4, 1.2)) %>%\n  ggplot(aes(y = 0, xdist = dist)) +\n\n  geom_hline(yintercept = 0:1, color = \"gray95\") +\n\n  stat_dots(\n    aes(linewidth = NULL),\n    color = \"gray50\",\n    fill = \"gray75\",\n    linewidth = 1.5,\n    shape = 21\n  ) +\n\n  # height\n  refline_(x = 0, xend = 8.4, y = 1) +\n  bracket_(x = 8.4, y = 0, yend = 1) +\n  label_(label = \"height\", x = 8.6, y = 1) +\n\n  # scale\n  refline_(x = 4, xend = 8.6, y = 0.9) +\n  bracket_(x = 8.6, y = 0, yend = 0.9) +\n  label_(label = \"scale = 0.9\", x = 8.8, y = 0.9) +\n\n  # slab line properties\n  label_(x = 2.5, y = 0.7,\n    label = 'color = \"gray50\"\\nlinewidth = 1.5',\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 2.52, xend = 3, y = 0.67, yend = thickness_(3.1) + 0.03, curvature = -0.2) +\n\n  # slab fill\n  label_(x = 5.5, y = 0.7,\n    label = 'fill = \"gray75\"\\nalpha = 1\\nshape = 21',\n    vjust = 1\n  ) +\n  arrow_(x = 5.48, xend = 4.81, y = 0.67, yend = thickness_(3.1) + 0.01, curvature = 0.2) +\n\n  coord_cartesian(xlim = c(-1, 10), ylim = c(-0.05, 1)) +\n  labs(subtitle = \"Properties of geom_dots\", x = NULL, y = NULL)"},{"id":"ggdist-42-layout-params","pkg":"ggdist","num":"42","title":"Layout parameters for dots geoms (annotated diagram)","source":"dotsinterval vignette, chunk layout_params","img":"catalog/img/ggdist-42-layout-params.png","more":[],"gofish":"chart([\n  { x: 0.4 },\n  { x: 0.7 },\n  { x: 0.7 },\n  { x: 1 },\n  { x: 1 },\n  { x: 1 },\n])\n  .flow(\n    partition({\n      by: field(\"x\").bin(Bin.step(0.3)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"x\",\n    }),\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 15, opacity: 0.5 }))\n  .layer(\n    chart(annotations).mark(\n      text({ x: \"x\", y: \"y\", text: \"label\" })\n    )\n  )\n  .layer(chart(brackets).mark(arrow({})));","uses_up":"six plain values as finite draws: partition by a bin, then stack","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The diagram explains the automatic bin width (0.3, chosen so the tallest stack fits in the height), which GoFish cannot choose, and uses bracket annotations and coord_fixed (equal units on both axes).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 40 --\nred_ = \"#d95f02\"\ngreen_ = \"#1b9e77\"\nblue_ = \"#7570b3\"\n\nbracket_ = function(..., x, xend = x, y, yend = y, color = red_) {\n  annotate(\"segment\",\n    arrow = arrow(angle = 90, ends = \"both\", length = unit(3, \"points\")),\n    color = color, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nthickness_ = function(x) dnorm(x,4,1) * 0.9 / dnorm(4,4,1)\nrefline_ = function(..., x, xend = x, y, yend = y, color = red_, linetype = \"solid\", alpha = 0.5) {\n  annotate(\"segment\",\n    color = color, linetype = linetype, alpha = alpha, linewidth = 0.75,\n    x = x, xend = xend, y = y, yend = yend,\n    ...\n  )\n}\nlabel_ = function(..., hjust = 0, color = red_) {\n  annotate(\"text\",\n    color = color, hjust = hjust, lineheight = 1,\n    size = 3.25,\n    ...\n  )\n}\narrow_ = function(..., curvature = 0, x, xend = x, y, yend = y) {\n  annotate(\"curve\",\n    color = red_, arrow = arrow(angle = 45, length = unit(3, \"points\"), type = \"closed\"),\n    curvature = curvature,\n    x = x, xend = xend, y = y, yend = yend\n  )\n}\n\n\ntibble(dist = dist_normal(4, 1.2)) %>%\n  ggplot(aes(y = 0, xdist = dist)) +\n\n  geom_hline(yintercept = 0:1, color = \"gray95\") +\n\n  stat_dotsinterval(\n    aes(linewidth = NULL),\n    slab_color = \"gray50\",\n    .width = 1 - 2*pnorm(-1, sd = 1.2),\n    fill = \"gray75\",\n    point_size = 5,\n    shape = 22,\n    slab_shape = 21,\n    stroke = 1.5,\n    linewidth = 5,\n    slab_linewidth = 1.5\n  ) +\n\n  # height\n  refline_(x = 0, xend = 8.4, y = 1) +\n  bracket_(x = 8.4, y = 0, yend = 1) +\n  label_(label = \"height\", x = 8.6, y = 1) +\n\n  # scale\n  refline_(x = 4, xend = 8.6, y = 0.9) +\n  bracket_(x = 8.6, y = 0, yend = 0.9) +\n  label_(label = \"scale = 0.9\", x = 8.8, y = 0.9) +\n\n  # slab line properties\n  label_(x = 2.5, y = 0.7,\n    label = 'slab_color = \"gray50\"\\nslab_linewidth = 1.5',\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 2.52, xend = 3, y = 0.67, yend = thickness_(3.1) + 0.03, curvature = -0.2) +\n\n  # slab fill\n  label_(x = 5.5, y = 0.7,\n    label = 'slab_fill = fill = \"gray75\"\\nslab_alpha = alpha = 1\\nslab_shape = 21',\n    vjust = 1\n  ) +\n  arrow_(x = 5.48, xend = 4.81, y = 0.67, yend = thickness_(3.1) + 0.01, curvature = 0.2) +\n\n  # xmin, x, xmax\n  arrow_(x = 2.65, xend = 3, y = -0.1, yend = -0.01, curvature = -0.2) +\n  label_(x = 2.7, y = -0.1, label = \"xmin\", hjust = 1, vjust = 1) +\n  arrow_(x = 4, y = -0.1, yend = -0.05) +\n  label_(x = 4, y = -0.1, label = \"x\", hjust = 0.5, vjust = 1) +\n  arrow_(x = 5.35, xend = 5, y = -0.1, yend = -0.01, curvature = 0.2) +\n  label_(x = 5.3, y = -0.1, label = \"xmax\", hjust = 0, vjust = 1) +\n\n  # interval properties\n  label_(x = 3.5, y = -0.2,\n    label = paste0(\n      'interval_color = color = \"black\"\\n',\n      'interval_alpha = alpha = 1\\n',\n      'interval_linetype = linetype = \"solid\"\\n',\n      'linewidth = size = 5'\n    ),\n    vjust = 1, hjust = 1\n  ) +\n  arrow_(x = 3.3, xend = 3.4, y = -0.18, yend = -0.015, curvature = -0.1) +\n\n  # point properties\n  label_(x = 4.5, y = -0.2,\n    label = paste0(\n      'point_fill = fill = \"gray75\"\\n',\n      'point_color = color = \"black\"\\n',\n      'point_alpha = alpha = 1\\n',\n      'point_size = size = 5\\nshape = 22\\nstroke = 1.5'\n    ),\n    vjust = 1, hjust = 0\n  ) +\n  arrow_(x = 4.55, xend = 4.2, y = -0.18, yend = -0.03, curvature = 0.2) +\n\n  coord_cartesian(xlim = c(-1, 10), ylim = c(-0.6, 1)) +\n  labs(subtitle = \"Properties of geom_dotsinterval\", x = NULL, y = NULL)\n# -- chunk layout_params --\ndata.frame(x = c(.4, .7, .7, 1, 1, 1)) %>%\n  ggplot(aes(x = x)) +\n\n  geom_hline(yintercept = 0:1, color = \"gray95\") +\n\n  # binwidth\n  refline_(x = seq(.25, 1.15, by = .3), y = -0.025, yend = 0.9, color = green_) +\n  bracket_(x = .25, xend = .55, y = -0.025, color = green_) +\n  label_(\n    label = \"binwidth = NA\\n=> binwidth = 0.3\\n(auto-selected so that\\n the tallest stack is \\u2264 scale)\",\n    x = 0.55, y = -0.08, vjust = 1, hjust = 1, color = green_\n  ) +\n\n  geom_dots(scale = 0.9, dotsize = 1, alpha = 0.5) +\n\n  # height\n  refline_(x = 0, xend = 2, y = 1) +\n  bracket_(x = 2, y = 0, yend = 1) +\n  label_(label = \"height\", x = 2.05, y = 1) +\n\n  # scale\n  refline_(x = 0.25, xend = 2.1, y = 0.9) +\n  bracket_(x = 2.1, y = 0, yend = 0.9) +\n  label_(label = \"scale = 0.9\", x = 2.15, y = 0.9) +\n\n  # stackratio\n  refline_(x = 1, xend = 1.3, y = c(.15, .45)) +\n  bracket_(x = 1.3, y = .15, yend = .45) +\n  label_(label = \"stackratio = 1\", x = 1.35, y = .3) +\n\n  # dotsize\n  refline_(x = c(.85, 1.15), y = 0.15, yend = -0.025, color = blue_, linetype = \"22\", alpha = 1) +\n  bracket_(x = .85, xend = 1.15, y = -0.025, color = blue_) +\n  label_(\n    label = \"dotsize = 1\\n(relative to binwidth)\",\n    x = 0.85, y = -0.08, vjust = 1, hjust = 0, color = blue_\n  ) +\n\n  scale_x_continuous(limits = c(-0.1, 2.35)) +\n  scale_y_continuous(limits = c(-0.35, 1)) +\n  coord_fixed() +\n  labs(subtitle = \"Layout parameters for dots geoms\", x = NULL, y = NULL)"},{"id":"ggdist-43-horizontal-side","pkg":"ggdist","num":"43","title":"Horizontal geom_dots() with side = topright / both / bottomleft","source":"dotsinterval vignette, chunk horizontal_side","img":"catalog/img/ggdist-43-horizontal-side.png","more":[],"gofish":"const panel = (alignment) =>\n  chart(xs)\n    .flow(\n      partition({\n        by: field(\"x\").bin(Bin.step(0.2)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"x\",\n        alignment,\n      }),\n      stack({ dir: \"y\" })\n    )\n    .mark(circle({ r: 3 }));\nspread({ dir: \"x\", spacing: 12 }, [\n  panel(\"end\"),\n  panel(\"middle\"),\n  panel(\"start\"),\n]);","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Side is the stack's alignment against the baseline. Missing: the dot-binning gap of entry 20.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk horizontal_side --\nset.seed(1234)\nx = rnorm(100)\n\nside_plot = function(...) {\n  expand.grid(\n    x = x,\n    side = c(\"topright\", \"both\", \"bottomleft\"),\n    stringsAsFactors = FALSE\n  ) %>%\n    ggplot(aes(side = side, ...)) +\n    geom_dots() +\n    facet_grid(~ side, labeller = \"label_both\") +\n    labs(x = NULL, y = NULL) +\n    theme(panel.border = element_rect(color = \"gray75\", fill = NA))\n}\nside_plot(x = x) +\n  labs(title = \"Horizontal geom_dots() with different values of side\") +\n  scale_y_continuous(breaks = NULL)"},{"id":"ggdist-44-vertical-side","pkg":"ggdist","num":"44","title":"Vertical geom_dots() with side = topright / both / bottomleft","source":"dotsinterval vignette, chunk vertical_side","img":"catalog/img/ggdist-44-vertical-side.png","more":[],"gofish":"const panel = (alignment) =>\n  chart(xs)\n    .flow(\n      partition({\n        by: field(\"x\").bin(Bin.step(0.2)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"y\",\n        alignment,\n      }),\n      stack({ dir: \"x\" })\n    )\n    .mark(circle({ r: 3 }));\nspread({ dir: \"x\", spacing: 12 }, [\n  panel(\"end\"),\n  panel(\"middle\"),\n  panel(\"start\"),\n]);","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Entry 43 turned vertical.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 43 --\nset.seed(1234)\nx = rnorm(100)\n\nside_plot = function(...) {\n  expand.grid(\n    x = x,\n    side = c(\"topright\", \"both\", \"bottomleft\"),\n    stringsAsFactors = FALSE\n  ) %>%\n    ggplot(aes(side = side, ...)) +\n    geom_dots() +\n    facet_grid(~ side, labeller = \"label_both\") +\n    labs(x = NULL, y = NULL) +\n    theme(panel.border = element_rect(color = \"gray75\", fill = NA))\n}\nside_plot(x = x) +\n  labs(title = \"Horizontal geom_dots() with different values of side\") +\n  scale_y_continuous(breaks = NULL)\n# -- chunk vertical_side --\nside_plot(y = x) +\n  labs(title = \"Vertical geom_dots() with different values of side\") +\n  scale_x_continuous(breaks = NULL)"},{"id":"ggdist-45-layout-top","pkg":"ggdist","num":"45","title":"geom_dots() layouts bin / hex / weave / swarm with side = 'top'","source":"dotsinterval vignette, chunk layout_top","img":"catalog/img/ggdist-45-layout-top.png","more":[],"gofish":"spread({ dir: \"y\", spacing: 12 }, [\n  // bin\n  chart(xs)\n    .flow(\n      partition({\n        by: field(\"x\").bin(Bin.step(0.2)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"x\",\n        alignment: \"end\",\n      }),\n      stack({ dir: \"y\" })\n    )\n    .mark(circle({ r: 3 })),\n  // hex and weave: no GoFish layout\n  // swarm\n  chart(xs)\n    .flow(\n      scatter({\n        x: \"x\",\n        overlap: Overlap.separate(),\n        alignment: \"end\",\n      })\n    )\n    .mark(circle({ r: 3 })),\n]);","uses_up":"the rows as finite draws, each placed by a dot layout","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Missing: the hex and weave dot layouts and dot-density binning; swarm is Overlap.separate, which exists.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 43 --\nset.seed(1234)\nx = rnorm(100)\n\nside_plot = function(...) {\n  expand.grid(\n    x = x,\n    side = c(\"topright\", \"both\", \"bottomleft\"),\n    stringsAsFactors = FALSE\n  ) %>%\n    ggplot(aes(side = side, ...)) +\n    geom_dots() +\n    facet_grid(~ side, labeller = \"label_both\") +\n    labs(x = NULL, y = NULL) +\n    theme(panel.border = element_rect(color = \"gray75\", fill = NA))\n}\nside_plot(x = x) +\n  labs(title = \"Horizontal geom_dots() with different values of side\") +\n  scale_y_continuous(breaks = NULL)\n# -- chunk layout_top --\nlayout_plot = function(layout, side, ...) {\n  data.frame(\n    x = x\n  ) %>%\n    ggplot(aes(x = x)) +\n    geom_dots(layout = layout, side = side, stackratio = if (layout == \"hex\") 0.9 else 1) +\n    labs(\n      subtitle = paste0(\"layout = \", deparse(layout), if (layout == \"hex\") \" with stackratio = 0.9\"),\n      x = NULL,\n      y = NULL\n    ) +\n    scale_y_continuous(breaks = NULL) +\n    theme(panel.border = element_rect(color = \"gray75\", fill = NA))\n}\n\n(layout_plot(\"bin\", side = \"top\") + layout_plot(\"hex\", side = \"top\")) /\n  (layout_plot(\"weave\", side = \"top\") + layout_plot(\"swarm\", side = \"top\")) +\n  plot_annotation(title = 'geom_dots() layouts with side = \"top\"')"},{"id":"ggdist-46-layout-both","pkg":"ggdist","num":"46","title":"geom_dots() layouts bin / hex / weave / swarm with side = 'both'","source":"dotsinterval vignette, chunk layout_both","img":"catalog/img/ggdist-46-layout-both.png","more":[],"gofish":"spread({ dir: \"y\", spacing: 12 }, [\n  // bin\n  chart(xs)\n    .flow(\n      partition({\n        by: field(\"x\").bin(Bin.step(0.2)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"x\",\n        alignment: \"middle\",\n      }),\n      stack({ dir: \"y\" })\n    )\n    .mark(circle({ r: 3 })),\n  // hex and weave: no GoFish layout\n  // swarm\n  chart(xs)\n    .flow(scatter({ x: \"x\", overlap: Overlap.separate() }))\n    .mark(circle({ r: 3 })),\n]);","uses_up":"the rows as finite draws, each placed by a dot layout","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Missing: the hex and weave dot layouts and dot-density binning; swarm is Overlap.separate, which exists.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 43 --\nset.seed(1234)\nx = rnorm(100)\n\nside_plot = function(...) {\n  expand.grid(\n    x = x,\n    side = c(\"topright\", \"both\", \"bottomleft\"),\n    stringsAsFactors = FALSE\n  ) %>%\n    ggplot(aes(side = side, ...)) +\n    geom_dots() +\n    facet_grid(~ side, labeller = \"label_both\") +\n    labs(x = NULL, y = NULL) +\n    theme(panel.border = element_rect(color = \"gray75\", fill = NA))\n}\nside_plot(x = x) +\n  labs(title = \"Horizontal geom_dots() with different values of side\") +\n  scale_y_continuous(breaks = NULL)\n# -- needs chunk 45 --\nlayout_plot = function(layout, side, ...) {\n  data.frame(\n    x = x\n  ) %>%\n    ggplot(aes(x = x)) +\n    geom_dots(layout = layout, side = side, stackratio = if (layout == \"hex\") 0.9 else 1) +\n    labs(\n      subtitle = paste0(\"layout = \", deparse(layout), if (layout == \"hex\") \" with stackratio = 0.9\"),\n      x = NULL,\n      y = NULL\n    ) +\n    scale_y_continuous(breaks = NULL) +\n    theme(panel.border = element_rect(color = \"gray75\", fill = NA))\n}\n\n(layout_plot(\"bin\", side = \"top\") + layout_plot(\"hex\", side = \"top\")) /\n  (layout_plot(\"weave\", side = \"top\") + layout_plot(\"swarm\", side = \"top\")) +\n  plot_annotation(title = 'geom_dots() layouts with side = \"top\"')\n# -- chunk layout_both --\n(layout_plot(\"bin\", side = \"both\") + layout_plot(\"hex\", side = \"both\")) /\n  (layout_plot(\"weave\", side = \"both\") + layout_plot(\"swarm\", side = \"both\")) +\n  plot_annotation(title = 'geom_dots() layouts with side = \"both\"')"},{"id":"ggdist-47-beeswarm-bin","pkg":"ggdist","num":"47","title":"geom_dots(side = 'both') per group (binned beeswarm)","source":"dotsinterval vignette, chunk beeswarm_bin","img":"catalog/img/ggdist-47-beeswarm-bin.png","more":[],"gofish":"chart(abcDf)\n  .flow(\n    spread({ by: \"abc\", dir: \"x\" }),\n    partition({\n      by: field(\"value\").bin(Bin.step(0.25)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"y\",\n      alignment: \"middle\",\n    }),\n    stack({ dir: \"x\" })\n  )\n  .mark(circle({ r: 2 }));","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Missing: the dot-binning gap of entry 20.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk beeswarm_bin --\nset.seed(1234)\n\nabc_df = tibble(\n  value = rnorm(300, mean = c(1,2,3), sd = c(1,2,2)),\n  abc = rep(c(\"a\", \"b\", \"c\"), 100)\n)\n\nabc_df %>%\n  ggplot(aes(x = abc, y = value)) +\n  geom_dots(side = \"both\") +\n  ggtitle('geom_dots(side = \"both\")')"},{"id":"ggdist-48-beeswarm-hex","pkg":"ggdist","num":"48","title":"geom_dots(side = 'both', layout = 'hex')","source":"dotsinterval vignette, chunk beeswarm_hex","img":"catalog/img/ggdist-48-beeswarm-hex.png","more":[],"gofish":"chart(abcDf)\n  .flow(\n    spread({ by: \"abc\", dir: \"x\" }),\n    scatter({ y: \"value\", overlap: Overlap.separate() })\n  ) // nearest: hex has no GoFish layout\n  .mark(circle({ r: 2 }));","uses_up":"the rows as finite draws, each placed by a dot layout","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Hex packing (alternate rows offset by half a dot) is not a GoFish layout; Overlap.separate gives a beeswarm instead.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 47 --\nset.seed(1234)\n\nabc_df = tibble(\n  value = rnorm(300, mean = c(1,2,3), sd = c(1,2,2)),\n  abc = rep(c(\"a\", \"b\", \"c\"), 100)\n)\n\nabc_df %>%\n  ggplot(aes(x = abc, y = value)) +\n  geom_dots(side = \"both\") +\n  ggtitle('geom_dots(side = \"both\")')\n# -- chunk beeswarm_hex --\nabc_df %>%\n  ggplot(aes(x = abc, y = value)) +\n  geom_dots(side = \"both\", layout = \"hex\", stackratio = 0.92) +\n  ggtitle('geom_dots(side = \"both\", layout = \"hex\")')"},{"id":"ggdist-49-geom-weave","pkg":"ggdist","num":"49","title":"geom_swarm() vs geom_weave()","source":"dotsinterval vignette, chunk geom_weave","img":"catalog/img/ggdist-49-geom-weave.png","more":[],"gofish":"const swarm = chart(swarmData)\n  .flow(\n    spread({ by: \"g\", dir: \"x\" }),\n    scatter({ y: \"y\", overlap: Overlap.separate() })\n  )\n  .mark(circle({ r: 2, opacity: 0.75 }));\n// weave: no GoFish layout\nspread({ dir: \"x\", spacing: 16 }, [swarm /*, weave */]);","uses_up":"the rows as finite draws, each placed by a dot layout","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The swarm panel fits as Overlap.separate. The weave panel (dots at their exact values, stacked in bins) has no GoFish layout.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk geom_weave --\nset.seed(1234)\n\nswarm_data = tibble(\n  y = rnorm(300, c(1,4)),\n  g = rep(c(\"a\",\"b\"), 150)\n)\n\nswarm_plot = swarm_data %>%\n  ggplot(aes(x = g, y = y)) +\n  geom_swarm(linewidth = 0, alpha = 0.75) +\n  labs(title = \"geom_swarm()\")\n\nweave_plot = swarm_data %>%\n  ggplot(aes(x = g, y = y)) +\n  geom_weave(linewidth = 0, alpha = 0.75) +\n  labs(title = \"geom_weave()\")\n\nswarm_plot + weave_plot"},{"id":"ggdist-50-beeswarm-dodge","pkg":"ggdist","num":"50","title":"geom_weave(position = 'dodge'), fill = hi","source":"dotsinterval vignette, chunk beeswarm_dodge","img":"catalog/img/ggdist-50-beeswarm-dodge.png","more":[],"gofish":"chart(abccDf, { color: Color.palette(\"Dark2\") })\n  .flow(\n    spread({ by: \"abc\", dir: \"x\" }),\n    spread({ by: \"hi\", dir: \"x\" }),\n    scatter({ y: \"value\", overlap: Overlap.separate() })\n  ) // weave has no GoFish layout\n  .mark(circle({ r: 2, fill: \"hi\", opacity: 0.75 }));","uses_up":"the rows as finite draws, each placed by a dot layout","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Dodge is a nested spread; the weave layout is missing.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk beeswarm_dodge --\nset.seed(12345)\n\nabcc_df = tibble(\n  value = rnorm(300, mean = c(1,2,3,4), sd = c(1,2,2,1)),\n  abc = rep(c(\"a\", \"b\", \"c\", \"c\"), 75),\n  hi = rep(c(\"h\", \"h\", \"h\", \"i\"), 75)\n)\n\nabcc_df %>%\n  ggplot(aes(y = value, x = abc, fill = hi)) +\n  geom_weave(position = \"dodge\", linewidth = 0, alpha = 0.75) +\n  scale_fill_brewer(palette = \"Dark2\") +\n  ggtitle(\n    'geom_weave(position = \"dodge\")',\n    'aes(fill = hi, shape = hi)'\n  )"},{"id":"ggdist-51-beeswarm-shape-color-together","pkg":"ggdist","num":"51","title":"geom_dots(aes(fill = hi, group = NA)): colors mixed in one stack","source":"dotsinterval vignette, chunk beeswarm_shape_color_together","img":"catalog/img/ggdist-51-beeswarm-shape-color-together.png","more":[],"gofish":"chart(abccDf)\n  .flow(\n    spread({ by: \"abc\", dir: \"x\" }),\n    partition({\n      by: field(\"value\").bin(Bin.step(0.25)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"y\",\n    }),\n    stack({ dir: \"x\" })\n  )\n  .mark(circle({ r: 2, fill: \"hi\" }));","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Stacking rows of two colors in one bin is a stack over all rows of the bin. Missing: the dot-binning gap of entry 20.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 50 --\nset.seed(12345)\n\nabcc_df = tibble(\n  value = rnorm(300, mean = c(1,2,3,4), sd = c(1,2,2,1)),\n  abc = rep(c(\"a\", \"b\", \"c\", \"c\"), 75),\n  hi = rep(c(\"h\", \"h\", \"h\", \"i\"), 75)\n)\n\nabcc_df %>%\n  ggplot(aes(y = value, x = abc, fill = hi)) +\n  geom_weave(position = \"dodge\", linewidth = 0, alpha = 0.75) +\n  scale_fill_brewer(palette = \"Dark2\") +\n  ggtitle(\n    'geom_weave(position = \"dodge\")',\n    'aes(fill = hi, shape = hi)'\n  )\n# -- chunk beeswarm_shape_color_together --\nabcc_df %>%\n  ggplot(aes(y = value, x = abc, fill = hi, group = NA)) +\n  geom_dots(linewidth = 0) +\n  scale_color_brewer(palette = \"Dark2\") +\n  ggtitle(\n    'geom_dots()',\n    'aes(fill = hi, group = NA)'\n  )"},{"id":"ggdist-52-beeswarm-shape-color-together-stacked","pkg":"ggdist","num":"52","title":"geom_dots(aes(fill = hi, group = NA, order = hi))","source":"dotsinterval vignette, chunk beeswarm_shape_color_together_stacked","img":"catalog/img/ggdist-52-beeswarm-shape-color-together-stacked.png","more":[],"gofish":"chart(abccDf)\n  .flow(\n    spread({ by: \"abc\", dir: \"x\" }),\n    partition({\n      by: field(\"value\").bin(Bin.step(0.25)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"y\",\n    }),\n    stack({ by: field(\"hi\").sort(), dir: \"x\" })\n  )\n  .mark(circle({ r: 2, fill: \"hi\" }));","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The order within each stack is the stack's sorted key. Missing: the dot-binning gap of entry 20.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 50 --\nset.seed(12345)\n\nabcc_df = tibble(\n  value = rnorm(300, mean = c(1,2,3,4), sd = c(1,2,2,1)),\n  abc = rep(c(\"a\", \"b\", \"c\", \"c\"), 75),\n  hi = rep(c(\"h\", \"h\", \"h\", \"i\"), 75)\n)\n\nabcc_df %>%\n  ggplot(aes(y = value, x = abc, fill = hi)) +\n  geom_weave(position = \"dodge\", linewidth = 0, alpha = 0.75) +\n  scale_fill_brewer(palette = \"Dark2\") +\n  ggtitle(\n    'geom_weave(position = \"dodge\")',\n    'aes(fill = hi, shape = hi)'\n  )\n# -- chunk beeswarm_shape_color_together_stacked --\nabcc_df %>%\n  ggplot(aes(y = value, x = abc, fill = hi, group = NA, order = hi)) +\n  geom_dots(linewidth = 0) +\n  scale_color_brewer(palette = \"Dark2\") +\n  ggtitle(\n    'geom_dots()',\n    'aes(fill = hi, group = NA, order = hi)'\n  )"},{"id":"ggdist-53-beeswarm-shape-color-continuous","pkg":"ggdist","num":"53","title":"geom_dots(aes(shape = abc, color = value))","source":"dotsinterval vignette, chunk beeswarm_shape_color_continuous","img":"catalog/img/ggdist-53-beeswarm-shape-color-continuous.png","more":[],"gofish":"chart(abccDf, {\n  color: Color.gradient([\"#132b43\", \"#56b1f7\"]),\n})\n  .flow(\n    spread({ by: \"abc\", dir: \"x\" }),\n    partition({\n      by: field(\"value\").bin(Bin.step(0.25)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"y\",\n    }),\n    stack({ dir: \"x\" })\n  )\n  .mark(circle({ r: 2, fill: \"value\" })); // shape by abc: no shape channel","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Color by value fits. Missing: a point shape mapped from a field, and the dot-binning gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 50 --\nset.seed(12345)\n\nabcc_df = tibble(\n  value = rnorm(300, mean = c(1,2,3,4), sd = c(1,2,2,1)),\n  abc = rep(c(\"a\", \"b\", \"c\", \"c\"), 75),\n  hi = rep(c(\"h\", \"h\", \"h\", \"i\"), 75)\n)\n\nabcc_df %>%\n  ggplot(aes(y = value, x = abc, fill = hi)) +\n  geom_weave(position = \"dodge\", linewidth = 0, alpha = 0.75) +\n  scale_fill_brewer(palette = \"Dark2\") +\n  ggtitle(\n    'geom_weave(position = \"dodge\")',\n    'aes(fill = hi, shape = hi)'\n  )\n# -- chunk beeswarm_shape_color_continuous --\nabcc_df %>%\n  arrange(hi) %>%\n  ggplot(aes(y = value, x = abc, shape = abc, color = value)) +\n  geom_dots() +\n  ggtitle(\n    'geom_dots()',\n    'aes(color = value)'\n  )"},{"id":"ggdist-54-increasing-samples","pkg":"ggdist","num":"54","title":"geom_dots() on samples of 50, 200, 500, 5000 (facet_wrap)","source":"dotsinterval vignette, chunk increasing_samples","img":"catalog/img/ggdist-54-increasing-samples.png","more":[],"gofish":"chart(increasingSamples)\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" } }), // facet_wrap(~ n) needs a col/row column per n\n    partition({\n      by: field(\"x\").bin(Bin.step(0.1)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"x\",\n    }),\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 2 }));","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The point of the chart is that ggdist shrinks the dots so the tallest stack fits each panel; GoFish has no dot size or bin width from the layout. Also, a wrapped facet by one key needs hand-made row and column fields (table takes two keys).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk increasing_samples --\nset.seed(1234)\n\nns = c(50, 200, 500, 5000)\nincreasing_samples = data.frame(\n  x = rgamma(sum(ns), 2, 2),\n  n = rep(ns, ns)\n)\n\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  facet_wrap(~ n) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on large samples, dots may get too small\"\n  )"},{"id":"ggdist-55-increasing-samples-min-binwidth","pkg":"ggdist","num":"55","title":"geom_dots(binwidth = unit(c(1, Inf), 'mm')): a minimum bin width","source":"dotsinterval vignette, chunk increasing_samples_min_binwidth","img":"catalog/img/ggdist-55-increasing-samples-min-binwidth.png","more":[],"gofish":"chart(increasingSamples)\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" } }), // facet_wrap(~ n) needs a col/row column per n\n    partition({\n      by: field(\"x\").bin(Bin.step(0.1)), // chosen by hand; ggdist picks the width so the tallest stack fits, with a 1 mm minimum\n      dir: \"x\",\n    }),\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 2 }));","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A bin width with a minimum in millimetres lets the stacks overflow the panel. Bin.step is in data units, so a width in screen units needs the scale (entry 54's gap).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 54 --\nset.seed(1234)\n\nns = c(50, 200, 500, 5000)\nincreasing_samples = data.frame(\n  x = rgamma(sum(ns), 2, 2),\n  n = rep(ns, ns)\n)\n\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  facet_wrap(~ n) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on large samples, dots may get too small\"\n  )\n# -- chunk increasing_samples_min_binwidth --\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  geom_dots(binwidth = unit(c(1, Inf), \"mm\")) +\n  facet_wrap(~ n) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = 'binwidth = unit(c(1.5, Inf), \"mm\")'\n  )"},{"id":"ggdist-56-increasing-samples-min-binwidth-compress","pkg":"ggdist","num":"56","title":"geom_dots(binwidth = unit(c(1, Inf), 'mm'), overflow = 'compress')","source":"dotsinterval vignette, chunk increasing_samples_min_binwidth_compress","img":"catalog/img/ggdist-56-increasing-samples-min-binwidth-compress.png","more":[],"gofish":"chart(increasingSamples)\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" } }), // facet_wrap(~ n) needs a col/row column per n\n    partition({\n      by: field(\"x\").bin(Bin.step(0.1)), // chosen by hand; ggdist picks the width so the tallest stack fits, with a 1 mm minimum\n      dir: \"x\",\n    }),\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 2 }));","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"overflow = 'compress' squeezes the stack spacing so overflowing stacks fit; GoFish's stack has no such option (and no spacing at all).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 54 --\nset.seed(1234)\n\nns = c(50, 200, 500, 5000)\nincreasing_samples = data.frame(\n  x = rgamma(sum(ns), 2, 2),\n  n = rep(ns, ns)\n)\n\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  facet_wrap(~ n) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on large samples, dots may get too small\"\n  )\n# -- chunk increasing_samples_min_binwidth_compress --\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  geom_dots(binwidth = unit(c(1, Inf), \"mm\"), overflow = \"compress\", alpha = 0.75) +\n  facet_wrap(~ n) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = 'binwidth = unit(c(1, Inf), \"mm\"), overflow = \"compress\"'\n  )"},{"id":"ggdist-57-discrete-dots-too-small","pkg":"ggdist","num":"57","title":"geom_dots() on a large discrete sample","source":"dotsinterval vignette, chunk discrete_dots_too_small","img":"catalog/img/ggdist-57-discrete-dots-too-small.png","more":[],"gofish":"chart(abcdDf)\n  .flow(spread({ by: \"x\", dir: \"x\" }), stack({ dir: \"y\" }))\n  .mark(circle({ r: 0.6 }));","uses_up":"the rows as finite draws: spread by category, then stack","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A discrete dotplot is a spread by category and a stack. ggdist picks the dot size so 600 dots fit; GoFish needs it by hand (entry 54's gap).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk discrete_dots_too_small --\nset.seed(1234)\nabcd_df = tibble(\n  x = sample(c(\"a\", \"b\", \"c\", \"d\"), 1000, replace = TRUE, prob = c(0.27, 0.6, 0.03, 0.005)),\n  g = rep(c(\"a\",\"b\"), 500)\n)\n\nabcd_df %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  scale_y_continuous(breaks = NULL) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on a large discrete sample\"\n  )"},{"id":"ggdist-58-discrete-dots-bar","pkg":"ggdist","num":"58","title":"geom_dots(layout = 'bar', aes(fill = g)) on a discrete sample","source":"dotsinterval vignette, chunk discrete_dots_bar","img":"catalog/img/ggdist-58-discrete-dots-bar.png","more":[],"gofish":"chart(abcdDf)\n  .flow(\n    spread({ by: \"x\", dir: \"x\" }),\n    stack({ by: \"g\", dir: \"y\" })\n  ) // + a grid of dots inside each bar\n  .mark(circle({ r: 1, fill: \"g\" }));","uses_up":"the rows as finite draws: spread by category, then a grid of dots","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The bar layout packs each category's dots into a grid shaped like a bar (rows of several dots). GoFish has no wrapped grid of marks inside a stack.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 57 --\nset.seed(1234)\nabcd_df = tibble(\n  x = sample(c(\"a\", \"b\", \"c\", \"d\"), 1000, replace = TRUE, prob = c(0.27, 0.6, 0.03, 0.005)),\n  g = rep(c(\"a\",\"b\"), 500)\n)\n\nabcd_df %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  scale_y_continuous(breaks = NULL) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on a large discrete sample\"\n  )\n# -- chunk discrete_dots_bar --\nabcd_df %>%\n  ggplot(aes(x = x, fill = g, order = g)) +\n  geom_dots(layout = \"bar\", group = NA, color = NA) +\n  scale_y_continuous(breaks = NULL) +\n  labs(\n    title = 'geom_dots(aes(fill = g), layout = \"bar\", group = NA)',\n    subtitle = \"on a large discrete sample\"\n  )"},{"id":"ggdist-59-discrete-dots-ep","pkg":"ggdist","num":"59","title":"geom_dots(smooth = smooth_discrete(kernel = 'ep'), side = 'both')","source":"dotsinterval vignette, chunk discrete_dots_ep","img":"catalog/img/ggdist-59-discrete-dots-ep.png","more":[],"gofish":"chart(abcdDf)\n  .flow(\n    spread({ by: \"x\", dir: \"x\" }),\n    scatter({\n      x: 0,\n      overlap: Overlap.noise({ smoothing: 0.3 }),\n    })\n  )\n  .mark(circle({ r: 0.6 }));","uses_up":"the rows as finite draws, smoothed along the category axis","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"smooth_discrete moves each discrete value by a kernel along the data axis, then bins and stacks it, so each category becomes a small density. GoFish's noise moves dots along the free axis, not the data axis, and a discrete position cannot take continuous noise.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 57 --\nset.seed(1234)\nabcd_df = tibble(\n  x = sample(c(\"a\", \"b\", \"c\", \"d\"), 1000, replace = TRUE, prob = c(0.27, 0.6, 0.03, 0.005)),\n  g = rep(c(\"a\",\"b\"), 500)\n)\n\nabcd_df %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  scale_y_continuous(breaks = NULL) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on a large discrete sample\"\n  )\n# -- chunk discrete_dots_ep --\nabcd_df %>%\n  ggplot(aes(x = x)) +\n  geom_dots(smooth = smooth_discrete(kernel = \"ep\"), side = \"both\") +\n  scale_y_continuous(breaks = NULL) +\n  labs(\n    title = 'geom_dots(smooth = smooth_discrete(kernel = \"ep\"), side = \"both\")',\n    subtitle = \"on a large discrete sample\"\n  )"},{"id":"ggdist-60-dotsinterval-dist","pkg":"ggdist","num":"60","title":"stat_dotsinterval(subguide = 'integer') of Normal, Beta and Gamma","source":"dotsinterval vignette, chunk dotsinterval_dist","img":"catalog/img/ggdist-60-dotsinterval-dist.png","more":[],"gofish":"chart(sample(distDf2, { n: 100, at: \"quantiles\" }))\n  .flow(\n    spread({ by: \"distName\", dir: \"y\" }),\n    partition({\n      by: as(\"dist\").bin(Bin.step(0.02)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"x\",\n    }),\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 1.5 }))\n  .layer(\n    chart(distDf2)\n      .flow(spread({ by: \"distName\", dir: \"y\" }))\n      .mark(interval(\"dist\"))\n  );","uses_up":"sample(data, { n: 100, at: \"quantiles\" }), then partition by a bin and stack (finite n); the interval is quantiles and the median of the draws","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Quantile dots and intervals of three families, from a column of Dist cells. Missing: the dot-binning gap (one bin width cannot suit three different scales) and the integer subguide, a count axis inside each row.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk dotsinterval_dist --\ndist_df = tibble(\n  dist = c(dist_normal(1,0.25), dist_beta(3,3), dist_gamma(5,5)),\n  dist_name = format(dist)\n)\n\ndist_df %>%\n  ggplot(aes(y = dist_name, xdist = dist)) +\n  stat_dotsinterval(subguide = 'integer') +\n  ggtitle(\n    \"stat_dotsinterval(subguide = 'integer')\",\n    \"aes(y = dist_name, xdist = dist)\"\n  )"},{"id":"ggdist-61-dotsinterval-dist-1000-level-color","pkg":"ggdist","num":"61","title":"stat_dotsinterval(quantiles = 1000, point_interval = mode_hdci, layout = 'weave'), slab_fill = level","source":"dotsinterval vignette, chunk dotsinterval_dist_1000_level_color","img":"catalog/img/ggdist-61-dotsinterval-dist-1000-level-color.png","more":[],"gofish":"chart(sample(distDf2, { n: 1000, at: \"quantiles\" }), {\n  color: Color.palette([\"#9ecae1\", \"#3182bd\"]),\n})\n  .flow(\n    spread({ by: \"distName\", dir: \"y\" }),\n    // the interval a dot falls in, from its level: the hdci\n    // needs a helper that does not exist\n    derive((rows) =>\n      rows.map((r) => ({\n        ...r,\n        band: Math.abs(r.level - 0.5) < 0.33 ? 0.66 : 0.95,\n      }))\n    ),\n    scatter({ x: \"dist\", overlap: Overlap.separate() }) // weave: no GoFish layout\n  )\n  .mark(circle({ r: 0.5, fill: \"band\" }))\n  .layer(\n    chart(distDf2)\n      .flow(spread({ by: \"distName\", dir: \"y\" }))\n      .mark(\n        layer([\n          // gap: the mode and the highest-density interval,\n          // written as the helper they would most likely be\n          interval(\"dist\", {\n            intervals: highestDensityIntervals,\n            point: \"mode\",\n          }),\n        ])\n      )\n  );","uses_up":"sample(data, { n: 1000, at: \"quantiles\" }), then partition by a bin and stack (finite n) by a dot layout; the interval is central intervals of the draws","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Coloring each dot by the interval it falls in reads level, which is exact for an equal-tailed interval. Missing: the weave layout, and the mode and HDCI summaries (entry 30); with an HDCI the band is not a function of level alone.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 60 --\ndist_df = tibble(\n  dist = c(dist_normal(1,0.25), dist_beta(3,3), dist_gamma(5,5)),\n  dist_name = format(dist)\n)\n\ndist_df %>%\n  ggplot(aes(y = dist_name, xdist = dist)) +\n  stat_dotsinterval(subguide = 'integer') +\n  ggtitle(\n    \"stat_dotsinterval(subguide = 'integer')\",\n    \"aes(y = dist_name, xdist = dist)\"\n  )\n# -- chunk dotsinterval_dist_1000_level_color --\ndist_df %>%\n  ggplot(aes(y = dist_name, xdist = dist, slab_fill = after_stat(level))) +\n  stat_dotsinterval(quantiles = 1000, point_interval = mode_hdci, layout = \"weave\", slab_color = NA) +\n  scale_color_manual(values = scales::brewer_pal()(3)[-1], aesthetics = \"slab_fill\") +\n  ggtitle(\n    \"stat_dotsinterval(quantiles = 1000, point_interval = mode_hdci)\",\n    \"aes(y = dist_name, xdist = dist, slab_fill = after_stat(level))\"\n  )"},{"id":"ggdist-62-dotsinterval-dist-color","pkg":"ggdist","num":"62","title":"stat_dotsinterval(slab_shape = 19, quantiles = 500), slab_color = after_stat(x)","source":"dotsinterval vignette, chunk dotsinterval_dist_color","img":"catalog/img/ggdist-62-dotsinterval-dist-color.png","more":[],"gofish":"chart(sample(distDf2, { n: 500, at: \"quantiles\" }), {\n  color: Color.gradient(\"Blues\"),\n})\n  .flow(\n    spread({ by: \"distName\", dir: \"y\" }),\n    partition({\n      by: as(\"dist\").bin(Bin.step(0.01)), // chosen by hand; ggdist picks the width so the tallest stack fits\n      dir: \"x\",\n    }),\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 0.7, fill: \"dist\" }))\n  .layer(\n    chart(distDf2)\n      .flow(spread({ by: \"distName\", dir: \"y\" }))\n      .mark(interval(\"dist\"))\n  );","uses_up":"sample(data, { n: 500, at: \"quantiles\" }), then partition by a bin and stack (finite n); the interval is central intervals of the draws","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Color by the dot's value: on a drawn row the Dist column reads the draw. Missing: the dot-binning gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 60 --\ndist_df = tibble(\n  dist = c(dist_normal(1,0.25), dist_beta(3,3), dist_gamma(5,5)),\n  dist_name = format(dist)\n)\n\ndist_df %>%\n  ggplot(aes(y = dist_name, xdist = dist)) +\n  stat_dotsinterval(subguide = 'integer') +\n  ggtitle(\n    \"stat_dotsinterval(subguide = 'integer')\",\n    \"aes(y = dist_name, xdist = dist)\"\n  )\n# -- chunk dotsinterval_dist_color --\ndist_df %>%\n  ggplot(aes(y = dist_name, xdist = dist, slab_color = after_stat(x))) +\n  stat_dotsinterval(slab_shape = 19, quantiles = 500) +\n  scale_color_distiller(aesthetics = \"slab_color\", guide = \"colorbar2\") +\n  ggtitle(\n    \"stat_dotsinterval(slab_shape = 19, quantiles = 500)\",\n    'aes(slab_color = after_stat(x)) +\\nscale_color_distiller(aesthetics = \"slab_color\", guide = \"colorbar2\")'\n  )"},{"id":"ggdist-63-dist-dots-weave","pkg":"ggdist","num":"63","title":"stat_dots(layout = 'weave'), fill = after_stat(x < 6), with a reference line","source":"dotsinterval vignette, chunk dist_dots_weave","img":"catalog/img/ggdist-63-dist-dots-weave.png","more":[],"gofish":"const x = dist.normal({ mean: \"mean\", sd: \"sd\" });\nchart(sample(abDf, { n: 100, at: \"quantiles\" }))\n  .flow(\n    spread({ by: \"ab\", dir: \"y\" }),\n    derive((rows) =>\n      rows.map((r) => ({ ...r, flag: r.x < 6 }))\n    ), // x < 6 on the drawn value\n    scatter({ x, overlap: Overlap.separate() }) // weave: no GoFish layout\n  )\n  .mark(circle({ r: 2, fill: \"flag\" }))\n  .layer(\n    chart([{ x: 6 }]).mark(\n      rect({ x: \"x\", w: 1, opacity: 0.25 })\n    )\n  );","uses_up":"sample(data, { n: 100, at: \"quantiles\" }), then partition by a bin and stack (finite n) by a dot layout","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The predicate is a derive on the drawn rows. Missing: the weave layout.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk dist_dots_weave --\nab_df = tibble(\n  ab = c(\"a\", \"b\"),\n  mean = c(5, 7),\n  sd = c(1, 1.5)\n)\n\nab_df %>%\n  ggplot(aes(y = ab, xdist = dist_normal(mean, sd), fill = after_stat(x < 6))) +\n  stat_dots(position = \"dodge\", color = NA, layout = \"weave\") +\n  labs(\n    title = 'stat_dots(layout = \"weave\")',\n    subtitle = \"aes(fill = after_stat(x < 6))\"\n  ) +\n  geom_vline(xintercept = 6, alpha = 0.25) +\n  scale_x_continuous(breaks = 2:10)"},{"id":"ggdist-64-halfeye-dotplot","pkg":"ggdist","num":"64","title":"stat_slab(thickness = pdf*n) above + stat_dotsinterval(side = 'bottom') below","source":"dotsinterval vignette, chunk halfeye_dotplot","img":"catalog/img/ggdist-64-halfeye-dotplot.png","more":[],"gofish":"const value = field(\"value\");\nchart(halfeyeDotDf, { color: Color.palette(\"Set2\") })\n  .flow(spread({ by: \"abc\", dir: \"y\" }))\n  .mark(\n    layer([\n      slab(\"value\", {\n        fill: \"abc\",\n        curve: (c, rows) =>\n          c.map((r) => ({\n            ...r,\n            density: r.density * rows.length,\n          })),\n      }),\n      // dots below the line. gap: they should hang from the\n      // slab's zero line\n      chart()\n        .flow(\n          partition({\n            by: value.bin(Bin.step(0.3)), // chosen by hand; ggdist picks the width so the tallest stack fits\n            dir: \"x\",\n            alignment: \"start\",\n          }),\n          stack({ dir: \"y\" })\n        )\n        .mark(circle({ r: 2, fill: \"abc\" })),\n      interval(\"value\"),\n    ])\n  );","uses_up":"slab: the density curve and the count of the draws over the rows; dots: partition by a bin and stack over the rows","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Dots hanging below the line need entry 4's origin alignment. Scaling the slab's curve by the row count so it matches the dot stacks needs the slab and the stacks on one count scale, which the hand-set bin width breaks.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk halfeye_dotplot --\nset.seed(12345) # for reproducibility\n\ntibble(\n  abc = rep(c(\"a\", \"b\", \"b\", \"c\"), 50),\n  value = rnorm(200, c(1, 8, 8, 3), c(1, 1.5, 1.5, 1))\n) %>%\n  ggplot(aes(y = abc, x = value, fill = abc)) +\n  stat_slab(aes(thickness = after_stat(pdf*n)), scale = 0.7) +\n  stat_dotsinterval(side = \"bottom\", scale = 0.7, slab_linewidth = NA) +\n  scale_fill_brewer(palette = \"Set2\") +\n  ggtitle(\n    paste0(\n      'stat_slab(aes(thickness = after_stat(pdf*n)), scale = 0.7) +\\n',\n      'stat_dotsinterval(side = \"bottom\", scale = 0.7, slab_linewidth = NA)'\n    ),\n    'aes(fill = abc)'\n  )"},{"id":"ggdist-65-mcse-blur-dots","pkg":"ggdist","num":"65","title":"stat_mcse_dots(quantiles = 100): Monte Carlo standard error of each quantile as blur","source":"dotsinterval vignette, chunk mcse_blur_dots","img":"catalog/img/ggdist-65-mcse-blur-dots.png","more":[],"gofish":"// Not writable. The nearest version 2 spelling,\n// with two problems marked.\n// missing: no constructor makes a Dist<Dist> from a sample\nconst boot = dist.resampled(\"x\");\n// a draw of each sample\nconst outer = sample(increasingSamples, { n: 200 });\n// missing: this second sample also writes draw and level\nconst inner = sample(outer, { n: 100, at: \"quantiles\" });\nchart(inner)\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" } }),\n    // the outer draw key, which the inner one has overwritten\n    group({ by: \"draw\", blend: \"mean\" }),\n    partition({ by: boot.bin(Bin.step(0.1)), dir: \"x\" }), // chosen by hand; ggdist picks the width so the tallest stack fits\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 2 }));","uses_up":"(would be) the outer draws, blended, over the inner quantile dots","fit":"does-not-fit","verdict":"ok","v1_fit":"does-not-fit","note":"ggdist blurs each dot sideways by its quantile's Monte Carlo standard error, after binning. That is the blur channel the limits tab rules out (the Figure 14b cliff), so ggdist's own picture has no draw spelling. Section 4 says the honest version needs a Dist<Dist> made from a sample by resampling, a constructor and not a step. The catalog finds two missing pieces. Version 2 names no such constructor. And two levels of draws need two draw keys, but sample always writes columns named draw and level, so the inner sample overwrites the outer one. Its picture would also fade dots across stacks rather than smear them.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 54 --\nset.seed(1234)\n\nns = c(50, 200, 500, 5000)\nincreasing_samples = data.frame(\n  x = rgamma(sum(ns), 2, 2),\n  n = rep(ns, ns)\n)\n\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  facet_wrap(~ n) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on large samples, dots may get too small\"\n  )\n# -- chunk mcse_blur_dots --\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  stat_mcse_dots(quantiles = 100) +\n  facet_wrap(~ n) +\n  labs(\n    title = \"stat_mcse_dots(quantiles = 100)\",\n    subtitle = \"Monte Carlo Standard Error of each quantile shown as blur\"\n  )"},{"id":"ggdist-66-mcse-interval-dots","pkg":"ggdist","num":"66","title":"stat_mcse_dots(quantiles = 100, blur = 'interval')","source":"dotsinterval vignette, chunk mcse_interval_dots","img":"catalog/img/ggdist-66-mcse-interval-dots.png","more":[],"gofish":"// Not writable, for the reasons of entry 65.\n// With two named draw keys it would be: per inner\n// level, the 95% interval of the dot's value across\n// the outer draws (quantiles per level), drawn\n// as a rect through each dot.","uses_up":"(would be) quantiles across the outer draws, per inner level","fit":"does-not-fit","verdict":"ok","v1_fit":"does-not-fit","note":"Each dot's interval is the uncertainty of the quantile estimate, an outer level over the sample. In the draw model it is a pair of quantiles across the outer draws, grouped by the inner level. That needs the Dist<Dist> constructor and two draw keys, which entry 65 shows version 2 does not have.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 54 --\nset.seed(1234)\n\nns = c(50, 200, 500, 5000)\nincreasing_samples = data.frame(\n  x = rgamma(sum(ns), 2, 2),\n  n = rep(ns, ns)\n)\n\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  geom_dots() +\n  facet_wrap(~ n) +\n  labs(\n    title = \"geom_dots()\",\n    subtitle = \"on large samples, dots may get too small\"\n  )\n# -- chunk mcse_interval_dots --\nincreasing_samples %>%\n  ggplot(aes(x = x)) +\n  stat_mcse_dots(quantiles = 100, blur = \"interval\") +\n  facet_wrap(~ n) +\n  labs(\n    title = 'stat_mcse_dots(quantiles = 100, blur = \"interval\")',\n    subtitle = \"Monte Carlo Standard Error of each quantile shown as 95% intervals\"\n  )"},{"id":"ggdist-67-iris-v","pkg":"ggdist","num":"67","title":"geom_dots(scale = 0.5), aes(side = Species) + scale_side_mirrored()","source":"dotsinterval vignette, chunk iris_v","img":"catalog/img/ggdist-67-iris-v.png","more":[],"gofish":"layer([\n  chart(irisV.filter((d) => d.Species === \"versicolor\"))\n    .flow(\n      partition({\n        by: field(\"Petal.Length\").bin(Bin.step(0.1)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"x\",\n        alignment: \"end\",\n      }),\n      stack({ dir: \"y\" })\n    )\n    .mark(circle({ r: 2 })),\n  chart(irisV.filter((d) => d.Species === \"virginica\"))\n    .flow(\n      partition({\n        by: field(\"Petal.Length\").bin(Bin.step(0.1)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"x\",\n        alignment: \"start\",\n      }),\n      stack({ dir: \"y\" })\n    )\n    .mark(circle({ r: 2 })),\n]);","uses_up":"partition by a bin of the value, then stack, over the rows (each row is a draw; finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Side as a scale of a field is not a GoFish channel, so each species is its own chart with its own alignment. Missing: the dot-binning gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk iris_v --\niris_v = iris %>%\n  filter(Species != \"setosa\")\n\niris_v %>%\n  ggplot(aes(x = Petal.Length, y = Species, side = Species)) +\n  geom_dots(scale = 0.5) +\n  scale_side_mirrored(guide = \"none\") +\n  ggtitle(\n    \"geom_dots(scale = 0.5)\",\n    'aes(side = Species) + scale_side_mirrored()'\n  )"},{"id":"ggdist-68-logit-dotplot","pkg":"ggdist","num":"68","title":"Logit dotplot: geom_dots() with stat_lineribbon() of a transformed normal","source":"dotsinterval vignette, chunk logit_dotplot","img":"catalog/img/ggdist-68-logit-dotplot.png","more":[],"gofish":"const p = dist.transformed({\n  dist: dist.normal({ mean: \"fit\", sd: \"se.fit\" }),\n  f: plogis,\n}); // no transformed Dist\nlayer([\n  chart(irisV)\n    .flow(\n      spread({ by: \"Species\", dir: \"y\" }),\n      partition({\n        by: field(\"Petal.Length\").bin(Bin.step(0.1)), // chosen by hand; ggdist picks the width so the tallest stack fits\n        dir: \"x\",\n      }),\n      stack({ dir: \"y\" })\n    )\n    .mark(circle({ r: 2 })),\n  chart(predictionGrid).mark(\n    lineribbon(p, {\n      along: \"Petal.Length\",\n      fill: \"#08306b\",\n      opacity: 0.25,\n    })\n  ),\n]);","uses_up":"dots: partition by a bin and stack over the rows; ribbon: quantiles and the median of the draws per x","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The ribbon is central intervals of the draws along x (quantiles pass through the monotone plogis). Missing: a transformed Dist constructor, dots stacked down from y = 1 and up from y = 0 on a continuous y axis (side mirrored by species), and the dot-binning gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 67 --\niris_v = iris %>%\n  filter(Species != \"setosa\")\n\niris_v %>%\n  ggplot(aes(x = Petal.Length, y = Species, side = Species)) +\n  geom_dots(scale = 0.5) +\n  scale_side_mirrored(guide = \"none\") +\n  ggtitle(\n    \"geom_dots(scale = 0.5)\",\n    'aes(side = Species) + scale_side_mirrored()'\n  )\n# -- needs chunk m_iris_v --\nm = glm(Species == \"virginica\" ~ Petal.Length, data = iris_v, family = binomial)\nm\n# -- chunk logit_dotplot --\n# construct a prediction grid for the fit line\nprediction_grid = with(iris_v,\n  data.frame(Petal.Length = seq(min(Petal.Length), max(Petal.Length), length.out = 100))\n)\n\nprediction_grid %>%\n  bind_cols(predict(m, ., se.fit = TRUE)) %>%\n  mutate(\n    # distribution describing uncertainty in log odds\n    log_odds = dist_normal(fit, se.fit),\n    # inverse-logit transform the log odds to get\n    # distribution describing uncertainty in Pr(Species == \"virginica\")\n    p_virginica = dist_transformed(log_odds, plogis, qlogis)\n  ) %>%\n  ggplot(aes(x = Petal.Length)) +\n  geom_dots(\n    aes(y = as.numeric(Species == \"virginica\"), side = Species),\n    scale = 0.4,\n    data = iris_v\n  ) +\n  stat_lineribbon(\n    aes(ydist = p_virginica), alpha = 1/4, fill = \"#08306b\"\n  ) +\n  scale_side_mirrored(guide = \"none\") +\n  coord_cartesian(ylim = c(0, 1)) +\n  labs(\n    title = \"logit dotplot: geom_dots() with stat_lineribbon()\",\n    subtitle = 'aes(side = Species) + scale_side_mirrored()',\n    x = \"Petal Length\",\n    y = \"Pr(Species = virginica)\"\n  )"},{"id":"ggdist-69-spaghetti","pkg":"ggdist","num":"69","title":"Spaghetti plot: 100 draws of a linear model","source":"lineribbon vignette, chunk spaghetti","img":"catalog/img/ggdist-69-spaghetti.png","more":[],"gofish":"chart(\n  df.filter((d) => d[\".draw\"] <= 100),\n  { schema: { y: { draws: \".draw\" } } }\n)\n  .flow(\n    group({ by: \".draw\" }),\n    scatter({ by: \"x\", x: \"x\", y: \"y\" })\n  )\n  .mark(line({ opacity: 0.25 }));","uses_up":"group({ by: \".draw\" }), the plain overlay, over draws declared shared in the schema, 100 draws","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The draws are shared: each .draw is a whole line. The schema says so, and then rule 3.2 has nothing to warn about. This is the plain overlay row of the table, which version 1's table lacked; ggdist's alpha is 0.25, not the 1/100 a blend would give.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- chunk spaghetti --\ndf %>%\n  filter(.draw %in% 1:100) %>%\n  ggplot(aes(x = x, y = y, group = .draw)) +\n  geom_line(alpha = 0.25)"},{"id":"ggdist-70-one-ribbon","pkg":"ggdist","num":"70","title":"geom_lineribbon() of median_qi(y) per x (one 95% band)","source":"lineribbon vignette, chunk one_ribbon","img":"catalog/img/ggdist-70-one-ribbon.png","more":[],"gofish":"chart(df).mark(\n  lineribbon(\"y\", {\n    along: \"x\",\n    levels: [0.95],\n    fill: \"gray65\",\n  })\n);","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The band is the central interval of the draws at each x, and the line goes through the median of the draws at each x, which rule 3.2 treats as a summary. Version 1's rule warned here.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- chunk one_ribbon --\ndf %>%\n  group_by(x) %>%\n  median_qi(y) %>%\n  ggplot(aes(x = x, y = y, ymin = .lower, ymax = .upper)) +\n  geom_lineribbon(fill = \"gray65\")"},{"id":"ggdist-71-geom-lineribbon","pkg":"ggdist","num":"71","title":"geom_lineribbon() with .width = c(.5, .8, .95)","source":"lineribbon vignette, chunk geom_lineribbon","img":"catalog/img/ggdist-71-geom-lineribbon.png","more":[],"gofish":"chart(df, {\n  color: Color.palette([\"#deebf7\", \"#9ecae1\", \"#3182bd\"]),\n}).mark(lineribbon(\"y\", { along: \"x\" }));","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Three nested bands colored by level. Each band is the central interval of the draws at each x, and the line goes through the median of the draws at each x, which rule 3.2 treats as a summary. Version 1's rule warned here.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- chunk geom_lineribbon --\ndf %>%\n  group_by(x) %>%\n  median_qi(y, .width = c(.50, .80, .95)) %>%\n  ggplot(aes(x = x, y = y, ymin = .lower, ymax = .upper)) +\n  geom_lineribbon() +\n  scale_fill_brewer()"},{"id":"ggdist-72-stat-lineribbon","pkg":"ggdist","num":"72","title":"stat_lineribbon() over the draws","source":"lineribbon vignette, chunk stat_lineribbon","img":"catalog/img/ggdist-72-stat-lineribbon.png","more":[],"gofish":"chart(df, {\n  color: Color.palette([\"#deebf7\", \"#9ecae1\", \"#3182bd\"]),\n}).mark(lineribbon(\"y\", { along: \"x\" }));","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The same picture as entry 71, computed from the draw rows.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- chunk stat_lineribbon --\ndf %>%\n  ggplot(aes(x = x, y = y)) +\n  stat_lineribbon() +\n  scale_fill_brewer()"},{"id":"ggdist-73-stat-lineribbon-gradient","pkg":"ggdist","num":"73","title":"stat_lineribbon(.width = ppoints(50)), fill = .width (merged with the fill_ramp + rampbar version)","source":"lineribbon vignette, chunk stat_lineribbon_gradient (merged with chunk stat_lineribbon_gradient_rampbar)","img":"catalog/img/ggdist-73-stat-lineribbon-gradient.png","more":["catalog/img/ggdist-73-stat-lineribbon-gradientb.png"],"gofish":"const levels = Array.from(\n  { length: 50 },\n  (_, i) => (i + 0.5) / 50\n);\nchart(df, { color: Color.gradient(\"Blues\") }).mark(\n  lineribbon(\"y\", { along: \"x\", levels: levels })\n);","uses_up":"quantiles and the median of the draws per cell, with one cell per x, at 50 levels","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Fifty nested bands colored by level. The merged rampbar version maps the same level to a lightened single hue, which is a gradient color scale here; its rampbar legend is a GoFish legend detail.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- chunk stat_lineribbon_gradient --\ndf %>%\n  ggplot(aes(x = x, y = y, fill = after_stat(.width))) +\n  stat_lineribbon(.width = ppoints(50)) +\n  scale_fill_distiller() +\n  labs(title = \"stat_lineribbon(.width = ppoints(50))\")\n# -- merged chunk stat_lineribbon_gradient_rampbar --\ndf %>%\n  ggplot(aes(x = x, y = y, fill_ramp = after_stat(.width))) +\n  stat_lineribbon(.width = ppoints(50), fill = \"#2171b5\") +\n  scale_fill_ramp_continuous(range = c(1, 0), guide = guide_rampbar(to = \"#2171b5\")) +\n  labs(\n    title = \"stat_lineribbon(.width = ppoints(50))\",\n    subtitle = 'aes(fill_ramp = after_stat(.width)) +\\nscale_fill_ramp_continuous(guide = \"rampbar\")'\n  )"},{"id":"ggdist-74-stat-lineribbon-density","pkg":"ggdist","num":"74","title":"stat_lineribbon(.width = ppoints(50)), fill_ramp = mean density at the band edges","source":"lineribbon vignette, chunk stat_lineribbon_density","img":"catalog/img/ggdist-74-stat-lineribbon-density.png","more":[],"gofish":"const levels = Array.from(\n  { length: 50 },\n  (_, i) => (i + 0.5) / 50\n);\nlayer([\n  // bands: one ribbon per level, colored by the density at\n  // its edges\n  chart(df, { color: Color.gradient([\"white\", \"#2171b5\"]) })\n    .flow(\n      derive((rows) => {\n        // at each x and level: the central interval, and\n        // the density at its two ends\n        const bands = Object.values(\n          Object.groupBy(rows, (r) => r.x)\n        ).flatMap((step) =>\n          centralIntervals(step, \"y\", levels).map(\n            (band) => {\n              const [lo, hi] = densityCurve(step, \"y\", {\n                n: 2,\n                range: [\n                  band.center - band.size / 2,\n                  band.center + band.size / 2,\n                ],\n              });\n              return {\n                ...band,\n                edge: lo.density + hi.density,\n              };\n            }\n          )\n        );\n        // ave(pdf_min + pdf_max, .width): the mean over\n        // every x, per level\n        const shade = (p) => {\n          const edges = bands\n            .filter((b) => b.level === p)\n            .map((b) => b.edge);\n          return (\n            edges.reduce((sum, e) => sum + e, 0) /\n            edges.length\n          );\n        };\n        return bands.map((b) => ({\n          ...b,\n          shade: shade(b.level),\n        }));\n      }),\n      group({ by: \"level\" }),\n      scatter({ by: \"x\", x: \"x\" })\n    )\n    .mark(rect({ w: 0, cy: \"center\", h: \"size\" }))\n    .layer(ribbon({ fill: \"shade\" })),\n  // line: the median of the draws at each x\n  chart(df)\n    .flow(\n      scatter({ by: \"x\", x: \"x\", y: field(\"y\").median() })\n    )\n    .mark(line({ stroke: INK, strokeWidth: 2 })),\n]);","uses_up":"quantiles and the median of the draws per cell, with one cell per x, with the density of the draws at each band edge","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Coloring bands by density is the density of the draws at each band's two ends, averaged over x per level, which is a function of the distribution, not a picture of draws. The spec spells it out in one derive. Version 1 called this a blend limit and then could not use one.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- chunk stat_lineribbon_density --\nwithr::with_options(list(ggdist.experimental.slab_data_in_intervals = TRUE), print(\n  df %>%\n    ggplot(aes(x = x, y = y, fill_ramp = after_stat(ave(pdf_min + pdf_max, .width)))) +\n    stat_lineribbon(.width = ppoints(50), fill = \"#2171b5\") +\n    scale_fill_ramp_continuous(name = \"density\", guide = guide_rampbar(to = \"#2171b5\")) +\n    labs(\n      title = \"stat_lineribbon(.width = ppoints(50))\",\n      subtitle = 'aes(fill_ramp = after_stat(ave(pdf_min + pdf_max, .width)))'\n    )\n))"},{"id":"ggdist-75-stat-lineribbon-density-smooth","pkg":"ggdist","num":"75","title":"stat_lineribbon(.width = pnorm(seq(-2.5, 2.5, length.out = 50))), fill_ramp = density","source":"lineribbon vignette, chunk stat_lineribbon_density_smooth","img":"catalog/img/ggdist-75-stat-lineribbon-density-smooth.png","more":[],"gofish":"const levels = Array.from({ length: 50 }, (_, i) =>\n  normalCdf(-2.5 + (5 * i) / 49)\n);\nlayer([\n  // bands: one ribbon per level, colored by the density at\n  // its edges\n  chart(df, { color: Color.gradient([\"white\", \"#2171b5\"]) })\n    .flow(\n      derive((rows) => {\n        // at each x and level: the central interval, and\n        // the density at its two ends\n        const bands = Object.values(\n          Object.groupBy(rows, (r) => r.x)\n        ).flatMap((step) =>\n          centralIntervals(step, \"y\", levels).map(\n            (band) => {\n              const [lo, hi] = densityCurve(step, \"y\", {\n                n: 2,\n                range: [\n                  band.center - band.size / 2,\n                  band.center + band.size / 2,\n                ],\n              });\n              return {\n                ...band,\n                edge: lo.density + hi.density,\n              };\n            }\n          )\n        );\n        // ave(pdf_min + pdf_max, .width): the mean over\n        // every x, per level\n        const shade = (p) => {\n          const edges = bands\n            .filter((b) => b.level === p)\n            .map((b) => b.edge);\n          return (\n            edges.reduce((sum, e) => sum + e, 0) /\n            edges.length\n          );\n        };\n        return bands.map((b) => ({\n          ...b,\n          shade: shade(b.level),\n        }));\n      }),\n      group({ by: \"level\" }),\n      scatter({ by: \"x\", x: \"x\" })\n    )\n    .mark(rect({ w: 0, cy: \"center\", h: \"size\" }))\n    .layer(ribbon({ fill: \"shade\" })),\n  // line: the median of the draws at each x\n  chart(df)\n    .flow(\n      scatter({ by: \"x\", x: \"x\", y: field(\"y\").median() })\n    )\n    .mark(line({ stroke: INK, strokeWidth: 2 })),\n]);","uses_up":"quantiles and the median of the draws per cell, with one cell per x, with the density of the draws at each band edge","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Entry 74 with levels spaced to look smooth.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- chunk stat_lineribbon_density_smooth --\nwithr::with_options(list(ggdist.experimental.slab_data_in_intervals = TRUE), print(\n  df %>%\n    ggplot(aes(x = x, y = y, fill_ramp = after_stat(ave(pdf_min + pdf_max, .width)))) +\n    stat_lineribbon(.width = pnorm(seq(-2.5, 2.5, length.out = 50)), fill = \"#2171b5\") +\n    scale_fill_ramp_continuous(name = \"density\", guide = guide_rampbar(to = \"#2171b5\")) +\n    labs(\n      title = \"stat_lineribbon(.width = pnorm(seq(-2.5, 2.5, length.out = 50)))\",\n      subtitle = 'aes(fill_ramp = after_stat(ave(pdf_min + pdf_max, .width)))'\n    )\n))"},{"id":"ggdist-76-stat-lineribbon-2groups-brewer","pkg":"ggdist","num":"76","title":"stat_lineribbon() of two groups, color = g, fill = level (brewer)","source":"lineribbon vignette, chunk stat_lineribbon_2groups_brewer","img":"catalog/img/ggdist-76-stat-lineribbon-2groups-brewer.png","more":[],"gofish":"chart(df2groups, {\n  color: Color.palette([\"#deebf7\", \"#9ecae1\", \"#3182bd\"]),\n})\n  .flow(group({ by: \"g\" }))\n  .mark(lineribbon(\"y\", { along: \"x\", stroke: \"g\" }));","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Two lineribbons; the median line's color is the group.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- needs chunk df_2groups --\ndf_2groups = rbind(\n  mutate(df, g = \"a\"),\n  mutate(df, g = \"b\", y = (y - 2) * 0.5)\n)\n# -- chunk stat_lineribbon_2groups_brewer --\ndf_2groups %>%\n  ggplot(aes(x = x, y = y, color = g)) +\n  stat_lineribbon() +\n  scale_fill_brewer()"},{"id":"ggdist-77-stat-lineribbon-2groups-alpha","pkg":"ggdist","num":"77","title":"stat_lineribbon(aes(fill = g), alpha = 1/4)","source":"lineribbon vignette, chunk stat_lineribbon_2groups_alpha","img":"catalog/img/ggdist-77-stat-lineribbon-2groups-alpha.png","more":[],"gofish":"chart(df2groups)\n  .flow(group({ by: \"g\" }))\n  .mark(\n    lineribbon(\"y\", {\n      along: \"x\",\n      fill: \"g\",\n      stroke: \"g\",\n      opacity: 0.25,\n    })\n  );","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Nested translucent bands in the group's color.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- needs chunk df_2groups --\ndf_2groups = rbind(\n  mutate(df, g = \"a\"),\n  mutate(df, g = \"b\", y = (y - 2) * 0.5)\n)\n# -- chunk stat_lineribbon_2groups_alpha --\ndf_2groups %>%\n  ggplot(aes(x = x, y = y, fill = g)) +\n  stat_lineribbon(alpha = 1/4) +\n  labs(title = \"stat_lineribbon(aes(fill = g), alpha = 1/4)\")"},{"id":"ggdist-78-stat-lineribbon-2groups-ramp","pkg":"ggdist","num":"78","title":"stat_lineribbon(aes(fill = g, fill_ramp = after_stat(level)))","source":"lineribbon vignette, chunk stat_lineribbon_2groups_ramp","img":"catalog/img/ggdist-78-stat-lineribbon-2groups-ramp.png","more":[],"gofish":"// gap: fill_ramp, the group's color lightened by level\nchart(df2groups)\n  .flow(group({ by: \"g\" }))\n  .mark(\n    lineribbon(\"y\", { along: \"x\", fill: \"g\", stroke: \"g\" })\n  );","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Missing: fill_ramp, the group's color lightened by level (entry 32).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- needs chunk df_2groups --\ndf_2groups = rbind(\n  mutate(df, g = \"a\"),\n  mutate(df, g = \"b\", y = (y - 2) * 0.5)\n)\n# -- chunk stat_lineribbon_2groups_ramp --\ndf_2groups %>%\n  ggplot(aes(x = x, y = y, fill = g)) +\n  stat_lineribbon(aes(fill_ramp = after_stat(level))) +\n  labs(title = \"stat_lineribbon(aes(fill = g, fill_ramp = after_stat(level)))\")"},{"id":"ggdist-79-stat-lineribbon-2groups-group-order","pkg":"ggdist","num":"79","title":"stat_lineribbon with order = interaction(level, group)","source":"lineribbon vignette, chunk stat_lineribbon_2groups_group_order","img":"catalog/img/ggdist-79-stat-lineribbon-2groups-group-order.png","more":[],"gofish":"// ggdist draws every group's 95% band first, then 80%, then\n// 50%: level outer, group inner. One lineribbon per group\n// draws group by group, so the 50% band of g = a is under\n// the 95% band of g = b. The definition's own flow could\n// interleave them, by grouping by level before g.\n// gap: fill_ramp, the group's color lightened by level\nchart(df2groups)\n  .flow(group({ by: \"g\" }))\n  .mark(\n    lineribbon(\"y\", { along: \"x\", fill: \"g\", stroke: \"g\" })\n  );","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"ggdist draws every group's widest band first. That is drawing order, which is flow order: group by level, then by g. The lineribbon mark groups by g outside the mark, so it draws one group's bands at a time; the spec says so in a comment. The definition's own flow could interleave them if it took the grouping as an option. Missing: fill_ramp as in entry 78.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- needs chunk df_2groups --\ndf_2groups = rbind(\n  mutate(df, g = \"a\"),\n  mutate(df, g = \"b\", y = (y - 2) * 0.5)\n)\n# -- chunk stat_lineribbon_2groups_group_order --\ndf_2groups %>%\n  ggplot(aes(x = x, y = y, fill = g)) +\n  stat_lineribbon(aes(\n    fill_ramp = after_stat(level),\n    order = after_stat(interaction(level, group))\n  )) +\n  labs(title = \"stat_lineribbon(aes(order = after_stat(interaction(level, group))))\")"},{"id":"ggdist-80-stat-lineribbon-dist","pkg":"ggdist","num":"80","title":"stat_lineribbon(aes(ydist = dist_normal(y_mean, y_sd)))","source":"lineribbon vignette, chunk stat_lineribbon_dist","img":"catalog/img/ggdist-80-stat-lineribbon-dist.png","more":[],"gofish":"const y = dist.normal({ mean: \"y_mean\", sd: \"y_sd\" });\nchart(analyticalDf, {\n  color: Color.palette([\"#deebf7\", \"#9ecae1\", \"#3182bd\"]),\n}).mark(lineribbon(y, { along: \"x\" }));","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The analytic version of entry 72.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk df --\nset.seed(1234)\nn = 5000\n\ndf = tibble(\n  .draw = 1:n,\n  intercept = rnorm(n, 3, 1),\n  slope = rnorm(n, 1, 0.25),\n  x = list(-4:5),\n  y = Map(function(x, y) x + y * -4:5, intercept, slope)\n) %>%\n  unnest(c(x, y))\n# -- needs chunk analytical_df --\nanalytical_df = tibble(\n  x = -4:5,\n  y_mean = 3 + x,\n  y_sd = sqrt(x^2/10 + 1)\n)\nanalytical_df\n# -- chunk stat_lineribbon_dist --\nanalytical_df %>%\n  ggplot(aes(x = x, ydist = dist_normal(y_mean, y_sd))) +\n  stat_lineribbon() +\n  scale_fill_brewer()"},{"id":"ggdist-81-curve-draws","pkg":"ggdist","num":"81","title":"Eleven curves (draws) as lines, alpha = 0.2","source":"lineribbon vignette, chunk curve_draws","img":"catalog/img/ggdist-81-curve-draws.png","more":[],"gofish":"chart(curves, { schema: { y: { draws: \".draw\" } } })\n  .flow(\n    group({ by: \".draw\" }),\n    scatter({ by: \"x\", x: \"x\", y: \"y\" })\n  )\n  .mark(line({ opacity: 0.2 }));","uses_up":"group({ by: \".draw\" }), the plain overlay, over draws declared shared in the schema, 11 draws","fit":"fits","verdict":"ok","v1_fit":"fits","note":"An overlay of whole-curve draws, as in entry 69.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk curve_draws --\nk = 11 # number of curves\nn = 501\ndf = tibble(\n  .draw = 1:k,\n  mean = seq(-5, 5, length.out = k),\n  x = list(seq(-15, 15, length.out = n))\n) %>%\n  unnest(x) %>%\n  mutate(y = dnorm(x, mean, 3)/max(dnorm(x, mean, 3)))\n\ndf %>%\n  ggplot(aes(x = x, y = y)) +\n  geom_line(aes(group = .draw), alpha = 0.2)"},{"id":"ggdist-82-pointwise-ribbon","pkg":"ggdist","num":"82","title":"50% pointwise intervals with point_interval() over the curves","source":"lineribbon vignette, chunk pointwise_ribbon","img":"catalog/img/ggdist-82-pointwise-ribbon.png","more":[],"gofish":"layer([\n  chart(curves).mark(\n    lineribbon(\"y\", {\n      along: \"x\",\n      levels: [0.5],\n      fill: \"#3182bd\",\n    })\n  ),\n  chart(curves, { schema: { y: { draws: \".draw\" } } })\n    .flow(\n      group({ by: \".draw\" }),\n      scatter({ by: \"x\", x: \"x\", y: \"y\" })\n    )\n    .mark(line({ opacity: 0.15 })),\n]);","uses_up":"band: quantiles and the median of the draws per cell, with one cell per x; curves: group({ by: \".draw\" }), the plain overlay, over draws declared shared in the schema","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The pointwise band is narrow in the middle where the curves cross, which is the point of the next entry. The band is the central interval of the draws at each x, and the line goes through the median of the draws at each x, which rule 3.2 treats as a summary. Version 1's rule warned here.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 81 --\nk = 11 # number of curves\nn = 501\ndf = tibble(\n  .draw = 1:k,\n  mean = seq(-5, 5, length.out = k),\n  x = list(seq(-15, 15, length.out = n))\n) %>%\n  unnest(x) %>%\n  mutate(y = dnorm(x, mean, 3)/max(dnorm(x, mean, 3)))\n\ndf %>%\n  ggplot(aes(x = x, y = y)) +\n  geom_line(aes(group = .draw), alpha = 0.2)\n# -- chunk pointwise_ribbon --\ndf %>%\n  group_by(x) %>%\n  median_qi(y, .width = .5) %>%\n  ggplot(aes(x = x, y = y)) +\n  geom_lineribbon(aes(ymin = .lower, ymax = .upper)) +\n  geom_line(aes(group = .draw), alpha = 0.15, data = df) +\n  scale_fill_brewer() +\n  ggtitle(\"50% pointwise intervals with point_interval()\")"},{"id":"ggdist-83-curvewise-ribbon","pkg":"ggdist","num":"83","title":"50% curvewise intervals with curve_interval()","source":"lineribbon vignette, chunk curvewise_ribbon","img":"catalog/img/ggdist-83-curvewise-ribbon.png","more":[],"gofish":"// curves: one row per .draw and x, draws shared across x\nconst kept = (width) =>\n  chart(curves, { schema: { y: { draws: \".draw\" } } })\n    .flow(\n      // a summary per draw: the mean over x of the\n      // pointwise depth min(level, 1 - level), then keep\n      // the deepest share of the draws. gap: a summary\n      // whose result a later filter reads; written as a\n      // derive over the rows\n      derive(\n        keepDeepest({\n          by: \".draw\",\n          depth: (r) => Math.min(r.level, 1 - r.level),\n          share: width,\n        })\n      ),\n      scatter({\n        by: \"x\",\n        x: \"x\",\n        yMin: field(\"y\").min(),\n        yMax: field(\"y\").max(),\n      })\n    )\n    .mark(rect({ w: 0 }))\n    .layer(ribbon({ fill: \"#3182bd\" }));\nlayer([\n  kept(0.5),\n  chart(curves, { schema: { y: { draws: \".draw\" } } })\n    .flow(\n      group({ by: \".draw\" }),\n      scatter({ by: \"x\", x: \"x\", y: \"y\" })\n    )\n    .mark(line({ opacity: 0.15 })),\n]);","uses_up":"a summary per draw (mean depth from level), a filter on its rank, then the min and max of the draws per x","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"curve_interval's default, mhd, scores each whole curve by its mean halfspace depth over x. The pointwise depth is min(level, 1 - level), so the score is a summary per draw of the level column, and the band is the min and max of the kept draws at each x. That is the 'summary per draw' row of the table, and version 1 could not write it. The missing piece is general: a summary whose result a later step reads, written here as a derive (keepDeepest is plain JavaScript over the rows). Because it is a derive, the checker cannot see that it keeps whole draws.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk 81 --\nk = 11 # number of curves\nn = 501\ndf = tibble(\n  .draw = 1:k,\n  mean = seq(-5, 5, length.out = k),\n  x = list(seq(-15, 15, length.out = n))\n) %>%\n  unnest(x) %>%\n  mutate(y = dnorm(x, mean, 3)/max(dnorm(x, mean, 3)))\n\ndf %>%\n  ggplot(aes(x = x, y = y)) +\n  geom_line(aes(group = .draw), alpha = 0.2)\n# -- chunk curvewise_ribbon --\ndf %>%\n  group_by(x) %>%\n  curve_interval(y, .width = .5) %>%\n  ggplot(aes(x = x, y = y)) +\n  geom_lineribbon(aes(ymin = .lower, ymax = .upper)) +\n  geom_line(aes(group = .draw), alpha = 0.15, data = df) +\n  scale_fill_brewer() +\n  ggtitle(\"50% curvewise intervals with curve_interval()\")"},{"id":"ggdist-84-pointwise-curvewise","pkg":"ggdist","num":"84","title":"point_interval() vs curve_interval() on 1000 curves","source":"lineribbon vignette, chunk pointwise_curvewise","img":"catalog/img/ggdist-84-pointwise-curvewise.png","more":[],"gofish":"// largeCurves: one row per .draw and x, draws shared across x\nconst kept = (width) =>\n  chart(largeCurves, { schema: { y: { draws: \".draw\" } } })\n    .flow(\n      // a summary per draw: the mean over x of the\n      // pointwise depth min(level, 1 - level), then keep\n      // the deepest share of the draws. gap: a summary\n      // whose result a later filter reads; written as a\n      // derive over the rows\n      derive(\n        keepDeepest({\n          by: \".draw\",\n          depth: (r) => Math.min(r.level, 1 - r.level),\n          share: width,\n        })\n      ),\n      scatter({\n        by: \"x\",\n        x: \"x\",\n        yMin: field(\"y\").min(),\n        yMax: field(\"y\").max(),\n      })\n    )\n    .mark(rect({ w: 0 }))\n    .layer(ribbon({ fill: \"#3182bd\" }));\nconst pointwise = layer([\n  chart([{ y: 1 }]).mark(\n    rect({ y: \"y\", h: 1, strokeDasharray: \"4 3\" })\n  ),\n  chart(largeCurves, {\n    color: Color.palette([\"#deebf7\", \"#9ecae1\", \"#3182bd\"]),\n  }).mark(lineribbon(\"y\", { along: \"x\" })),\n]);\nconst curvewise = layer([kept(0.95), kept(0.8), kept(0.5)]);\nspread({ dir: \"y\", spacing: 16 }, [pointwise, curvewise]);","uses_up":"pointwise: quantiles and the median of the draws per cell, with one cell per x; curvewise: as entry 83","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"The pointwise panel fits. The curvewise panel is entry 83 at three widths, with the same gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- chunk pointwise_curvewise --\nk = 1000 # number of curves\nlarge_df = tibble(\n  .draw = 1:k,\n  mean = seq(-5,5, length.out = k),\n  x = list(seq(-15,15,length.out = n))\n) %>%\n  unnest(x) %>%\n  mutate(y = dnorm(x, mean, 3)/max(dnorm(x, mean, 3)))\n\npointwise_plot = large_df %>%\n  group_by(x) %>%\n  median_qi(y, .width = c(.5, .8, .95)) %>%\n  ggplot(aes(x = x, y = y)) +\n  geom_hline(yintercept = 1, color = \"gray75\", linetype = \"dashed\") +\n  geom_lineribbon(aes(ymin = .lower, ymax = .upper)) +\n  scale_fill_brewer() +\n  ggtitle(\"point_interval()\")\n\ncurvewise_plot = large_df %>%\n  group_by(x) %>%\n  curve_interval(y, .width = c(.5, .8, .95)) %>%\n  ggplot(aes(x = x, y = y)) +\n  geom_hline(yintercept = 1, color = \"gray75\", linetype = \"dashed\") +\n  geom_lineribbon(aes(ymin = .lower, ymax = .upper)) +\n  scale_fill_brewer() +\n  ggtitle(\"curve_interval()\")\n\npointwise_plot / curvewise_plot"},{"id":"ggdist-85-mtcars-spaghetti","pkg":"ggdist","num":"85","title":"mtcars bootstrap loess fits as spaghetti, with the data","source":"lineribbon vignette, chunk mtcars_spaghetti","img":"catalog/img/ggdist-85-mtcars-spaghetti.png","more":[],"gofish":"layer([\n  chart(\n    mtcarsBoot.filter((d) => d[\".draw\"] < 400),\n    { schema: { hp: { draws: \".draw\" } } }\n  )\n    .flow(\n      group({ by: \".draw\" }),\n      scatter({ by: \"mpg\", x: \"mpg\", y: \"hp\" })\n    )\n    .mark(line({ opacity: 0.1 })),\n  chart(mtcars)\n    .flow(scatter({ x: \"mpg\", y: \"hp\" }))\n    .mark(circle({ r: 1.5 })),\n]);","uses_up":"group({ by: \".draw\" }), the plain overlay, over draws declared shared in the schema, 400 bootstrap draws precomputed in R","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The bootstrap (resampling mtcars and refitting loess) is done in data preparation. In GoFish it would be resample plus a fit per draw; version 2 does not change that.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk mtcars_boot --\nset.seed(1234)\nn = 4000\nmpg = seq(min(mtcars$mpg), max(mtcars$mpg), length.out = 100)\n\nmtcars_boot = tibble(\n  .draw = 1:n,\n  m = lapply(.draw, function(d) loess(\n    hp ~ mpg,\n    span = 0.9,\n    # this lets us predict outside the range of the data\n    control = loess.control(surface = \"direct\"),\n    data = slice_sample(mtcars, prop = 1, replace = TRUE)\n  )),\n  hp = lapply(m, predict, newdata = tibble(mpg)),\n  mpg = list(mpg)\n) %>%\n  select(-m) %>%\n  unnest(c(hp, mpg))\n# -- chunk mtcars_spaghetti --\nmtcars_boot %>%\n  filter(.draw < 400) %>%\n  ggplot(aes(x = mpg, y = hp)) +\n  geom_line(aes(group = .draw), alpha = 1/10) +\n  geom_point(data = mtcars) +\n  coord_cartesian(ylim = c(0, 400))"},{"id":"ggdist-86-mtcars-point-interval","pkg":"ggdist","num":"86","title":"stat_lineribbon(.width = c(.5, .7, .9)) of the bootstrap fits, with the data","source":"lineribbon vignette, chunk mtcars_point_interval","img":"catalog/img/ggdist-86-mtcars-point-interval.png","more":[],"gofish":"layer([\n  chart(mtcarsBoot, {\n    color: Color.palette([\"#deebf7\", \"#9ecae1\", \"#3182bd\"]),\n  }).mark(\n    lineribbon(\"hp\", {\n      along: \"mpg\",\n      levels: [0.9, 0.7, 0.5],\n    })\n  ),\n  chart(mtcars)\n    .flow(scatter({ x: \"mpg\", y: \"hp\" }))\n    .mark(circle({ r: 1.5 })),\n]);","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Pointwise bands over shared draws. Each band is the central interval of the draws at each x, and the line goes through the median of the draws at each x, which rule 3.2 treats as a summary. Version 1's rule warned here.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk mtcars_boot --\nset.seed(1234)\nn = 4000\nmpg = seq(min(mtcars$mpg), max(mtcars$mpg), length.out = 100)\n\nmtcars_boot = tibble(\n  .draw = 1:n,\n  m = lapply(.draw, function(d) loess(\n    hp ~ mpg,\n    span = 0.9,\n    # this lets us predict outside the range of the data\n    control = loess.control(surface = \"direct\"),\n    data = slice_sample(mtcars, prop = 1, replace = TRUE)\n  )),\n  hp = lapply(m, predict, newdata = tibble(mpg)),\n  mpg = list(mpg)\n) %>%\n  select(-m) %>%\n  unnest(c(hp, mpg))\n# -- chunk mtcars_point_interval --\nmtcars_boot %>%\n  ggplot(aes(x = mpg, y = hp)) +\n  stat_lineribbon(.width = c(.5, .7, .9)) +\n  geom_point(data = mtcars) +\n  scale_fill_brewer() +\n  coord_cartesian(ylim = c(0, 400))"},{"id":"ggdist-87-mtcars-curve-interval","pkg":"ggdist","num":"87","title":"curve_interval(hp, .width = c(.5, .7, .9)) of the bootstrap fits","source":"lineribbon vignette, chunk mtcars_curve_interval","img":"catalog/img/ggdist-87-mtcars-curve-interval.png","more":[],"gofish":"// mtcarsBoot: one row per .draw and x, draws shared across x\nconst kept = (width) =>\n  chart(mtcarsBoot, { schema: { hp: { draws: \".draw\" } } })\n    .flow(\n      // a summary per draw: the mean over x of the\n      // pointwise depth min(level, 1 - level), then keep\n      // the deepest share of the draws. gap: a summary\n      // whose result a later filter reads; written as a\n      // derive over the rows\n      derive(\n        keepDeepest({\n          by: \".draw\",\n          depth: (r) => Math.min(r.level, 1 - r.level),\n          share: width,\n        })\n      ),\n      scatter({\n        by: \"mpg\",\n        x: \"mpg\",\n        yMin: field(\"hp\").min(),\n        yMax: field(\"hp\").max(),\n      })\n    )\n    .mark(rect({ w: 0 }))\n    .layer(ribbon({ fill: \"#3182bd\" }));\nlayer([\n  kept(0.9),\n  kept(0.7),\n  kept(0.5),\n  chart(mtcars)\n    .flow(scatter({ x: \"mpg\", y: \"hp\" }))\n    .mark(circle({ r: 1.5 })),\n]);","uses_up":"as entry 83","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"Curvewise intervals with the default .interval = 'mhd', at three widths. Same spelling and the same gap as entry 83.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk mtcars_boot --\nset.seed(1234)\nn = 4000\nmpg = seq(min(mtcars$mpg), max(mtcars$mpg), length.out = 100)\n\nmtcars_boot = tibble(\n  .draw = 1:n,\n  m = lapply(.draw, function(d) loess(\n    hp ~ mpg,\n    span = 0.9,\n    # this lets us predict outside the range of the data\n    control = loess.control(surface = \"direct\"),\n    data = slice_sample(mtcars, prop = 1, replace = TRUE)\n  )),\n  hp = lapply(m, predict, newdata = tibble(mpg)),\n  mpg = list(mpg)\n) %>%\n  select(-m) %>%\n  unnest(c(hp, mpg))\n# -- chunk mtcars_curve_interval --\nmtcars_boot %>%\n  group_by(mpg) %>%\n  curve_interval(hp, .width = c(.5, .7, .9)) %>%\n  ggplot(aes(x = mpg, y = hp)) +\n  geom_lineribbon(aes(ymin = .lower, ymax = .upper)) +\n  geom_point(data = mtcars) +\n  scale_fill_brewer() +\n  coord_cartesian(ylim = c(0, 400))"},{"id":"ggdist-88-mtcars-curve-interval-bd","pkg":"ggdist","num":"88","title":"curve_interval(..., .interval = 'bd-mbd') of the bootstrap fits","source":"lineribbon vignette, chunk mtcars_curve_interval_bd","img":"catalog/img/ggdist-88-mtcars-curve-interval-bd.png","more":[],"gofish":"// Not writable: band depth compares pairs of whole\n// draws. keepDeepest's depth would have to be, for\n// each draw, the share of pairs of other draws whose\n// band contains it at every x. That is not a summary of\n// one draw's rows, and not a function of level.","uses_up":"(would be) a statistic over pairs of whole draws, a filter on its rank, then the min and max of the draws per x","fit":"does-not-fit","verdict":"ok","v1_fit":"does-not-fit","note":"bd-mbd ranks curves by band depth: the share of pairs of other curves whose band contains a curve at every x, with modified band depth to break ties. The table's 'summary per draw' covers mhd and modified band depth, which are means over x of functions of level. Band depth itself needs every pair of draws at once, so it is not a summary per draw.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk mtcars_boot --\nset.seed(1234)\nn = 4000\nmpg = seq(min(mtcars$mpg), max(mtcars$mpg), length.out = 100)\n\nmtcars_boot = tibble(\n  .draw = 1:n,\n  m = lapply(.draw, function(d) loess(\n    hp ~ mpg,\n    span = 0.9,\n    # this lets us predict outside the range of the data\n    control = loess.control(surface = \"direct\"),\n    data = slice_sample(mtcars, prop = 1, replace = TRUE)\n  )),\n  hp = lapply(m, predict, newdata = tibble(mpg)),\n  mpg = list(mpg)\n) %>%\n  select(-m) %>%\n  unnest(c(hp, mpg))\n# -- chunk mtcars_curve_interval_bd --\nmtcars_boot %>%\n  group_by(mpg) %>%\n  curve_interval(hp, .width = c(.5, .7, .9), .interval = \"bd-mbd\") %>%\n  ggplot(aes(x = mpg, y = hp)) +\n  geom_lineribbon(aes(ymin = .lower, ymax = .upper)) +\n  geom_point(data = mtcars) +\n  scale_fill_brewer() +\n  coord_cartesian(ylim = c(0, 400))"},{"id":"ggdist-89-data-plot","pkg":"ggdist","num":"89","title":"The ABC data: response by condition","source":"freq-uncertainty-vis vignette, chunk data_plot","img":"catalog/img/ggdist-89-data-plot.png","more":[],"gofish":"chart(ABC)\n  .flow(\n    spread({ by: \"condition\", dir: \"y\" }),\n    scatter({ x: \"response\" })\n  )\n  .mark(circle({ r: 2, opacity: 0.5 }));","uses_up":"no draws: plain data points","fit":"fits","verdict":"ok","v1_fit":"fits","note":"No uncertainty is shown; it is a strip plot of the raw data.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk data_gen --\nset.seed(5)\nn = 10\nn_condition = 5\nABC =\n  tibble(\n    condition = rep(c(\"A\",\"B\",\"C\",\"D\",\"E\"), n),\n    response = rnorm(n * 5, c(0,1,2,1,-1), 0.5)\n  )\n# -- needs chunk m_ABC --\nm_ABC = lm(response ~ condition, data = ABC)\n# -- chunk data_plot --\nABC %>%\n  ggplot(aes(x = response, y = condition)) +\n  geom_point(alpha = 0.5) +\n  ylab(\"condition\")"},{"id":"ggdist-90-halfeye","pkg":"ggdist","num":"90","title":"stat_halfeye() of Student t sampling distributions of lm coefficients","source":"freq-uncertainty-vis vignette, chunk halfeye","img":"catalog/img/ggdist-90-halfeye.png","more":[],"gofish":"const x = dist.studentT({\n  df: \"df\",\n  mu: \"estimate\",\n  sigma: \"std.error\",\n});\nchart(tidyCoefs)\n  .flow(spread({ by: \"term\", dir: \"y\" }))\n  .mark(layer([slab(x), interval(x)]));","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A half-eye of a confidence distribution, with a t family in the dist namespace.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk data_gen --\nset.seed(5)\nn = 10\nn_condition = 5\nABC =\n  tibble(\n    condition = rep(c(\"A\",\"B\",\"C\",\"D\",\"E\"), n),\n    response = rnorm(n * 5, c(0,1,2,1,-1), 0.5)\n  )\n# -- needs chunk m_ABC --\nm_ABC = lm(response ~ condition, data = ABC)\n# -- chunk halfeye --\nm_ABC %>%\n  tidy() %>%\n  ggplot(aes(y = term)) +\n  stat_halfeye(\n    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = estimate, sigma = std.error))\n  )"},{"id":"ggdist-91-halfeye-with-data","pkg":"ggdist","num":"91","title":"stat_halfeye(scale = .5) of fitted means, with the data as ticks below","source":"freq-uncertainty-vis vignette, chunk halfeye_with_data","img":"catalog/img/ggdist-91-halfeye-with-data.png","more":[],"gofish":"const x = dist.studentT({\n  df: \"df\",\n  mu: \".fitted\",\n  sigma: \".se.fit\",\n});\nlayer([\n  chart(fitted)\n    .flow(spread({ by: \"condition\", dir: \"y\" }))\n    .mark(layer({ h: 30 }, [slab(x), interval(x)])),\n  // the data as ticks below each half-eye. gap: placed by a\n  // hand offset, not from the slab's zero line\n  chart(ABC)\n    .flow(\n      spread({ by: \"condition\", dir: \"y\" }).translate({\n        y: -10,\n      }),\n      scatter({ x: \"response\" })\n    )\n    .mark(rect({ w: 1, h: 8 })),\n]);","uses_up":"summaries per cell: the density curve of the draws for the slab, and quantiles and the median of the draws for the interval (exact on a Dist, which is n = Infinity; over the rows on a sample)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The data ticks sit just below each half-eye's baseline; as with the raincloud in elaborations.md, placing a second chart's rows relative to the slab's zero line is not expressible, so this relies on a hand offset that matches only if both spreads give identical rows.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk data_gen --\nset.seed(5)\nn = 10\nn_condition = 5\nABC =\n  tibble(\n    condition = rep(c(\"A\",\"B\",\"C\",\"D\",\"E\"), n),\n    response = rnorm(n * 5, c(0,1,2,1,-1), 0.5)\n  )\n# -- needs chunk m_ABC --\nm_ABC = lm(response ~ condition, data = ABC)\n# -- chunk halfeye_with_data --\nABC %>%\n  expand(condition) %>%\n  augment(m_ABC, newdata = ., se_fit = TRUE) %>%\n  ggplot(aes(y = condition)) +\n  stat_halfeye(\n    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit)),\n    scale = .5\n  ) +\n  # we'll add the data back in too (scale = .5 above adjusts the halfeye height so\n  # that the data fit in as well)\n  geom_point(aes(x = response), data = ABC, pch = \"|\", size = 2, position = position_nudge(y = -.15))"},{"id":"ggdist-92-gradientinterval","pkg":"ggdist","num":"92","title":"stat_gradientinterval(fill_type = 'gradient') of fitted means","source":"freq-uncertainty-vis vignette, chunk gradientinterval","img":"catalog/img/ggdist-92-gradientinterval.png","more":[],"gofish":"const x = dist.studentT({\n  df: \"df\",\n  mu: \".fitted\",\n  sigma: \".se.fit\",\n});\nchart(fitted)\n  .flow(spread({ by: \"condition\", dir: \"y\" }))\n  .mark(\n    layer({ h: 30 }, [gradientinterval(x), interval(x)])\n  );","uses_up":"the density curve of the draws per cell, divided by its peak and read as opacity along the slab (the second kind of ggdist mark)","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"The gradient interval of entry 18 on t distributions: the density curve of the draws divided by its peak, read as opacity. GoFish has no opacity that varies along one region, so the spec marks it as a gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk data_gen --\nset.seed(5)\nn = 10\nn_condition = 5\nABC =\n  tibble(\n    condition = rep(c(\"A\",\"B\",\"C\",\"D\",\"E\"), n),\n    response = rnorm(n * 5, c(0,1,2,1,-1), 0.5)\n  )\n# -- needs chunk m_ABC --\nm_ABC = lm(response ~ condition, data = ABC)\n# -- chunk gradientinterval --\nABC %>%\n  expand(condition) %>%\n  augment(m_ABC, newdata = ., se_fit = TRUE) %>%\n  ggplot(aes(y = condition)) +\n  stat_gradientinterval(\n    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit)),\n    scale = .5, fill_type = \"gradient\"\n  )"},{"id":"ggdist-93-ccdfinterval","pkg":"ggdist","num":"93","title":"stat_ccdfinterval() of fitted means","source":"freq-uncertainty-vis vignette, chunk ccdfinterval","img":"catalog/img/ggdist-93-ccdfinterval.png","more":[],"gofish":"const x = dist.studentT({\n  df: \"df\",\n  mu: \".fitted\",\n  sigma: \".se.fit\",\n});\nchart(fitted)\n  .flow(spread({ by: \"condition\", dir: \"y\" }))\n  .mark(\n    layer([\n      // the bar starts at the axis's lower limit, -1.5, as\n      // ggdist's does\n      ccdf(x, { density: { range: [-1.5] } }),\n      interval(x),\n    ])\n  );","uses_up":"summaries per cell: the CDF of the draws as thickness (ccdf), and quantiles and the median of the draws","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The ccdf mark of section 1, which is a summary of the draws, so it is exact on a Dist. The bar must start at a fixed point at or below the support; ggdist uses the axis's lower limit, -1.5 here, which the spec sets as the curve's range. A bar from 0 would be wrong, since the distributions cross 0. Bars sorted by level tend to this picture as n grows, but a spread by level at n = Infinity is an error under rule 3.1.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk data_gen --\nset.seed(5)\nn = 10\nn_condition = 5\nABC =\n  tibble(\n    condition = rep(c(\"A\",\"B\",\"C\",\"D\",\"E\"), n),\n    response = rnorm(n * 5, c(0,1,2,1,-1), 0.5)\n  )\n# -- needs chunk m_ABC --\nm_ABC = lm(response ~ condition, data = ABC)\n# -- chunk ccdfinterval --\nABC %>%\n  expand(condition) %>%\n  augment(m_ABC, newdata = ., se_fit = TRUE) %>%\n  ggplot(aes(y = condition)) +\n  stat_ccdfinterval(\n    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit))\n  )"},{"id":"ggdist-94-dotplot","pkg":"ggdist","num":"94","title":"stat_dots(quantiles = 100) of fitted means","source":"freq-uncertainty-vis vignette, chunk dotplot","img":"catalog/img/ggdist-94-dotplot.png","more":[],"gofish":"const x = dist.studentT({\n  df: \"df\",\n  mu: \".fitted\",\n  sigma: \".se.fit\",\n});\nchart(sample(fitted, { n: 100, at: \"quantiles\" }))\n  .flow(\n    spread({ by: \"condition\", dir: \"y\" }),\n    partition({ by: x.bin(Bin.step(0.05)), dir: \"x\" }), // chosen by hand; ggdist picks the width so the tallest stack fits\n    stack({ dir: \"y\" })\n  )\n  .mark(circle({ r: 1.5 }));","uses_up":"sample(data, { n: 100, at: \"quantiles\" }), then partition by a bin and stack (finite n)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Quantile dots of a t distribution: sample at 100 evenly spaced levels, which version 1 needed a derive for. Missing: the dot-binning gap.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk data_gen --\nset.seed(5)\nn = 10\nn_condition = 5\nABC =\n  tibble(\n    condition = rep(c(\"A\",\"B\",\"C\",\"D\",\"E\"), n),\n    response = rnorm(n * 5, c(0,1,2,1,-1), 0.5)\n  )\n# -- needs chunk m_ABC --\nm_ABC = lm(response ~ condition, data = ABC)\n# -- chunk dotplot --\nABC %>%\n  expand(condition) %>%\n  augment(m_ABC, newdata = ., se_fit = TRUE) %>%\n  ggplot(aes(y = condition)) +\n  stat_dots(\n    aes(xdist = dist_student_t(df = df.residual(m_ABC), mu = .fitted, sigma = .se.fit)),\n    quantiles = 100\n  )"},{"id":"ggdist-95-lineribbon","pkg":"ggdist","num":"95","title":"stat_lineribbon of a t confidence band per cyl, alpha = 1/4, with the data","source":"freq-uncertainty-vis vignette, chunk lineribbon","img":"catalog/img/ggdist-95-lineribbon.png","more":[],"gofish":"const y = dist.studentT({\n  df: \"df\",\n  mu: \".fitted\",\n  sigma: \".se.fit\",\n});\nlayer([\n  chart(fittedMpg, { color: Color.palette(\"Set2\") })\n    .flow(group({ by: \"cyl\" }))\n    .mark(\n      lineribbon(y, {\n        along: \"hp\",\n        fill: \"cyl\",\n        stroke: \"cyl\",\n        opacity: 0.25,\n      })\n    ),\n  chart(mtcars)\n    .flow(scatter({ x: \"hp\", y: \"mpg\" }))\n    .mark(circle({ r: 1.5, fill: \"cyl\" })),\n]);","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Three nested translucent bands per cylinder count. The fill and stroke use two palettes in ggdist (Set2 and Dark2) for one field, which GoFish's single color scale per field cannot do; a minor color difference.","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk m_mpg --\nm_mpg = lm(mpg ~ hp * cyl, data = mtcars)\n# -- chunk lineribbon --\nmtcars %>%\n  group_by(cyl) %>%\n  expand(hp = seq(min(hp), max(hp), length.out = 101)) %>%\n  augment(m_mpg, newdata = ., se_fit = TRUE) %>%\n  ggplot(aes(x = hp, fill = ordered(cyl), color = ordered(cyl))) +\n  stat_lineribbon(\n    aes(ydist = dist_student_t(df = df.residual(m_mpg), mu = .fitted, sigma = .se.fit)),\n    alpha = 1/4\n  ) +\n  geom_point(aes(y = mpg), data = mtcars) +\n  scale_fill_brewer(palette = \"Set2\") +\n  scale_color_brewer(palette = \"Dark2\") +\n  labs(\n    color = \"cyl\",\n    fill = \"cyl\",\n    y = \"mpg\"\n  )"},{"id":"ggdist-96-lineribbon-lightened","pkg":"ggdist","num":"96","title":"stat_lineribbon with fill = cyl, fill_ramp = level, with the data","source":"freq-uncertainty-vis vignette, chunk lineribbon_lightened","img":"catalog/img/ggdist-96-lineribbon-lightened.png","more":[],"gofish":"const y = dist.studentT({\n  df: \"df\",\n  mu: \".fitted\",\n  sigma: \".se.fit\",\n});\n// gap: fill_ramp, the cylinder count's color lightened by level\nlayer([\n  chart(fittedMpg)\n    .flow(group({ by: \"cyl\" }))\n    .mark(\n      lineribbon(y, {\n        along: \"hp\",\n        fill: \"cyl\",\n        stroke: \"cyl\",\n      })\n    ),\n  chart(mtcars)\n    .flow(scatter({ x: \"hp\", y: \"mpg\" }))\n    .mark(circle({ r: 1.5, fill: \"cyl\" })),\n]);","uses_up":"quantiles and the median of the draws per cell, with one cell per x","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Missing: fill_ramp (entry 32).","r":"# setup: library(dplyr); library(tidyr); library(distributional);\n#        library(ggdist); library(ggplot2); library(patchwork); library(broom)\n#        theme_set(theme_ggdist())\n# -- needs chunk m_mpg --\nm_mpg = lm(mpg ~ hp * cyl, data = mtcars)\n# -- chunk lineribbon_lightened --\nmtcars %>%\n  group_by(cyl) %>%\n  expand(hp = seq(min(hp), max(hp), length.out = 101)) %>%\n  augment(m_mpg, newdata = ., se_fit = TRUE) %>%\n  ggplot(aes(x = hp, color = ordered(cyl))) +\n  stat_lineribbon(aes(\n    ydist = dist_student_t(df = df.residual(m_mpg), mu = .fitted, sigma = .se.fit),\n    fill = ordered(cyl),\n    fill_ramp = after_stat(level)\n  )) +\n  geom_point(aes(y = mpg), data = mtcars) +\n  scale_fill_brewer(palette = \"Set2\") +\n  scale_color_brewer(palette = \"Dark2\") +\n  labs(\n    color = \"cyl\",\n    fill = \"cyl\",\n    y = \"mpg\"\n  )"},{"id":"ggdibbler-01","pkg":"ggdibbler","num":"01","title":"Uncertain contours of faithfuld","source":"README","img":"catalog/img/ggdibbler-01-readme-contour.png","more":[],"gofish":"chart(sample(uncertainFaithfuld, { n: 10 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    contour({\n      x: \"waiting\",\n      y: \"eruptions\",\n      z: \"density0\",\n      opacity: 0.2,\n    }),\n  ); // gap: contour stat and mark","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Contour lines per draw, painted over each other at alpha 0.2. GoFish has no contour stat (marching squares over a grid), which has nothing to do with draws. Each contour is a stat over many cells of one draw, so rule 3.2, which is about marks that join rows, does not fire (see the summary on stats per draw).","r":"ggplot(uncertain_faithfuld, aes(waiting, eruptions, z = density0)) +\n  geom_contour_sample(alpha = 0.2)"},{"id":"ggdibbler-02","pkg":"ggdibbler","num":"02","title":"Raster of faithfuld density, some error (identity_dodge)","source":"README; Rd geom_raster_sample ex 1; paper Fig 5c","img":"catalog/img/ggdibbler-02-raster-faithfuld.png","more":[],"gofish":"chart(sample(uncertainFaithfuld, { n: 10 }))\n  .flow(\n    table({ by: { x: \"waiting\", y: \"eruptions\" } }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ fill: \"density\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"identity_dodge: the grid cells are placed by the table, and each cell is cut into 10 strips, one per draw. Merged: Rd geom_raster_sample example 1 (no title/theme); paper Fig 5c (palette, title).","r":"ggplot(uncertain_faithfuld, aes(waiting, eruptions)) +\n  geom_raster_sample(aes(fill = density))"},{"id":"ggdibbler-03","pkg":"ggdibbler","num":"03","title":"Raster of faithfuld density, more error","source":"README; paper Fig 5d","img":"catalog/img/ggdibbler-03-raster-faithfuld-more.png","more":[],"gofish":"chart(sample(uncertainFaithfuld, { n: 10 }))\n  .flow(\n    table({ by: { x: \"waiting\", y: \"eruptions\" } }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ fill: \"density2\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Same flow as the previous entry on the noisier column. Merged: paper Fig 5d (palette, title).","r":"ggplot(uncertain_faithfuld, aes(waiting, eruptions)) +\n  geom_raster_sample(aes(fill = density2))"},{"id":"ggdibbler-04","pkg":"ggdibbler","num":"04","title":"geom_bar_sample stack on deterministic mpg","source":"README","img":"catalog/img/ggdibbler-04-readme-stack-deterministic.png","more":[],"gofish":"chart(mpg)\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    stack({ by: \"drv\", dir: \"y\" }),\n  )\n  .mark(rect({ h: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"nothing: no Dist column, so no sample step","fit":"fits","verdict":"ok","v1_fit":"fits","note":"ggdibbler on plain data draws nothing and gives the plain stacked bar. In GoFish that is the chart without sample. Version 2 still does not say what sample does to a table with no Dist; the identity is the natural rule.","r":"ggplot(mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), position = \"stack\")"},{"id":"ggdibbler-05","pkg":"ggdibbler","num":"05","title":"Uncertain mpg counts, stack_identity","source":"README; Rd position_stack_nested ex 3","img":"catalog/img/ggdibbler-05-stack-identity.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n    stack({ by: \"drv\", dir: \"y\" }),\n  )\n  .mark(\n    rect({\n      h: field(\"drv\").count(),\n      fill: \"drv\",\n      opacity: 0.15,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_identity: each draw is a full stacked bar, and the draws are painted over each other at alpha 0.15. sample comes first because class itself is random. Merged: Rd position_stack_nested example 3 (alpha 0.2 instead of 0.15).","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), alpha = 0.15, position = \"stack_identity\")"},{"id":"ggdibbler-06","pkg":"ggdibbler","num":"06","title":"Uncertain mpg counts, stack_dodge","source":"README; Rd position_stack_nested ex 4","img":"catalog/img/ggdibbler-06-stack-dodge.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n    stack({ by: \"drv\", dir: \"y\" }),\n  )\n  .mark(rect({ h: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_dodge: the draw spread is outside the group stack, so each thin bar is one draw's whole stack. Merged: Rd position_stack_nested example 4 (byte-identical plot code; README adds theme and title).","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), position = \"stack_dodge\")"},{"id":"ggdibbler-07","pkg":"ggdibbler","num":"07","title":"Iowa temperature map, subdivided, with borders","source":"README","img":"catalog/img/ggdibbler-07-readme-sf-map.png","more":[],"gofish":"const temp = dist.normal({\n  mean: \"tempMean\",\n  sd: \"tempSe\",\n});\nlayer([\n  chart(sample(counties, { n: 50 }), { coord: Coord.geo() })\n    .flow(\n      // gap: cut a polygon into n cells\n      subdivide({ by: \"draw\", region: \"geometry\" }),\n    )\n    .mark(region({ fill: temp })),\n  chart(counties, { coord: Coord.geo() }).mark(\n    polygon({\n      points: \"geometry\",\n      fill: \"none\",\n      stroke: \"#333\",\n      strokeWidth: 0.7,\n    }),\n  ),\n]);","uses_up":"subdivide by \"draw\" (missing operator), n = 50","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"position_subdivide is a spread by draw inside a polygon. The draw part fits; GoFish has no operator that cuts an arbitrary polygon into n cells (table and spread cut boxes only).","r":"toy_temp_dist |>\n  ggplot() +\n  geom_sf_sample(aes(geometry = county_geometry, fill = temp_dist),\n    linewidth = 0, times = 50) +\n  geom_sf(aes(geometry = county_geometry), fill = NA, linewidth = 0.7) +\n  scale_fill_distiller(palette = \"OrRd\")"},{"id":"ggdibbler-08","pkg":"ggdibbler","num":"08","title":"Random intercept reference line over points","source":"Rd geom_abline_sample","img":"catalog/img/ggdibbler-08-abline-intercept.png","more":[],"gofish":"const intercept = dist.normal({ mean: \"m\", sd: \"s\" });\nlayer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ x: \"wt\", y: \"mpg\" }),\n    )\n    .mark(circle({ r: 3, opacity: 0.3 })),\n  chart(sample([{ m: 20, s: 1 }], { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(abline({ intercept, slope: 0, opacity: 0.3 })), // gap: a line across the whole plot\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Two layers, each with its own draws, as in ggdibbler. GoFish has no reference-line mark (rule or abline).","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) + geom_point_sample(alpha = 0.3) +\n  geom_abline_sample(intercept = dist_normal(20, 1), alpha = 0.3)"},{"id":"ggdibbler-09","pkg":"ggdibbler","num":"09","title":"Random vertical reference line","source":"Rd geom_abline_sample","img":"catalog/img/ggdibbler-09-vline.png","more":[],"gofish":"const xintercept = dist.normal({ mean: \"m\", sd: \"s\" });\nlayer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ x: \"wt\", y: \"mpg\" }),\n    )\n    .mark(circle({ r: 3, opacity: 0.3 })),\n  chart(sample([{ m: 5, s: 0.1 }], { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(rule({ x: xintercept, opacity: 0.3 })), // gap: rule mark\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Same as the abline entry with a vertical rule. The missing piece is the rule mark the proposal already lists as new.","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) + geom_point_sample(alpha = 0.3) +\n  geom_vline_sample(xintercept = dist_normal(5, 0.1), alpha = 0.3)"},{"id":"ggdibbler-10","pkg":"ggdibbler","num":"10","title":"Random horizontal reference line","source":"Rd geom_abline_sample","img":"catalog/img/ggdibbler-10-hline.png","more":[],"gofish":"const yintercept = dist.normal({ mean: \"m\", sd: \"s\" });\nlayer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ x: \"wt\", y: \"mpg\" }),\n    )\n    .mark(circle({ r: 3, opacity: 0.3 })),\n  chart(sample([{ m: 20, s: 1 }], { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(rule({ y: yintercept, opacity: 0.3 })), // gap: rule mark\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Horizontal version of the vline entry.","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) + geom_point_sample(alpha = 0.3) +\n  geom_hline_sample(yintercept = dist_normal(20, 1), alpha = 0.3)"},{"id":"ggdibbler-11","pkg":"ggdibbler","num":"11","title":"Regression line with random slope and intercept","source":"Rd geom_abline_sample; paper Fig 10a","img":"catalog/img/ggdibbler-11-abline-coef.png","more":[],"gofish":"const intercept = dist.normal({ mean: \"a\", sd: \"aSe\" });\nconst slope = dist.normal({ mean: \"b\", sd: \"bSe\" });\nlayer([\n  chart(mtcars)\n    .flow(scatter({ x: \"wt\", y: \"mpg\" }))\n    .mark(circle({ r: 3 })),\n  chart(\n    sample([{ a: 37, aSe: 1.8, b: -5, bSe: 0.56 }], {\n      n: 30,\n    }),\n  )\n    .flow(group({ by: \"draw\" }))\n    .mark(abline({ intercept, slope, opacity: 0.3 })), // gap: abline mark\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 30","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Slope and intercept are drawn independently, as ggdibbler does; dist.mvnormal would give the joint. Missing piece: an abline mark. Merged: paper Fig 10a (line colour only).","r":"ggplot(mtcars, aes(wt, mpg)) + geom_point() +\n  geom_abline_sample(intercept = dist_normal(37, 1.8),\n    slope = dist_normal(-5, 0.56), times = 30, alpha = 0.3)"},{"id":"ggdibbler-12","pkg":"ggdibbler","num":"12","title":"Uncertain class counts (stack_dodge default)","source":"Rd geom_bar_sample","img":"catalog/img/ggdibbler-12-bar-count.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ h: field(\"class\").count() }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Counts of a random category, one thin bar per draw.","r":"ggplot(uncertain_mpg, aes(class)) + geom_bar_sample()"},{"id":"ggdibbler-13","pkg":"ggdibbler","num":"13","title":"Uncertain class counts, identity_identity","source":"Rd geom_bar_sample","img":"catalog/img/ggdibbler-13-bar-count-identity.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n  )\n  .mark(rect({ h: field(\"class\").count(), opacity: 0.1 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The same counts painted over each other at alpha 0.1. With blend: \"mean\" in place of the opacity, the limit at n = Infinity would be the fade by P(count > y) from the table in section 2.","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(position = \"identity_identity\", alpha = 0.1)"},{"id":"ggdibbler-14","pkg":"ggdibbler","num":"14","title":"Uncertain bar heights (geom_col_sample)","source":"Rd geom_bar_sample","img":"catalog/img/ggdibbler-14-col.png","more":[],"gofish":"const outcome = dist.normal({ mean: \"outcome\", sd: \"sd\" });\nchart(sample(trials, { n: 10 }))\n  .flow(\n    spread({ by: \"trt\", dir: \"x\" }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ h: outcome }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The plain uncertain bar chart: three normals, 10 draws dodged in each slot.","r":"uncertain_df <- data.frame(trt = c(\"a\", \"b\", \"c\"),\n  outcome = dist_normal(mean = c(2.3, 1.9, 3.2), sd = c(0.5, 0.8, 0.7)))\nggplot(uncertain_df, aes(x = trt, y = outcome)) + geom_col_sample()"},{"id":"ggdibbler-15","pkg":"ggdibbler","num":"15","title":"Horizontal stacked counts, stack_dodge(reverse)","source":"Rd geom_bar_sample","img":"catalog/img/ggdibbler-15-bar-horizontal-reverse.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"y\" }),\n    spread({ by: \"draw\", dir: \"y\", spacing: 0 }),\n    stack({ by: \"drv\", dir: \"x\", reverse: true }),\n  )\n  .mark(rect({ w: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_dodge on the y axis; reverse is today's stack option.","r":"ggplot(uncertain_mpg, aes(y = class)) +\n  geom_bar_sample(aes(fill = drv), alpha = 1,\n    position = position_stack_dodge(reverse = TRUE)) +\n  theme(legend.position = \"top\")"},{"id":"ggdibbler-16","pkg":"ggdibbler","num":"16","title":"2D bin counts, 100 draws dodged","source":"Rd geom_bin_2d_sample","img":"catalog/img/ggdibbler-16-bin2d.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 100 }))\n  .flow(\n    partition({\n      by: {\n        x: field(\"x\").bin(Bin.thresholds(30)),\n        y: field(\"y\").bin(Bin.thresholds(30)),\n      },\n    }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ fill: field(\"x\").count() }));","uses_up":"spread({ by: \"draw\" }), n = 100","fit":"fits","verdict":"ok","v1_fit":"fits","note":"identity_dodge for 2D bins: the bins are computed per draw and each cell holds 100 strips. Bin.thresholds(30) gives about 30 round bins, not exactly 30.","r":"ggplot(smaller_uncertain_diamonds, aes(x, y)) + geom_bin_2d_sample(times = 100)"},{"id":"ggdibbler-17","pkg":"ggdibbler","num":"17","title":"2D bin counts, draws overlaid","source":"Rd geom_bin_2d_sample","img":"catalog/img/ggdibbler-17-bin2d-identity.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: {\n        x: field(\"x\").bin(Bin.thresholds(30)),\n        y: field(\"y\").bin(Bin.thresholds(30)),\n      },\n    }),\n  )\n  .mark(rect({ fill: field(\"x\").count(), opacity: 0.1 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Draws of the 2D histogram painted over each other.","r":"ggplot(smaller_uncertain_diamonds, aes(x, y)) +\n  geom_bin_2d_sample(position = \"identity\", alpha = 0.1)"},{"id":"ggdibbler-18","pkg":"ggdibbler","num":"18","title":"2D bin counts, 10 bins","source":"Rd geom_bin_2d_sample","img":"catalog/img/ggdibbler-18-bin2d-10.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    partition({\n      by: {\n        x: field(\"x\").bin(Bin.thresholds(10)),\n        y: field(\"y\").bin(Bin.thresholds(10)),\n      },\n    }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ fill: field(\"x\").count() }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Ten bins per axis, draws dodged in each cell.","r":"ggplot(smaller_uncertain_diamonds, aes(x, y)) + geom_bin_2d_sample(bins = 10)"},{"id":"ggdibbler-19","pkg":"ggdibbler","num":"19","title":"Uncertain boxplots","source":"Rd geom_boxplot_sample","img":"catalog/img/ggdibbler-19-boxplot.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n  )\n  .mark(boxplot({ y: \"hwy\", opacity: 0.1 })); // gap: boxplot (quartiles of the draws, whiskers, outliers)","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"One boxplot per class per draw, painted over each other. GoFish has the median but no quartiles of the draws and no boxplot glyph.","r":"ggplot(uncertain_mpg, aes(class, hwy)) + geom_boxplot_sample(alpha = 0.1)"},{"id":"ggdibbler-20","pkg":"ggdibbler","num":"20","title":"Uncertain boxplots, varwidth","source":"Rd geom_boxplot_sample","img":"catalog/img/ggdibbler-20-boxplot-varwidth.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n  )\n  .mark(\n    boxplot({\n      y: \"hwy\",\n      w: field(\"hwy\").count(),\n      opacity: 0.1,\n    }),\n  ); // gap: boxplot","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"varwidth is the box width from the group count. Same gap as the boxplot entry.","r":"ggplot(uncertain_mpg, aes(class, hwy)) +\n  geom_boxplot_sample(alpha = 0.1, varwidth = TRUE)"},{"id":"ggdibbler-21","pkg":"ggdibbler","num":"21","title":"Boxplots by drv, dodge_identity","source":"Rd geom_boxplot_sample","img":"catalog/img/ggdibbler-21-boxplot-dodge-identity.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"drv\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n  )\n  .mark(\n    boxplot({ y: \"hwy\", stroke: \"drv\", opacity: 0.05 }),\n  ); // gap: boxplot","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"dodge_identity: groups dodged by drv, draws overlaid inside each. Same boxplot gap.","r":"ggplot(uncertain_mpg, aes(class, hwy)) +\n  geom_boxplot_sample(aes(colour = drv), alpha = 0.05, position = \"dodge_identity\")"},{"id":"ggdibbler-22","pkg":"ggdibbler","num":"22","title":"Contours of a filtered faithfuld","source":"Rd geom_contour_sample","img":"catalog/img/ggdibbler-22-contour.png","more":[],"gofish":"chart(\n  sample(\n    uncertainFaithfuld.filter(\n      (d) => d.waiting > 80 && d.eruptions > 3,\n    ),\n    { n: 10 },\n  ),\n)\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    contour({ x: \"waiting\", y: \"eruptions\", z: \"density\" }),\n  ); // gap: contour","uses_up":"group({ by: \"draw\" }), the plain overlay at full opacity, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Contours per draw drawn over each other. Missing: a contour stat.","r":"ggplot(uncertain_faithfuld |> filter(waiting > 80) |> filter(eruptions > 3),\n  aes(waiting, eruptions, z = density)) + geom_contour_sample()"},{"id":"ggdibbler-23","pkg":"ggdibbler","num":"23","title":"Filled contours","source":"Rd geom_contour_sample","img":"catalog/img/ggdibbler-23-contour-filled.png","more":[],"gofish":"chart(\n  sample(\n    uncertainFaithfuld.filter(\n      (d) => d.waiting > 80 && d.eruptions > 3,\n    ),\n    { n: 10 },\n  ),\n)\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    contour({\n      x: \"waiting\",\n      y: \"eruptions\",\n      z: \"density\",\n      filled: true,\n    }),\n  ); // gap: contour","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Filled bands per draw painted over each other, so the last draw mostly wins. Missing: a contour stat.","r":"ggplot(uncertain_faithfuld |> filter(waiting > 80) |> filter(eruptions > 3),\n  aes(waiting, eruptions, z = density)) + geom_contour_filled_sample()"},{"id":"ggdibbler-24","pkg":"ggdibbler","num":"24","title":"Overplotted uncertain points","source":"Rd geom_count_sample","img":"catalog/img/ggdibbler-24-point-cty-hwy.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(scatter({ x: \"cty\", y: \"hwy\" }))\n  .mark(circle({ r: 2 }));","uses_up":"no step reads the draw key: every drawn row is painted, which is the plain overlay, n = 10 (an error at n = Infinity, rule 3.1)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Opaque points painted over each other. Version 2 says what this is at finite n (the plain overlay) and makes it an error at n = Infinity, where an unused draw key has no limit.","r":"ggplot(uncertain_mpg, aes(cty, hwy)) + geom_point_sample()"},{"id":"ggdibbler-25","pkg":"ggdibbler","num":"25","title":"geom_count bubbles, draws overlaid","source":"Rd geom_count_sample; paper Fig 14a; paper Fig 10e","img":"catalog/img/ggdibbler-25-count.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    group({ by: \"cty\" }),\n    scatter({ by: \"hwy\", x: \"cty\", y: \"hwy\" }),\n  )\n  .mark(circle({ r: field(\"hwy\").count(), opacity: 0.15 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"geom_count per draw, painted over each other. The flow fits; ggplot sizes by area and GoFish's r is linear in the count (area circles, #972, is not merged). Merged: paper Fig 14a (same help-file example, theme); paper Fig 10e (colour/shape only; reconstructed match).","r":"ggplot(uncertain_mpg, aes(cty, hwy)) + geom_count_sample(alpha = 0.15)"},{"id":"ggdibbler-26","pkg":"ggdibbler","num":"26","title":"geom_count with scale_size_area","source":"Rd geom_count_sample","img":"catalog/img/ggdibbler-26-count-size-area.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    group({ by: \"cty\" }),\n    scatter({ by: \"hwy\", x: \"cty\", y: \"hwy\" }),\n  )\n  .mark(\n    circle({ area: field(\"hwy\").count(), opacity: 0.15 }),\n  ); // gap: area-proportional size (#972)","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"scale_size_area makes area proportional to count with 0 at 0. Same flow as the previous entry; the missing piece is area sizing.","r":"ggplot(uncertain_mpg, aes(cty, hwy)) + geom_count_sample(alpha = 0.15) +\n  scale_size_area()"},{"id":"ggdibbler-27","pkg":"ggdibbler","num":"27","title":"2D density contours over points","source":"Rd geom_density_2d_sample","img":"catalog/img/ggdibbler-27-density2d.png","more":[],"gofish":"layer([\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(scatter({ x: \"eruptions\", y: \"waiting\" }))\n    .mark(circle({ r: 0.5 })),\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(\n      density2d({\n        x: \"eruptions\",\n        y: \"waiting\",\n        opacity: 0.5,\n      }),\n    ), // gap: 2D KDE contours\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Points and density contours sample separately, as in the Rd code (no seed). Missing: a 2D kernel density stat.","r":"ggplot(uncertain_faithful, aes(x = eruptions, y = waiting)) +\n  geom_point_sample(size = 2/10) +\n  scale_x_continuous_distribution(limits = c(0.5, 6)) +\n  scale_y_continuous_distribution(limits = c(40, 110)) +\n  geom_density_2d_sample(linewidth = 2/10, alpha = 0.5)"},{"id":"ggdibbler-28","pkg":"ggdibbler","num":"28","title":"2D density bands","source":"Rd geom_density_2d_sample","img":"catalog/img/ggdibbler-28-density2d-filled.png","more":[],"gofish":"layer([\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(scatter({ x: \"eruptions\", y: \"waiting\" }))\n    .mark(circle({ r: 0.5 })),\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(\n      density2d({\n        x: \"eruptions\",\n        y: \"waiting\",\n        filled: true,\n        opacity: 0.1,\n      }),\n    ), // gap: 2D KDE\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Filled density bands per draw, painted over each other. Same gap.","r":"ggplot(uncertain_faithful, aes(x = eruptions, y = waiting)) +\n  geom_point_sample(size = 2/10) +\n  scale_x_continuous_distribution(limits = c(0.5, 6)) +\n  scale_y_continuous_distribution(limits = c(40, 110)) +\n  geom_density_2d_filled_sample(alpha = 0.1)"},{"id":"ggdibbler-29","pkg":"ggdibbler","num":"29","title":"Density of carat, one curve per draw","source":"Rd geom_density_sample","img":"catalog/img/ggdibbler-29-density.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(density({ x: \"carat\", opacity: 0.5 })); // gap: kernel density stat","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"One density curve per draw over all 1000 cells, painted over each other. Missing: a KDE stat (quantileRows reads a density grid but does not compute one).","r":"ggplot(smaller_uncertain_diamonds, aes(carat)) + geom_density_sample(alpha = 0.5)"},{"id":"ggdibbler-30","pkg":"ggdibbler","num":"30","title":"Densities of depth by cut","source":"Rd geom_density_sample","img":"catalog/img/ggdibbler-30-density-by-cut.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(group({ by: \"draw\" }), group({ by: \"cut\" }))\n  .mark(\n    density({\n      x: \"depth\",\n      fill: \"cut\",\n      stroke: \"cut\",\n      opacity: 0.1,\n    }),\n  ); // gap: KDE","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"cut is random, so a diamond can change group between draws. Same KDE gap.","r":"ggplot(smaller_uncertain_diamonds, aes(depth, fill = cut)) +\n  geom_density_sample(aes(colour = after_stat(fill)), alpha = 0.1) +\n  scale_x_continuous_distribution(limits = c(55, 70))"},{"id":"ggdibbler-31","pkg":"ggdibbler","num":"31","title":"Dot plot of mpg, draws overlaid","source":"Rd geom_dotplot_sample; paper Fig 14 (middle)","img":"catalog/img/ggdibbler-31-dotplot.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: field(\"mpg\").bin(Bin.dotdensity()),\n      dir: \"x\",\n    }), // gap: dot-density binning\n    stack({ dir: \"y\" }),\n  )\n  .mark(circle({ opacity: 0.2 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"geom_dotplot's default method places bins at data-driven centres (dot density); GoFish bins only on fixed grids. Each draw's dotplot is painted over the others at alpha 0.2. The stack is over the cars of one draw, which are parts of a whole, so rule 3.4 does not fire. Merged: paper Fig 14 middle panel (same help-file example).","r":"ggplot(uncertain_mtcars, aes(x = mpg)) + geom_dotplot_sample(alpha = 0.2)"},{"id":"ggdibbler-32","pkg":"ggdibbler","num":"32","title":"Dot plot, binwidth 1.5","source":"Rd geom_dotplot_sample","img":"catalog/img/ggdibbler-32-dotplot-binwidth.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: field(\"mpg\").bin(Bin.dotdensity(1.5)),\n      dir: \"x\",\n    }), // gap\n    stack({ dir: \"y\" }),\n  )\n  .mark(circle({ opacity: 0.2 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Same as the previous entry with binwidth 1.5.","r":"ggplot(uncertain_mtcars, aes(x = mpg)) +\n  geom_dotplot_sample(binwidth = 1.5, alpha = 0.2)"},{"id":"ggdibbler-33","pkg":"ggdibbler","num":"33","title":"Dot plot, fixed-width bins (histodot)","source":"Rd geom_dotplot_sample","img":"catalog/img/ggdibbler-33-dotplot-histodot.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: field(\"mpg\").bin(Bin.step(1.5)),\n      dir: \"x\",\n    }),\n    stack({ dir: \"y\" }),\n  )\n  .mark(circle({ opacity: 0.2 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Fixed bins: the dotplot row of the table in section 2, per draw, with the draws painted over each other. The stack is over the cars of one draw, which may stack.","r":"ggplot(uncertain_mtcars, aes(x = mpg)) +\n  geom_dotplot_sample(method = \"histodot\", binwidth = 1.5, alpha = 0.2)"},{"id":"ggdibbler-34","pkg":"ggdibbler","num":"34","title":"Hex bins of carat and price","source":"Rd geom_hex_sample","img":"catalog/img/ggdibbler-34-hex.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: struct({ x: \"carat\", y: \"price\" }).bin(\n        Bin.hex({ radius: { x: 0.05, y: 300 } }),\n      ),\n    }),\n  )\n  .mark(\n    region({ fill: field(\"carat\").count(), opacity: 0.15 }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Hex bins per draw, painted over each other. Bin.hex takes a radius, not ggplot's bin count.","r":"ggplot(smaller_uncertain_diamonds, aes(carat, price)) + geom_hex_sample(alpha = 0.15)"},{"id":"ggdibbler-35","pkg":"ggdibbler","num":"35","title":"Hex bins, 10 bins","source":"Rd geom_hex_sample","img":"catalog/img/ggdibbler-35-hex-10.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: struct({ x: \"carat\", y: \"price\" }).bin(\n        Bin.hex({ radius: { x: 0.15, y: 950 } }),\n      ),\n    }),\n  )\n  .mark(\n    region({ fill: field(\"carat\").count(), opacity: 0.15 }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Coarser hexes; same flow.","r":"ggplot(smaller_uncertain_diamonds, aes(carat, price)) +\n  geom_hex_sample(bins = 10, alpha = 0.15)"},{"id":"ggdibbler-36","pkg":"ggdibbler","num":"36","title":"Histogram of carat (stack_dodge default)","source":"Rd geom_histogram_sample","img":"catalog/img/ggdibbler-36-histogram.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    partition({\n      by: field(\"carat\").bin(Bin.thresholds(30)),\n      dir: \"x\",\n    }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ h: field(\"carat\").count() }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_dodge with one group: each bin's slot holds 10 thin bars, one per draw. The bins are fitted to all drawn values.","r":"ggplot(smaller_uncertain_diamonds, aes(carat)) + geom_histogram_sample()"},{"id":"ggdibbler-37","pkg":"ggdibbler","num":"37","title":"Histogram, identity_identity","source":"Rd geom_histogram_sample","img":"catalog/img/ggdibbler-37-histogram-identity.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: field(\"carat\").bin(Bin.thresholds(30)),\n      dir: \"x\",\n    }),\n  )\n  .mark(rect({ h: field(\"carat\").count(), opacity: 0.15 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Draws of the histogram painted over each other at alpha 0.15.","r":"ggplot(smaller_uncertain_diamonds, aes(carat)) +\n  geom_histogram_sample(position = \"identity_identity\", alpha = 0.15)"},{"id":"ggdibbler-38","pkg":"ggdibbler","num":"38","title":"Frequency polygons of price by cut","source":"Rd geom_histogram_sample","img":"catalog/img/ggdibbler-38-freqpoly.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    group({ by: \"cut\" }),\n    partition({\n      by: field(\"price\").bin(Bin.step(500)),\n      dir: \"x\",\n    }),\n  )\n  .mark(\n    line({\n      h: field(\"price\").count(),\n      stroke: \"cut\",\n      along: \"price\",\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"warning: 3.2, each frequency polygon joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"fits","note":"One frequency polygon per cut per draw, painted over each other. Each vertex is the count of one bin in one draw, and the line joins the bins of one draw. The cells are drawn one by one, so the line is one possible world only if the diamonds are independent, which is the warning of rule 3.2.","r":"ggplot(smaller_uncertain_diamonds, aes(price, colour = cut)) +\n  geom_freqpoly_sample(binwidth = 500)"},{"id":"ggdibbler-39","pkg":"ggdibbler","num":"39","title":"Histogram of price filled by cut","source":"Rd geom_histogram_sample","img":"catalog/img/ggdibbler-39-histogram-fill.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    partition({\n      by: field(\"price\").bin(Bin.step(500)),\n      dir: \"x\",\n    }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n    stack({ by: \"cut\", dir: \"y\" }),\n  )\n  .mark(rect({ h: field(\"price\").count(), fill: \"cut\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_dodge in each bin: draws side by side, each a stack of cuts.","r":"ggplot(smaller_uncertain_diamonds, aes(price, fill = cut)) +\n  geom_histogram_sample(binwidth = 500)"},{"id":"ggdibbler-40","pkg":"ggdibbler","num":"40","title":"Points of cyl and hwy","source":"Rd geom_jitter_sample","img":"catalog/img/ggdibbler-40-point-cyl-hwy.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(scatter({ x: \"cyl\", y: \"hwy\" }))\n  .mark(circle({ r: 2 }));","uses_up":"no step reads the draw key: every drawn row is painted, which is the plain overlay, n = 10 (an error at n = Infinity, rule 3.1)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Opaque overplotted draws, the plain overlay.","r":"ggplot(uncertain_mpg, aes(cyl, hwy)) + geom_point_sample(times = 10)"},{"id":"ggdibbler-41","pkg":"ggdibbler","num":"41","title":"Jittered uncertain points","source":"Rd geom_jitter_sample","img":"catalog/img/ggdibbler-41-jitter.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    // gap: jitter on both placed axes\n    scatter({\n      x: \"cyl\",\n      y: \"hwy\",\n      overlap: Overlap.jitter(),\n    }),\n  )\n  .mark(circle({ r: 2 }));","uses_up":"no step reads the draw key: every drawn row is painted, which is the plain overlay, n = 10 (an error at n = Infinity, rule 3.1)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Overlap.jitter moves only the axis no field places; geom_jitter shakes both x and y. Not a draw question.","r":"ggplot(uncertain_mpg, aes(cyl, hwy)) + geom_jitter_sample(times = 10)"},{"id":"ggdibbler-42","pkg":"ggdibbler","num":"42","title":"geom_jitter_sample on deterministic mpg","source":"Rd geom_jitter_sample","img":"catalog/img/ggdibbler-42-jitter-deterministic.png","more":[],"gofish":"chart(mpg)\n  .flow(\n    scatter({\n      x: \"cyl\",\n      y: \"hwy\",\n      overlap: Overlap.jitter(),\n    }),\n  ) // gap: 2D jitter\n  .mark(circle({ r: 2, fill: \"class\" }));","uses_up":"nothing: no Dist column","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"geom_jitter_sample on plain data is plain jitter. Same 2D jitter gap.","r":"ggplot(mpg, aes(cyl, hwy)) + geom_jitter_sample(aes(colour = class))"},{"id":"ggdibbler-43","pkg":"ggdibbler","num":"43","title":"Uncertain line ranges","source":"Rd geom_linerange_sample","img":"catalog/img/ggdibbler-43-linerange.png","more":[],"gofish":"const lower = dist.normal({ mean: \"lower\", sd: \"lowerSd\" });\nconst upper = dist.normal({ mean: \"upper\", sd: \"upperSd\" });\nchart(sample(trials, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"trt\", yMin: lower, yMax: upper }),\n  )\n  .mark(rect({ w: 4, fill: \"group\" }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Each range's ends are drawn and the ranges are painted over each other, as ggdibbler does at full alpha.","r":"df <- data.frame(trt = factor(c(1, 1, 2, 2)), resp = c(1, 5, 3, 4),\n  group = factor(c(1, 2, 1, 2)), upper = c(1.1, 5.3, 3.3, 4.2),\n  lower = c(0.8, 4.6, 2.4, 3.6))\nuncertain_df <- df |> group_by(trt, group) |>\n  mutate(resp = dist_normal(resp, runif(1, 0, 0.2)),\n    upper = dist_normal(upper, runif(1, 0, 0.2)),\n    lower = dist_normal(lower, runif(1, 0, 0.2)))\n\nggplot(uncertain_df, aes(trt, resp, colour = group)) +\n  geom_linerange_sample(aes(ymin = lower, ymax = upper), linewidth = 4)"},{"id":"ggdibbler-44","pkg":"ggdibbler","num":"44","title":"Uncertain point ranges","source":"Rd geom_linerange_sample","img":"catalog/img/ggdibbler-44-pointrange.png","more":[],"gofish":"const resp = dist.normal({ mean: \"resp\", sd: \"respSd\" });\nconst lower = dist.normal({ mean: \"lower\", sd: \"lowerSd\" });\nconst upper = dist.normal({ mean: \"upper\", sd: \"upperSd\" });\nchart(sample(trials, { n: 10 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    pointrange({\n      x: \"trt\",\n      y: resp,\n      yMin: lower,\n      yMax: upper,\n      fill: \"group\",\n    }),\n  ); // gap","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"One drawn row becomes a point at resp and a range from lower to upper, two marks at different data positions. GoFish has no glyph made of parts placed by different fields of one row.","r":"df <- data.frame(trt = factor(c(1, 1, 2, 2)), resp = c(1, 5, 3, 4),\n  group = factor(c(1, 2, 1, 2)), upper = c(1.1, 5.3, 3.3, 4.2),\n  lower = c(0.8, 4.6, 2.4, 3.6))\nuncertain_df <- df |> group_by(trt, group) |>\n  mutate(resp = dist_normal(resp, runif(1, 0, 0.2)),\n    upper = dist_normal(upper, runif(1, 0, 0.2)),\n    lower = dist_normal(lower, runif(1, 0, 0.2)))\n\nggplot(uncertain_df, aes(trt, resp, colour = group)) +\n  geom_pointrange_sample(aes(ymin = lower, ymax = upper))"},{"id":"ggdibbler-45","pkg":"ggdibbler","num":"45","title":"Uncertain crossbars","source":"Rd geom_linerange_sample","img":"catalog/img/ggdibbler-45-crossbar.png","more":[],"gofish":"chart(sample(trials, { n: 10 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    crossbar({\n      x: \"trt\",\n      y: resp,\n      yMin: lower,\n      yMax: upper,\n      w: 0.2,\n      stroke: \"group\",\n    }),\n  ); // gap","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Box from lower to upper with a bar at resp. Same composite-glyph gap as pointrange (resp, lower, upper as in that entry).","r":"df <- data.frame(trt = factor(c(1, 1, 2, 2)), resp = c(1, 5, 3, 4),\n  group = factor(c(1, 2, 1, 2)), upper = c(1.1, 5.3, 3.3, 4.2),\n  lower = c(0.8, 4.6, 2.4, 3.6))\nuncertain_df <- df |> group_by(trt, group) |>\n  mutate(resp = dist_normal(resp, runif(1, 0, 0.2)),\n    upper = dist_normal(upper, runif(1, 0, 0.2)),\n    lower = dist_normal(lower, runif(1, 0, 0.2)))\n\nggplot(uncertain_df, aes(trt, resp, colour = group)) +\n  geom_crossbar_sample(aes(ymin = lower, ymax = upper), width = 0.2)"},{"id":"ggdibbler-46","pkg":"ggdibbler","num":"46","title":"Uncertain error bars","source":"Rd geom_linerange_sample","img":"catalog/img/ggdibbler-46-errorbar.png","more":[],"gofish":"chart(sample(trials, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"trt\", yMin: lower, yMax: upper }),\n  )\n  .mark(errorbar({ w: 0.2, stroke: \"group\" })); // gap: error bar with caps","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The span fits; the capped error-bar glyph does not exist in GoFish.","r":"df <- data.frame(trt = factor(c(1, 1, 2, 2)), resp = c(1, 5, 3, 4),\n  group = factor(c(1, 2, 1, 2)), upper = c(1.1, 5.3, 3.3, 4.2),\n  lower = c(0.8, 4.6, 2.4, 3.6))\nuncertain_df <- df |> group_by(trt, group) |>\n  mutate(resp = dist_normal(resp, runif(1, 0, 0.2)),\n    upper = dist_normal(upper, runif(1, 0, 0.2)),\n    lower = dist_normal(lower, runif(1, 0, 0.2)))\n\nggplot(uncertain_df, aes(trt, resp, colour = group)) +\n  geom_errorbar_sample(aes(ymin = lower, ymax = upper), width = 0.2)"},{"id":"ggdibbler-47","pkg":"ggdibbler","num":"47","title":"Unemployment over time, one line per draw","source":"Rd geom_path_sample","img":"catalog/img/ggdibbler-47-line-economics.png","more":[],"gofish":"chart(sample(uncertainEconomics, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ by: \"date\", x: \"date\", y: \"unemploy\" }),\n  )\n  .mark(line({ opacity: 0.1 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"warning: 3.2, each line joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"fits","note":"One line per draw across months, at alpha 0.1. Each month is drawn on its own, so a line through draw 3 of every month is a path of the series only if the months are independent. Version 1 found no rule for this; rule 3.2 now warns.","r":"ggplot(uncertain_economics, aes(date, unemploy)) + geom_line_sample(alpha = 0.1)"},{"id":"ggdibbler-48","pkg":"ggdibbler","num":"48","title":"Step lines since 2013","source":"Rd geom_path_sample","img":"catalog/img/ggdibbler-48-step.png","more":[],"gofish":"chart(\n  sample(\n    uncertainEconomics.filter(\n      (d) => d.date > new Date(\"2013-01-01\"),\n    ),\n    { n: 10 },\n  ),\n)\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ by: \"date\", x: \"date\", y: \"unemploy\" }),\n  )\n  .mark(line({ curve: Curve.step(), opacity: 0.5 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"warning: 3.2, each step line joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"fits","note":"Step lines per draw, painted over each other at alpha 0.5. Rule 3.2 warns, as for the line entry.","r":"uncertain_recent <- uncertain_economics[uncertain_economics$date > as.Date(\"2013-01-01\"), ]\nggplot(uncertain_recent, aes(date, unemploy)) + geom_step_sample(alpha = 0.5)"},{"id":"ggdibbler-49","pkg":"ggdibbler","num":"49","title":"Connected scatter of unemploy and psavert, colored by date","source":"Rd geom_path_sample","img":"catalog/img/ggdibbler-49-path.png","more":[],"gofish":"chart(sample(uncertainEconomics, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ by: \"date\", x: \"unemploy\", y: \"psavert\" }),\n  )\n  .mark(line({ stroke: \"date\", opacity: 0.15 })); // gap: color that varies along one line","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"warning: 3.2, each path joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"gofish-gap","note":"A connected scatter per draw in date order. GoFish's line color must be constant within a line; ggplot colors each segment by date. Rule 3.2 warns, as for the line entry.","r":"ggplot(uncertain_economics, aes(unemploy, psavert)) +\n  geom_path_sample(aes(colour = as.numeric(date)), alpha = 0.15)"},{"id":"ggdibbler-50","pkg":"ggdibbler","num":"50","title":"Points and lines with a missing value, shared seed","source":"Rd geom_path_sample","img":"catalog/img/ggdibbler-50-line-na.png","more":[],"gofish":"const y = dist.normal({ mean: \"y\", sd: 0.3 });\nconst drawn = sample(series, { n: 10, seed: 33 });\nlayer([\n  chart(drawn)\n    .flow(scatter({ x: \"x\", y }))\n    .mark(circle({ r: 3 })),\n  chart(drawn)\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ by: \"x\", x: \"x\", y }),\n    )\n    .mark(line()), // gap: break the line at the missing value\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; both layers read one sample (seed = 33)","fit":"gofish-gap","verdict":"warning: 3.2, each line joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"gofish-gap","note":"seed = 33 makes the points and the lines read the same draws. In version 2 the two charts read one sample, so the spec says this directly. GoFish's line does not break at a missing y.","r":"df <- data.frame(x = 1:5, y = c(1, 2, NA, 4, 5))\nuncertain_df <- df |> mutate(y = dist_normal(y, 0.3))\nggplot(uncertain_df, aes(x, y)) +\n  geom_point_sample(seed = 33) + geom_line_sample(seed = 33)"},{"id":"ggdibbler-51","pkg":"ggdibbler","num":"51","title":"Scatter of wt and mpg, 50 draws","source":"Rd geom_point_sample","img":"catalog/img/ggdibbler-51-point-mtcars.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 50 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"wt\", y: \"mpg\" }),\n  )\n  .mark(circle({ r: 2, opacity: 0.5 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 50","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Fifty draws of each car painted over each other at alpha 0.5. With blend: \"mean\" the picture would converge, as n grows, to each car's joint density of (wt, mpg).","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) + geom_point_sample(times = 50, alpha = 0.5)"},{"id":"ggdibbler-52","pkg":"ggdibbler","num":"52","title":"Scatter colored by a random category","source":"Rd geom_point_sample","img":"catalog/img/ggdibbler-52-point-colour.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(scatter({ x: \"wt\", y: \"mpg\" }))\n  .mark(circle({ r: 2, fill: \"cyl\" }));","uses_up":"no step reads the draw key: every drawn row is painted, which is the plain overlay, n = 10 (an error at n = Infinity, rule 3.1)","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A random category on color. ggdibbler needs dist_transformed(cyl, factor) to make it discrete; GoFish would declare cyl's unit as ordered levels.","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) +\n  geom_point_sample(aes(colour = dist_transformed(cyl, factor, as.numeric))) +\n  labs(colour = \"factor(cyl)\")"},{"id":"ggdibbler-53","pkg":"ggdibbler","num":"53","title":"Scatter with a random shape","source":"Rd geom_point_sample","img":"catalog/img/ggdibbler-53-point-shape.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(scatter({ x: \"wt\", y: \"mpg\" }))\n  .mark(symbol({ shape: \"cyl\" })); // gap: shape channel","uses_up":"no step reads the draw key: every drawn row is painted, which is the plain overlay, n = 10 (an error at n = Infinity, rule 3.1)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"GoFish has no point mark with a shape channel.","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) +\n  geom_point_sample(aes(shape = dist_transformed(cyl, factor, as.numeric))) +\n  labs(shape = \"factor(cyl)\")"},{"id":"ggdibbler-54","pkg":"ggdibbler","num":"54","title":"Bubble chart with random size","source":"Rd geom_point_sample","img":"catalog/img/ggdibbler-54-bubble.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"wt\", y: \"mpg\" }),\n  )\n  .mark(circle({ r: \"qsec\", opacity: 0.15 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Random size on r, painted over each other; uncertainty in size reads as a soft edge. ggplot sizes by area; r is linear (#972).","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) + geom_point_sample(aes(size = qsec), alpha = 0.15)"},{"id":"ggdibbler-55","pkg":"ggdibbler","num":"55","title":"Polygons with random vertices and fill","source":"Rd geom_polygon_sample","img":"catalog/img/ggdibbler-55-polygon.png","more":[],"gofish":"chart(sample(uncertainDatapoly, { n: 10 }))\n  .flow(group({ by: \"draw\" }), group({ by: \"id\" }))\n  .mark(\n    polygon({\n      x: \"x\",\n      y: \"y\",\n      fill: \"value\",\n      opacity: 0.15,\n    }),\n  ); // gap: polygon whose vertices are rows","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"warning: 3.2, each polygon joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"gofish-gap","note":"Each vertex is its own row with independent uniforms, and each polygon joins its four vertices within one draw. GoFish's polygon takes a ring of pixel points from one row, not data-space vertices from a group of rows. Rule 3.2 warns because the vertices are drawn one by one.","r":"ids <- factor(c(\"1.1\", \"2.1\", \"1.2\", \"2.2\", \"1.3\", \"2.3\"))\npositions <- data.frame(id = rep(ids, each = 4),\n  x = c(2, 1, 1.1, 2.2, 1, 0, 0.3, 1.1, 2.2, 1.1, 1.2, 2.5, 1.1, 0.3,\n        0.5, 1.2, 2.5, 1.2, 1.3, 2.7, 1.2, 0.5, 0.6, 1.3),\n  y = c(-0.5, 0, 1, 0.5, 0, 0.5, 1.5, 1, 0.5, 1, 2.1, 1.7, 1, 1.5,\n        2.2, 2.1, 1.7, 2.1, 3.2, 2.8, 2.1, 2.2, 3.3, 3.2))\n\nvalues <- data.frame(id = ids, value = c(3, 3.1, 3.1, 3.2, 3.15, 3.5))\ndatapoly <- merge(values, positions, by = c(\"id\"))\nuncertain_datapoly <- datapoly |>\n  mutate(x = dist_uniform(x - 0.1, x + 0.1), y = dist_uniform(y - 0.1, y + 0.1),\n    value = dist_uniform(value - 0.5, value + 0.5))\nggplot(uncertain_datapoly, aes(x = x, y = y)) +\n  geom_polygon_sample(aes(fill = value, group = id), alpha = 0.15)"},{"id":"ggdibbler-56","pkg":"ggdibbler","num":"56","title":"QQ plot of uncertain t draws","source":"Rd geom_qq_sample","img":"catalog/img/ggdibbler-56-qq-t.png","more":[],"gofish":"chart(sample(tSample, { n: 10 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(qq({ sample: \"y\" })); // gap: QQ stat and QQ line","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A QQ plot of all 200 cells per draw. GoFish has no QQ stat (sorted values against theoretical quantiles) or fitted QQ line.","r":"uncertain_df <- data.frame(y = dist_normal(rt(200, df = 5), runif(200)))\nggplot(uncertain_df, aes(sample = y)) + stat_qq_sample() + stat_qq_line_sample()"},{"id":"ggdibbler-57","pkg":"ggdibbler","num":"57","title":"QQ plot of mpg","source":"Rd geom_qq_sample","img":"catalog/img/ggdibbler-57-qq-mtcars.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(qq({ sample: \"mpg\" })); // gap: QQ stat","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Same as the previous entry on mpg.","r":"ggplot(uncertain_mtcars, aes(sample = mpg)) + stat_qq_sample() + stat_qq_line_sample()"},{"id":"ggdibbler-58","pkg":"ggdibbler","num":"58","title":"Quantile regression lines","source":"Rd geom_quantile_sample","img":"catalog/img/ggdibbler-58-quantile-reg.png","more":[],"gofish":"layer([\n  chart(sample(uncertainMpg, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ x: \"displ\", y: \"hwy\" }),\n    )\n    .mark(circle({ r: 2, opacity: 0.3 })),\n  chart(sample(uncertainMpg, { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(\n      quantileRegression({\n        x: \"displ\",\n        y: \"hwy\",\n        quantiles: [0.25, 0.5, 0.75],\n        opacity: 0.3,\n      }),\n    ), // gap\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Quantile regression per draw. Missing: a regression stat. The quantiles here are of hwy given displ inside one draw, not of the draws.","r":"ggplot(uncertain_mpg, aes(displ, hwy)) + geom_point_sample(alpha = 0.3) +\n  geom_quantile_sample(alpha = 0.3)"},{"id":"ggdibbler-59","pkg":"ggdibbler","num":"59","title":"Median regression line","source":"Rd geom_quantile_sample","img":"catalog/img/ggdibbler-59-quantile-reg-median.png","more":[],"gofish":"layer([\n  chart(sample(uncertainMpg, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ x: \"displ\", y: \"hwy\" }),\n    )\n    .mark(circle({ r: 2, opacity: 0.3 })),\n  chart(sample(uncertainMpg, { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(\n      quantileRegression({\n        x: \"displ\",\n        y: \"hwy\",\n        quantiles: [0.5],\n        opacity: 0.3,\n      }),\n    ), // gap\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Median regression only; same gap.","r":"ggplot(uncertain_mpg, aes(displ, hwy)) + geom_point_sample(alpha = 0.3) +\n  geom_quantile_sample(quantiles = 0.5, alpha = 0.3)"},{"id":"ggdibbler-60","pkg":"ggdibbler","num":"60","title":"Area from 0 to Lake Huron level","source":"Rd geom_ribbon_sample","img":"catalog/img/ggdibbler-60-ribbon-area.png","more":[],"gofish":"// huron's column \"level\" is renamed \"lake\": sample adds its own column named level.\nconst lake = dist.normal({ mean: \"lake\", sd: \"sd\" });\nchart(sample(huron, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ by: \"year\", x: \"year\", yMin: 0, yMax: lake }),\n  )\n  .mark(rect({ w: 0 }))\n  .layer(ribbon({ opacity: 0.15 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"warning: 3.2, each area joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"fits","note":"An area per draw, painted over each other at alpha 0.15: the fan-chart idiom from the Signal stories (rect spans joined by a ribbon). The data's column level clashes with the level column that sample adds, so the spec renames it. Rule 3.2 warns, as for the line entry.","r":"huron <- data.frame(year = 1875:1972, level = as.vector(LakeHuron))\nuncertain_huron <- huron |> group_by(year) |>\n  mutate(level = dist_normal(level, runif(1, 0, 2)))\n\nggplot(uncertain_huron, aes(year)) +\n  geom_ribbon_sample(aes(ymin = 0, ymax = level), alpha = 0.15)"},{"id":"ggdibbler-61","pkg":"ggdibbler","num":"61","title":"Band of level +/- 1 with a line, shared seed","source":"Rd geom_ribbon_sample","img":"catalog/img/ggdibbler-61-ribbon-band-line.png","more":[],"gofish":"// huron's column \"level\" is renamed \"lake\": sample adds its own column named level.\nconst lake = dist.normal({ mean: \"lake\", sd: \"sd\" });\nconst drawn = sample(huron, { n: 10, seed: 4 });\nlayer([\n  chart(drawn)\n    .flow(\n      derive((rows) =>\n        rows.map((r) => ({\n          ...r,\n          lo: r.lake - 1,\n          hi: r.lake + 1,\n        })),\n      ),\n      group({ by: \"draw\" }),\n      scatter({\n        by: \"year\",\n        x: \"year\",\n        yMin: \"lo\",\n        yMax: \"hi\",\n      }),\n    )\n    .mark(rect({ w: 0 }))\n    .layer(ribbon({ fill: \"#b3b3b3\", opacity: 0.15 })),\n  chart(drawn)\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ by: \"year\", x: \"year\", y: lake }),\n    )\n    .mark(line({ opacity: 0.15 })),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; both layers read one sample (seed = 4)","fit":"fits","verdict":"warning: 3.2, each band and line joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"fits","note":"seed = 4 shares the draws between the band and the line, which is one sample read by two charts. derive reads drawn values, so lake - 1 is per draw. The column clash with level is as in the previous entry.","r":"huron <- data.frame(year = 1875:1972, level = as.vector(LakeHuron))\nuncertain_huron <- huron |> group_by(year) |>\n  mutate(level = dist_normal(level, runif(1, 0, 2)))\n\nggplot(uncertain_huron, aes(year)) +\n  geom_ribbon_sample(aes(ymin = level - 1, ymax = level + 1),\n    fill = \"grey70\", seed = 4, alpha = 0.15) +\n  geom_line_sample(aes(y = level), seed = 4, alpha = 0.15)"},{"id":"ggdibbler-62","pkg":"ggdibbler","num":"62","title":"Faceted areas with random x and y, points share the seed","source":"Rd geom_ribbon_sample","img":"catalog/img/ggdibbler-62-area-facet.png","more":[],"gofish":"const x = dist.normal({ mean: \"x\", sd: 0.8 });\nconst y = dist.normal({ mean: \"y\", sd: 0.8 });\nconst drawn = sample(pts, { n: 10, seed: 100 });\nlayer([\n  chart(drawn)\n    .flow(\n      spread({ by: \"g\", dir: \"y\" }),\n      group({ by: \"draw\" }),\n      scatter({ by: \"id\", x, yMin: 0, yMax: y }),\n    )\n    .mark(rect({ w: 0, fill: \"g\" }))\n    .layer(ribbon({ fill: \"g\", opacity: 0.15 })),\n  chart(drawn)\n    .flow(spread({ by: \"g\", dir: \"y\" }), scatter({ x, y }))\n    .mark(circle({ r: 3 })),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; both layers read one sample (seed = 100)","fit":"fits","verdict":"warning: 3.2, each area joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"does-not-fit","note":"seed = 100 makes the points sit on the drawn area's vertices. Version 1 could not say this, because sample lived inside one chart's flow. In version 2 sample is a data step, so the area and the points read one sample and place it in two ways. Rule 3.2 warns because each area joins three cells drawn one by one.","r":"df <- data.frame(g = c(\"a\", \"a\", \"a\", \"b\", \"b\", \"b\"), x = c(1, 3, 5, 2, 4, 6),\n  y = c(2, 5, 1, 3, 6, 7))\nuncertain_df <- df |> mutate(x = dist_normal(x, 0.8), y = dist_normal(y, 0.8))\nggplot(uncertain_df, aes(x, y, fill = g)) +\n  geom_area_sample(seed = 100, alpha = 0.15) + geom_point_sample(seed = 100) +\n  facet_grid(g ~ .)"},{"id":"ggdibbler-63","pkg":"ggdibbler","num":"63","title":"Rug in the margins, shared seed","source":"Rd geom_rug_sample","img":"catalog/img/ggdibbler-63-rug.png","more":[],"gofish":"const drawn = sample(uncertainMtcars, { n: 10, seed: 4 });\nlayer([\n  chart(drawn)\n    .flow(scatter({ x: \"wt\", y: \"mpg\" }))\n    .mark(circle({ r: 2 })),\n  chart(drawn)\n    .flow(group({ by: \"draw\" }), scatter({ x: \"wt\" }))\n    .mark(rect({ w: 1, h: 8, opacity: 0.5 })),\n  chart(drawn)\n    .flow(group({ by: \"draw\" }), scatter({ y: \"mpg\" }))\n    .mark(rect({ w: 8, h: 1, opacity: 0.5 })),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; all layers read one sample (seed = 4)","fit":"fits","verdict":"ok","v1_fit":"does-not-fit","note":"The rug ticks mark the same drawn points as the scatter (seed = 4). Version 1 could not say this; in version 2 the three charts read one sample. A scatter that places only x leaves y to the layer, as the rug needs.","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) + geom_point_sample(seed = 4) +\n  geom_rug_sample(seed = 4, alpha = 0.5)"},{"id":"ggdibbler-64","pkg":"ggdibbler","num":"64","title":"A random segment and curve over points","source":"Rd geom_segment_sample","img":"catalog/img/ggdibbler-64-segment-curve.png","more":[],"gofish":"const x1 = dist.normal({ mean: \"x1\", sd: 0.1 });\nconst y1 = dist.normal({ mean: \"y1\", sd: 0.1 });\nconst x2 = dist.normal({ mean: \"x2\", sd: 0.1 });\nconst y2 = dist.normal({ mean: \"y2\", sd: 0.1 });\nlayer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ x: \"wt\", y: \"mpg\" }),\n    )\n    .mark(circle({ r: 2, opacity: 0.5 })),\n  chart(sample(link, { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(\n      segment({\n        x: x1,\n        y: y1,\n        x2,\n        y2,\n        stroke: \"#00bfc4\",\n        opacity: 0.5,\n      }),\n    ), // gap: segment from one row\n  chart(sample(link, { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(\n      segment({\n        x: x1,\n        y: y1,\n        x2,\n        y2,\n        curve: Curve.arc(),\n        stroke: \"#f8766d\",\n        opacity: 0.5,\n      }),\n    ), // gap\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The seed here only repeats one random stream over different data sets, so independent samples are faithful. GoFish's line joins marks or refs; it has no segment from one row's (x, y, xend, yend). The segment reads four cells of one row at one draw. Rule 3.2 is about rows, so it does not fire (see the summary).","r":"uncertain_df <- data.frame(x1 = dist_normal(2.62, 0.1), x2 = dist_normal(3.57, 0.1),\n  y1 = dist_normal(21.0, 0.1), y2 = dist_normal(15.0, 0.1))\nggplot(uncertain_mtcars, aes(wt, mpg)) + geom_point_sample(seed = 77, alpha = 0.5) +\n  geom_curve_sample(aes(x = x1, y = y1, xend = x2, yend = y2, colour = \"curve\"),\n    data = uncertain_df, seed = 77, alpha = 0.5) +\n  geom_segment_sample(aes(x = x1, y = y1, xend = x2, yend = y2, colour = \"segment\"),\n    data = uncertain_df, seed = 77, alpha = 0.5)"},{"id":"ggdibbler-65","pkg":"ggdibbler","num":"65","title":"Three counties subdivided into 100 draws","source":"Rd geom_sf_sample","img":"catalog/img/ggdibbler-65-sf-subdivide.png","more":[],"gofish":"chart(sample(threeCounties, { n: 100 }), {\n  coord: Coord.geo(),\n})\n  .flow(subdivide({ by: \"draw\", region: \"geometry\" })) // gap\n  .mark(region({ fill: temp }));","uses_up":"subdivide by \"draw\" (missing operator), n = 100","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A pixel map in three counties. Missing: cutting a polygon into n cells.","r":"toy_temp_dist |>\n  filter(county_name %in% c(\"Pottawattamie County\", \"Mills County\", \"Cass County\")) |>\n  ggplot() +\n  geom_sf_sample(times = 100, linewidth = 0, aes(geometry = county_geometry, fill = temp_dist))"},{"id":"ggdibbler-66","pkg":"ggdibbler","num":"66","title":"Three counties subdivided, with borders","source":"Rd geom_sf_sample","img":"catalog/img/ggdibbler-66-sf-subdivide-border.png","more":[],"gofish":"layer([\n  chart(sample(threeCounties, { n: 100 }), {\n    coord: Coord.geo(),\n  })\n    .flow(subdivide({ by: \"draw\", region: \"geometry\" })) // gap\n    .mark(region({ fill: temp })),\n  chart(threeCounties, { coord: Coord.geo() }).mark(\n    polygon({\n      points: \"geometry\",\n      fill: \"none\",\n      stroke: \"black\",\n      strokeWidth: 1,\n    }),\n  ),\n]);","uses_up":"subdivide by \"draw\" (missing operator), n = 100","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Same with the plain borders on top.","r":"toy_temp_dist |>\n  filter(county_name %in% c(\"Pottawattamie County\", \"Mills County\", \"Cass County\")) |>\n  ggplot() +\n  geom_sf_sample(aes(geometry = county_geometry, fill = temp_dist), linewidth = 0, times = 100) +\n  geom_sf(aes(geometry = county_geometry), fill = NA, linewidth = 1)"},{"id":"ggdibbler-67","pkg":"ggdibbler","num":"67","title":"Loess smooth per draw, with points","source":"Rd geom_smooth_sample; paper Fig 7b","img":"catalog/img/ggdibbler-67-smooth.png","more":[],"gofish":"const drawn = sample(uncertainMpg, { n: 10, seed: 22 });\nlayer([\n  chart(drawn)\n    .flow(scatter({ x: \"displ\", y: \"hwy\" }))\n    .mark(circle({ r: 0.5, opacity: 0.5 })),\n  chart(drawn)\n    .flow(group({ by: \"draw\" }))\n    .mark(\n      smooth({\n        x: \"displ\",\n        y: \"hwy\",\n        method: \"loess\",\n        band: true,\n        opacity: 0.1,\n      }),\n    ), // gap: smoothing stat\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; both layers read one sample (seed = 22)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"seed = 22 shares draws between points and smooths, which is one sample read by two charts. One fit per draw is the fix that rule 3.3 asks for. Missing: a smoothing stat. Each fit uses many cells of one draw; rule 3.2 is about marks that join rows, so it does not fire (see the summary). Merged: paper Fig 7b (same chart; paper code not given, reconstructed match).","r":"ggplot(uncertain_mpg, aes(displ, hwy)) +\n  geom_point_sample(alpha = 0.5, size = 0.2, seed = 22) +\n  geom_smooth_sample(linewidth = 0.2, alpha = 0.1, seed = 22)"},{"id":"ggdibbler-68","pkg":"ggdibbler","num":"68","title":"Linear fits per class per draw","source":"Rd geom_smooth_sample","img":"catalog/img/ggdibbler-68-smooth-lm-class.png","more":[],"gofish":"const drawn = sample(uncertainMpg, { n: 10, seed: 22 });\nlayer([\n  chart(drawn)\n    .flow(scatter({ x: \"displ\", y: \"hwy\" }))\n    .mark(circle({ r: 0.5, fill: \"class\", opacity: 0.5 })),\n  chart(drawn)\n    .flow(group({ by: \"draw\" }), group({ by: \"class\" }))\n    .mark(\n      smooth({\n        x: \"displ\",\n        y: \"hwy\",\n        method: \"lm\",\n        stroke: \"class\",\n        opacity: 0.1,\n      }),\n    ), // gap: smoothing stat\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; both layers read one sample (seed = 22)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A linear fit per class per draw over one shared sample. Same smoother gap; class is random, so cars move between fits.","r":"ggplot(uncertain_mpg, aes(displ, hwy, colour = class)) +\n  geom_point_sample(alpha = 0.5, size = 0.2, seed = 22) +\n  geom_smooth_sample(linewidth = 0.2, alpha = 0.1, se = FALSE, method = lm, seed = 22)"},{"id":"ggdibbler-69","pkg":"ggdibbler","num":"69","title":"Vector field with random angle and speed","source":"Rd geom_spoke_sample","img":"catalog/img/ggdibbler-69-spoke.png","more":[],"gofish":"const angle = dist.normal({ mean: \"angle\", sd: \"angleSd\" });\nconst speed = dist.normal({ mean: \"speed\", sd: \"speedSd\" });\nlayer([\n  chart(sample(field, { n: 10 }))\n    .flow(scatter({ x: \"x\", y: \"y\" }))\n    .mark(circle({ r: 2 })),\n  chart(sample(field, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ x: \"x\", y: \"y\" }),\n    )\n    .mark(spoke({ angle, radius: speed, opacity: 0.3 })), // gap: segment by angle and length\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Arrows with random angle and length, painted over each other at alpha 0.5. Missing: a spoke or segment mark.","r":"set.seed(1)\ndf <- expand.grid(x = 1:10, y = 1:10)\ndf$angle <- runif(100, 0, 2 * pi)\ndf$speed <- runif(100, 0, sqrt(0.1 * df$x))\nuncertain_df <- df |> group_by(x, y) |>\n  mutate(angle = dist_normal(angle, runif(1, 0, 0.5)),\n    speed = dist_normal(speed, runif(1, 0, 0.1))) |> ungroup()\nggplot(uncertain_df, aes(x, y)) + geom_point_sample() +\n  geom_spoke_sample(aes(angle = angle, radius = speed), alpha = 0.3)"},{"id":"ggdibbler-70","pkg":"ggdibbler","num":"70","title":"Car names at random positions","source":"Rd geom_text_sample","img":"catalog/img/ggdibbler-70-text.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 3 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"wt\", y: \"mpg\" }),\n  )\n  .mark(text({ text: \"model\", opacity: 0.5 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 3","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Three placements of each car name, painted over each other at alpha 0.5.","r":"ggplot(uncertain_mtcars, aes(wt, mpg, label = rownames(uncertain_mtcars))) +\n  geom_text_sample(times = 3, alpha = 0.5)"},{"id":"ggdibbler-71","pkg":"ggdibbler","num":"71","title":"Car labels with background","source":"Rd geom_text_sample","img":"catalog/img/ggdibbler-71-label.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 3 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"wt\", y: \"mpg\" }),\n  )\n  .mark(labelBox({ text: \"model\", opacity: 0.5 })); // gap: text with a background box as one mark","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 3","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"geom_label is text in a box. GoFish's text mark has no box; the label background belongs to .label().","r":"ggplot(uncertain_mtcars, aes(wt, mpg, label = rownames(uncertain_mtcars))) +\n  geom_label_sample(times = 3, alpha = 0.5)"},{"id":"ggdibbler-72","pkg":"ggdibbler","num":"72","title":"Random text at a fixed position","source":"Rd geom_text_sample","img":"catalog/img/ggdibbler-72-text-random-label.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    scatter({\n      by: \"model\",\n      x: field(\"wt\").mean(),\n      y: field(\"mpg\").mean(),\n    }),\n    group({ by: \"draw\" }),\n  )\n  .mark(text({ text: \"cyl\", fontSize: 16, opacity: 0.3 }));","uses_up":"two steps: the mean of each car's draws places its label (rule 3.1 allows it at any n), then group({ by: \"draw\" }) paints the labels over each other, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The label is a random category at the car's mean position. The position is a summary of each car's own draws (their mean), which version 2 lists as a way to use up draws; at n = Infinity it is ggdibbler's exact mean.","r":"ggplot(uncertain_mtcars, aes(mean(wt), mean(mpg), lab = cyl)) +\n  geom_text_sample(aes(label = after_stat(lab)), size = 6, alpha = 0.3)"},{"id":"ggdibbler-73","pkg":"ggdibbler","num":"73","title":"6 x 6 raster of random fill","source":"Rd geom_raster_sample","img":"catalog/img/ggdibbler-73-raster-grid.png","more":[],"gofish":"chart(sample(grid, { n: 10 }))\n  .flow(\n    table({ by: { x: \"x\", y: \"y\" } }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ fill: \"z\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A 6 by 6 raster, each cell in 10 strips.","r":"df <- expand.grid(x = 0:5, y = 0:5)\nset.seed(1)\ndf$z <- runif(nrow(df))\nuncertain_df <- df |> group_by(x, y) |>\n  mutate(z = dist_normal(z, runif(1, 0, 0.1))) |> ungroup()\nggplot(uncertain_df, aes(x, y, fill = z)) + geom_raster_sample()"},{"id":"ggdibbler-74","pkg":"ggdibbler","num":"74","title":"Tiles of varying width with a random category, identity_dodge","source":"Rd geom_raster_sample","img":"catalog/img/ggdibbler-74-tile-categorical.png","more":[],"gofish":"chart(sample(tiles, { n: 10 }))\n  .flow(\n    scatter({ by: \"id\", x: \"x\", y: \"y\" }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ h: 40, fill: \"z\" }))\n  .layer(\n    chart(tiles)\n      .flow(scatter({ x: \"x\", y: \"y\" }))\n      .mark(\n        rect({\n          w: 40,\n          h: 40,\n          fill: \"none\",\n          stroke: \"#7f7f7f\",\n        }),\n      ),\n  );","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"identity_dodge with a random category on fill; the plain tile outlines are a second layer with no draws.","r":"tile_df <- data.frame(x = rep(c(2, 5, 7, 9, 12), 2), y = rep(c(1, 2), each = 5),\n  z = factor(rep(1:5, each = 2)), w = rep(diff(c(0, 4, 6, 8, 10, 14)), 2))\n\nuncertain_tile_df <- tile_df\nuncertain_tile_df$z <- dist_transformed((1 + dist_binomial(rep(1:5, each = 2), 0.5)),\n  factor, as.numeric)\nggplot(uncertain_tile_df, aes(x, y)) +\n  geom_tile_sample(aes(fill = z), position = \"identity_dodge\") +\n  geom_tile(fill = NA, colour = \"grey50\", linewidth = 1) +\n  labs(fill = \"z\")"},{"id":"ggdibbler-75","pkg":"ggdibbler","num":"75","title":"Rectangles with four random edges","source":"Rd geom_raster_sample","img":"catalog/img/ggdibbler-75-rect.png","more":[],"gofish":"chart(sample(rects, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({\n      xMin: \"xmin\",\n      xMax: \"xmax\",\n      yMin: \"ymin\",\n      yMax: \"ymax\",\n    }),\n  )\n  .mark(\n    rect({ fill: \"z\", stroke: \"#7f7f7f\", opacity: 0.2 }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Four random edges per rectangle, drawn and painted over each other. The range form of scatter takes the drawn values.","r":"tile_df <- data.frame(x = rep(c(2, 5, 7, 9, 12), 2), y = rep(c(1, 2), each = 5),\n  z = factor(rep(1:5, each = 2)), w = rep(diff(c(0, 4, 6, 8, 10, 14)), 2))\n\nrect_df <- tile_df |> mutate(xmin = x - w / 2, xmax = x + w / 2, ymin = y, ymax = y + 1)\nuncertain_rect <- rect_df |>\n  mutate(xmin = dist_normal(xmin, 0.5), xmax = dist_normal(xmax, 0.5),\n    ymin = dist_normal(ymin, 0.5), ymax = dist_normal(ymax, 0.5))\nggplot(data = uncertain_rect,\n  aes(xmin = xmin, xmax = xmax, ymin = ymin, ymax = ymax, f = z)) +\n  geom_rect_sample(aes(fill = as.factor(after_stat(f))), colour = \"grey50\", alpha = 0.2) +\n  labs(fill = \"z\")"},{"id":"ggdibbler-76","pkg":"ggdibbler","num":"76","title":"Violins of mpg by a random cyl","source":"Rd geom_violin_sample","img":"catalog/img/ggdibbler-76-violin.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    spread({ by: \"cyl\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n  )\n  .mark(violin({ y: \"mpg\", opacity: 0.1 })); // gap: KDE violin","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"dodge_identity: violins by a random cyl, draws overlaid. Missing: a KDE stat (Overlap.sina gives a violin outline for dots, not a violin area).","r":"ggplot(uncertain_mtcars, aes(dist_transformed(cyl, factor, as.numeric), mpg)) +\n  geom_violin_sample(alpha = 0.1)"},{"id":"ggdibbler-77","pkg":"ggdibbler","num":"77","title":"Violins, untrimmed","source":"Rd geom_violin_sample","img":"catalog/img/ggdibbler-77-violin-untrimmed.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    spread({ by: \"cyl\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n  )\n  .mark(violin({ y: \"mpg\", trim: false, opacity: 0.1 })); // gap: KDE violin","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Same, untrimmed.","r":"ggplot(uncertain_mtcars, aes(dist_transformed(cyl, factor, as.numeric), mpg)) +\n  geom_violin_sample(trim = FALSE, alpha = 0.1)"},{"id":"ggdibbler-78","pkg":"ggdibbler","num":"78","title":"Plain dodge of groups and draws","source":"Rd position_dodge_nested","img":"catalog/img/ggdibbler-78-dodge.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"drv\", dir: \"x\", spacing: 1 }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 1 }),\n  )\n  .mark(rect({ h: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Plain dodge treats group x draw as one flat key. GoFish nests two spreads with equal spacing, which draws the same bars.","r":"ggplot(uncertain_mpg, aes(class)) + geom_bar_sample(aes(fill = drv), position = \"dodge\")"},{"id":"ggdibbler-79","pkg":"ggdibbler","num":"79","title":"dodge_identity","source":"Rd position_dodge_nested","img":"catalog/img/ggdibbler-79-dodge-identity.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"drv\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n  )\n  .mark(\n    rect({\n      h: field(\"drv\").count(),\n      fill: \"drv\",\n      opacity: 0.2,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"dodge_identity: groups dodged, draws painted over each other inside each group's bar at alpha 0.2.","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), position = \"dodge_identity\", alpha = 0.2)"},{"id":"ggdibbler-80","pkg":"ggdibbler","num":"80","title":"dodge_dodge","source":"Rd position_dodge_nested","img":"catalog/img/ggdibbler-80-dodge-dodge.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"drv\", dir: \"x\" }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ h: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"dodge_dodge: groups dodged, then each group's bar cut into draws. Here the draw spread is INSIDE the group step, the opposite of stack_dodge.","r":"ggplot(uncertain_mpg, aes(class)) + geom_bar_sample(aes(fill = drv), position = \"dodge_dodge\")"},{"id":"ggdibbler-81","pkg":"ggdibbler","num":"81","title":"identity_dodge","source":"Rd position_dodge_nested","img":"catalog/img/ggdibbler-81-identity-dodge.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n    group({ by: \"drv\" }),\n  )\n  .mark(\n    rect({\n      h: field(\"drv\").count(),\n      fill: \"drv\",\n      opacity: 0.7,\n    }),\n  );","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"identity_dodge: each draw's slot holds the three drv bars on top of each other. opacity 0.7 is ggplot's alpha for the overlapping groups, not for draws.","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), position = \"identity_dodge\", alpha = 0.7)"},{"id":"ggdibbler-82","pkg":"ggdibbler","num":"82","title":"Counts by drv overlaid, position identity","source":"Rd position_identity_identity","img":"catalog/img/ggdibbler-82-identity-fill.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n    group({ by: \"drv\" }),\n  )\n  .mark(\n    rect({\n      h: field(\"drv\").count(),\n      fill: \"drv\",\n      opacity: 0.1,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Plain identity = identity_identity: groups and draws all painted over each other at ggplot's alpha 0.1.","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), position = \"identity\", alpha = 0.1)"},{"id":"ggdibbler-83","pkg":"ggdibbler","num":"83","title":"Counts by drv overlaid, identity_identity","source":"Rd position_identity_identity","img":"catalog/img/ggdibbler-83-identity-identity-fill.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    group({ by: \"draw\" }),\n    group({ by: \"drv\" }),\n  )\n  .mark(\n    rect({\n      h: field(\"drv\").count(),\n      fill: \"drv\",\n      opacity: 0.1,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The help page says this is the same as the previous entry; the GoFish spec is the same too.","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), position = \"identity_identity\", alpha = 0.1)"},{"id":"ggdibbler-84","pkg":"ggdibbler","num":"84","title":"position_nest(\"stack_dodge\")","source":"Rd position_nest","img":"catalog/img/ggdibbler-84-nest-stack-dodge.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n    stack({ by: \"drv\", dir: \"y\" }),\n  )\n  .mark(\n    rect({\n      h: field(\"drv\").count(),\n      fill: \"drv\",\n      opacity: 0.9,\n    }),\n  );","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"position_nest(\"stack_dodge\") is the general form of the named nested positions. In GoFish every nesting is just an order of flow steps, so position_nest has no counterpart beyond the flow itself.","r":"ggplot(uncertain_mpg, aes(class)) +\n  geom_bar_sample(aes(fill = drv), alpha = 0.9, position = position_nest(\"stack_dodge\"))"},{"id":"ggdibbler-85","pkg":"ggdibbler","num":"85","title":"Plain stack of groups and draws","source":"Rd position_stack_nested; paper Fig 8b (horizontal)","img":"catalog/img/ggdibbler-85-stack-uncertain.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"x\" }),\n    stack({ by: \"draw\", dir: \"y\" }),\n    stack({ by: \"drv\", dir: \"y\" }),\n  )\n  .mark(rect({ h: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"stack({ by: \"draw\" }), n = 10","fit":"fits","verdict":"error: 3.4, stack({ by: \"draw\" }) adds the counts of ten draws of one cell, which are alternatives, not parts of a sum","v1_fit":"fits","note":"Plain stack on uncertain data stacks the ten draws on the count axis (up to 600). The grammar rejects it, which matches the paper's Fig 8b argument. A count is summable over cars, so CanSum on the unit alone would accept this stack. The error needs the draw key to be a key that sums are never taken across (see the summary).","r":"ggplot(uncertain_mpg, aes(class)) + geom_bar_sample(aes(fill = drv), position = \"stack\")"},{"id":"ggdibbler-86","pkg":"ggdibbler","num":"86","title":"Polygons subdivided into 50 draws","source":"Rd position_subdivide","img":"catalog/img/ggdibbler-86-subdivide-polygon.png","more":[],"gofish":"chart(sample(uncertainDatapoly, { n: 50 }))\n  .flow(group({ by: \"id\" }), subdivide({ by: \"draw\" })) // gap\n  .mark(region({ fill: \"value\" }));","uses_up":"subdivide by \"draw\" (missing operator), n = 50","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Six polygons cut into 50 cells each. Two gaps: a polygon from vertex rows, and cutting a polygon into cells.","r":"ids <- factor(c(\"1.1\", \"2.1\", \"1.2\", \"2.2\", \"1.3\", \"2.3\"))\npositions <- data.frame(id = rep(ids, each = 4),\n  x = c(2, 1, 1.1, 2.2, 1, 0, 0.3, 1.1, 2.2, 1.1, 1.2, 2.5, 1.1, 0.3,\n        0.5, 1.2, 2.5, 1.2, 1.3, 2.7, 1.2, 0.5, 0.6, 1.3),\n  y = c(-0.5, 0, 1, 0.5, 0, 0.5, 1.5, 1, 0.5, 1, 2.1, 1.7, 1, 1.5,\n        2.2, 2.1, 1.7, 2.1, 3.2, 2.8, 2.1, 2.2, 3.3, 3.2))\n\nvalues <- data.frame(id = ids, value = c(1, 2, 3, 4, 5, 6))\ndatapoly <- merge(values, positions, by = c(\"id\"))\nuncertain_datapoly <- datapoly |> mutate(value = dist_uniform(value, value + 0.8))\nggplot(uncertain_datapoly, aes(x = x, y = y)) +\n  geom_polygon_sample(aes(fill = value, group = id), times = 50, position = \"subdivide\")"},{"id":"ggdibbler-87","pkg":"ggdibbler","num":"87","title":"Custom connection shapes between points","source":"Rd stat_connect_sample","img":"catalog/img/ggdibbler-87-connect.png","more":[],"gofish":"const drawn = sample(uncertainEconomics.slice(0, 10), {\n  n: 10,\n  seed: 64,\n});\nconst path = (curve, stroke) =>\n  chart(drawn)\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({ by: \"date\", x: \"date\", y: \"unemploy\" }),\n    )\n    .mark(line({ curve, stroke }));\nlayer([\n  path(Curve.custom(zigzag), \"#00bfc4\"), // gap: a connection shape from a matrix\n  path(Curve.custom(smooth), \"#f8766d\"),\n  chart(drawn)\n    .flow(scatter({ x: \"date\", y: \"unemploy\" }))\n    .mark(circle({ r: 3 })),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; all layers read one sample (seed = 64)","fit":"gofish-gap","verdict":"warning: 3.2, each connection joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"gofish-gap","note":"seed = 64 shares the draws among the points and both connections, which is one sample read by three charts. Missing: a user-given connection shape (stat_connect's matrix). Rule 3.2 warns, as for the line entry.","r":"x <- seq(0, 1, length.out = 20)[-1]\nsmooth <- cbind(x, scales::rescale(1 / (1 + exp(-(x * 10 - 5)))))\nzigzag <- cbind(c(0.4, 0.6, 1), c(0.75, 0.25, 1))\nggplot(head(uncertain_economics, 10), aes(date, unemploy)) +\n  stat_connect_sample(aes(colour = \"zigzag\"), connection = zigzag, seed = 64) +\n  stat_connect_sample(aes(colour = \"smooth\"), connection = smooth, seed = 64) +\n  geom_point_sample(seed = 64)"},{"id":"ggdibbler-88","pkg":"ggdibbler","num":"88","title":"ECDF step, one per draw","source":"Rd stat_ecdf_sample","img":"catalog/img/ggdibbler-88-ecdf.png","more":[],"gofish":"chart(sample(sample200, { n: 10 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    ecdf({ x: \"x\", curve: Curve.step(), opacity: 0.3 }),\n  ); // gap: cumulative count","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"One ECDF of all 200 cells per draw, painted over each other. GoFish can sort but has no cumulative count of the draws.","r":"set.seed(44)\ndf <- data.frame(x = c(rnorm(100, 0, 3), rnorm(100, 0, 10)), g = gl(2, 100))\nuncertain_df <- df |> group_by(x) |>\n  mutate(x = dist_normal(x, runif(1, 0, 5)),\n    g_pred = dist_bernoulli(0.9 - 0.8 * (2 - as.numeric(g))))\n\nggplot(uncertain_df, aes(x)) + stat_ecdf_sample(geom = \"step\", alpha = 0.3)"},{"id":"ggdibbler-89","pkg":"ggdibbler","num":"89","title":"ECDFs of two groups","source":"Rd stat_ecdf_sample","img":"catalog/img/ggdibbler-89-ecdf-groups.png","more":[],"gofish":"chart(sample(sample200, { n: 10 }))\n  .flow(group({ by: \"draw\" }), group({ by: \"g\" }))\n  .mark(ecdf({ x: \"x\", stroke: \"g\", opacity: 0.3 })); // gap: cumulative count","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Same per group.","r":"set.seed(44)\ndf <- data.frame(x = c(rnorm(100, 0, 3), rnorm(100, 0, 10)), g = gl(2, 100))\nuncertain_df <- df |> group_by(x) |>\n  mutate(x = dist_normal(x, runif(1, 0, 5)),\n    g_pred = dist_bernoulli(0.9 - 0.8 * (2 - as.numeric(g))))\n\nggplot(uncertain_df, aes(x, colour = g)) + stat_ecdf_sample(alpha = 0.3)"},{"id":"ggdibbler-90","pkg":"ggdibbler","num":"90","title":"Normal data ellipse per draw","source":"Rd stat_ellipse_sample","img":"catalog/img/ggdibbler-90-ellipse.png","more":[],"gofish":"layer([\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(scatter({ x: \"waiting\", y: \"eruptions\" }))\n    .mark(circle({ r: 1 })),\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(group({ by: \"draw\" }))\n    .mark(dataEllipse({ x: \"waiting\", y: \"eruptions\" })), // gap: ellipse stat\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A normal data ellipse per draw. Missing: an ellipse stat (enclose(Shape.oval()) is the smallest ellipse around nodes, not a covariance ellipse).","r":"ggplot(uncertain_faithful, aes(waiting, eruptions)) +\n  geom_point_sample() + stat_ellipse_sample()"},{"id":"ggdibbler-91","pkg":"ggdibbler","num":"91","title":"t ellipses by a random group","source":"Rd stat_ellipse_sample","img":"catalog/img/ggdibbler-91-ellipse-t-groups.png","more":[],"gofish":"layer([\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(\n      derive((rows) =>\n        rows.map((r) => ({ ...r, long: r.eruptions > 3 })),\n      ),\n      scatter({ x: \"waiting\", y: \"eruptions\" }),\n    )\n    .mark(circle({ r: 1, fill: \"long\" })),\n  chart(sample(uncertainFaithful, { n: 10 }))\n    .flow(\n      derive((rows) =>\n        rows.map((r) => ({ ...r, long: r.eruptions > 3 })),\n      ),\n      group({ by: \"draw\" }),\n      group({ by: \"long\" }),\n    )\n    .mark(\n      dataEllipse({\n        x: \"waiting\",\n        y: \"eruptions\",\n        type: \"t\",\n        stroke: \"long\",\n      }),\n    ), // gap\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The group is a function of a drawn value, so derive runs after sample. Same ellipse gap.","r":"ggplot(uncertain_faithful, aes(waiting, eruptions,\n    color = dist_transformed(eruptions, function(x) x > 3, identity))) +\n  geom_point_sample() + stat_ellipse_sample(type = \"t\") +\n  labs(colour = \"eruptions > 3\")"},{"id":"ggdibbler-92","pkg":"ggdibbler","num":"92","title":"Filled ellipses by a random group","source":"Rd stat_ellipse_sample","img":"catalog/img/ggdibbler-92-ellipse-polygon.png","more":[],"gofish":"chart(sample(uncertainFaithful, { n: 10 }))\n  .flow(\n    derive((rows) =>\n      rows.map((r) => ({ ...r, long: r.eruptions > 3 })),\n    ),\n    group({ by: \"draw\" }),\n    group({ by: \"long\" }),\n  )\n  .mark(\n    dataEllipse({\n      x: \"waiting\",\n      y: \"eruptions\",\n      fill: \"long\",\n      opacity: 0.1,\n    }),\n  ); // gap","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Filled ellipses painted over each other at alpha 0.1. Same gap.","r":"ggplot(uncertain_faithful, aes(waiting, eruptions,\n    fill = dist_transformed(eruptions, function(x) x > 3, identity))) +\n  stat_ellipse_sample(geom = \"polygon\", alpha = 0.1) +\n  labs(fill = \"eruptions > 3\")"},{"id":"ggdibbler-93","pkg":"ggdibbler","num":"93","title":"Points colored by draw ID","source":"Rd stat_identity_sample","img":"catalog/img/ggdibbler-93-identity-drawid.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(scatter({ x: \"wt\", y: \"mpg\" }))\n  .mark(circle({ r: 2, fill: \"draw\" }));","uses_up":"the color channel reads the draw key, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Color by draw ID. Fine at n = 10. Rule 3.1 now names a channel that reads draw as an error at n = Infinity, which version 1 missed.","r":"ggplot(uncertain_mtcars, aes(wt, mpg)) +\n  stat_identity_sample(aes(colour = after_stat(drawID)))"},{"id":"ggdibbler-94","pkg":"ggdibbler","num":"94","title":"Convex hull per group per draw","source":"Rd stat_manual_sample","img":"catalog/img/ggdibbler-94-manual-hull.png","more":[],"gofish":"layer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(scatter({ x: \"disp\", y: \"mpg\" }))\n    .mark(circle({ r: 2, fill: \"cyl\" })),\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      group({ by: \"cyl\" }),\n      derive(hull),\n    )\n    .mark(\n      polygon({\n        x: \"disp\",\n        y: \"mpg\",\n        fill: \"none\",\n        stroke: \"cyl\",\n      }),\n    ), // gap: polygon from rows\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"warning: 3.2, each hull polygon joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"gofish-gap","note":"stat_manual is a user function per group per draw, which is derive. The layers sample separately, as in the Rd code (no seed). Missing: a polygon whose vertices are rows in data space. The hull joins cars drawn one by one, so rule 3.2 warns.","r":"make_hull <- function(data) {\n  hull <- chull(x = data$x, y = data$y)\n  data.frame(x = data$x[hull], y = data$y[hull])\n}\nq <- ggplot(uncertain_mtcars,\n  aes(disp, mpg, colour = dist_transformed(cyl, factor, as.numeric))) +\n  labs(colour = \"factor(cyl)\") + geom_point_sample()\n\nq + stat_manual_sample(geom = \"polygon\", fun = make_hull, fill = NA)"},{"id":"ggdibbler-95","pkg":"ggdibbler","num":"95","title":"Segments to the group mean per draw","source":"Rd stat_manual_sample","img":"catalog/img/ggdibbler-95-manual-segment.png","more":[],"gofish":"layer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(scatter({ x: \"disp\", y: \"mpg\" }))\n    .mark(circle({ r: 2, fill: \"cyl\" })),\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      group({ by: \"cyl\" }),\n      derive(toGroupMean),\n    )\n    .mark(\n      segment({\n        x: \"disp\",\n        y: \"mpg\",\n        x2: \"xend\",\n        y2: \"yend\",\n        stroke: \"cyl\",\n      }),\n    ), // gap: segment\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"gofish-gap","verdict":"warning: 3.2, each segment joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"gofish-gap","note":"Each point joined to its group's mean, per draw. derive adds the mean; the missing piece is a segment mark from one row. Each segment joins one car to a mean over the other cars of the same draw, so rule 3.2 warns.","r":"make_hull <- function(data) {\n  hull <- chull(x = data$x, y = data$y)\n  data.frame(x = data$x[hull], y = data$y[hull])\n}\nq <- ggplot(uncertain_mtcars,\n  aes(disp, mpg, colour = dist_transformed(cyl, factor, as.numeric))) +\n  labs(colour = \"factor(cyl)\") + geom_point_sample()\n\nq + stat_manual_sample(geom = \"segment\", fun = transform,\n  args = list(xend = quote(mean(x)), yend = quote(mean(y))))"},{"id":"ggdibbler-96","pkg":"ggdibbler","num":"96","title":"Group centroids per draw","source":"Rd stat_manual_sample","img":"catalog/img/ggdibbler-96-manual-centroid.png","more":[],"gofish":"layer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(scatter({ x: \"disp\", y: \"mpg\" }))\n    .mark(circle({ r: 2, fill: \"cyl\" })),\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({\n        by: \"cyl\",\n        x: field(\"disp\").mean(),\n        y: field(\"mpg\").mean(),\n      }),\n    )\n    .mark(circle({ r: 10, fill: \"none\", stroke: \"cyl\" })),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Group centroids per draw: the mean of the points inside each draw, so no derive is needed.","r":"make_hull <- function(data) {\n  hull <- chull(x = data$x, y = data$y)\n  data.frame(x = data$x[hull], y = data$y[hull])\n}\nq <- ggplot(uncertain_mtcars,\n  aes(disp, mpg, colour = dist_transformed(cyl, factor, as.numeric))) +\n  labs(colour = \"factor(cyl)\") + geom_point_sample()\n\nq + stat_manual_sample(size = 10, shape = 21, fun = dplyr::summarise,\n  args = vars(x = mean(x), y = mean(y)))"},{"id":"ggdibbler-97","pkg":"ggdibbler","num":"97","title":"Mean price in 2D bins","source":"Rd stat_summary_2d_sample","img":"catalog/img/ggdibbler-97-summary-2d.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    partition({\n      by: {\n        x: field(\"carat\").bin(Bin.thresholds(30)),\n        y: field(\"depth\").bin(Bin.thresholds(30)),\n      },\n    }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ fill: field(\"price\").mean() }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Mean price per 2D bin per draw, with the draws as strips in each cell (identity_dodge default).","r":"ggplot(smaller_uncertain_diamonds, aes(carat, depth, z = price)) + stat_summary_2d_sample()"},{"id":"ggdibbler-98","pkg":"ggdibbler","num":"98","title":"Sum of squared price in hex bins","source":"Rd stat_summary_2d_sample","img":"catalog/img/ggdibbler-98-summary-hex.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    derive((rows) =>\n      rows.map((r) => ({ ...r, price2: r.price ** 2 })),\n    ),\n    group({ by: \"draw\" }),\n    partition({\n      by: struct({ x: \"carat\", y: \"depth\" }).bin(\n        Bin.hex({ radius: { x: 0.05, y: 0.4 } }),\n      ),\n    }),\n  )\n  .mark(\n    region({ fill: field(\"price2\").sum(), opacity: 0.3 }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The custom summary sum(z^2) is a derived column summed per hex.","r":"ggplot(smaller_uncertain_diamonds, aes(carat, depth, z = price)) +\n  stat_summary_hex_sample(fun = ~ sum(.x^2), alpha = 0.3)"},{"id":"ggdibbler-99","pkg":"ggdibbler","num":"99","title":"Median mpg per cyl","source":"Rd stat_summary_sample","img":"catalog/img/ggdibbler-99-summary-median.png","more":[],"gofish":"layer([\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(scatter({ x: \"cyl\", y: \"mpg\" }))\n    .mark(circle({ r: 2 })),\n  chart(sample(uncertainMtcars, { n: 10 }))\n    .flow(\n      group({ by: \"draw\" }),\n      scatter({\n        by: \"cyl\",\n        x: \"cyl\",\n        y: field(\"mpg\").median(),\n      }),\n    )\n    .mark(circle({ r: 3, fill: \"red\" })),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Only the points carry seed = 4, so the median layer's draws are separate in ggdibbler too, and here it is a second sample. cyl is random, so the groups change between draws.","r":"ggplot(uncertain_mtcars, aes(cyl, mpg)) + geom_point_sample(seed = 4) +\n  stat_summary_sample(fun = \"median\", colour = \"red\", geom = \"point\")"},{"id":"ggdibbler-100","pkg":"ggdibbler","num":"100","title":"Mean mpg per cyl as a line, by a random vs","source":"Rd stat_summary_sample","img":"catalog/img/ggdibbler-100-summary-mean-line.png","more":[],"gofish":"const drawn = sample(uncertainMtcars, { n: 10, seed: 4 });\nlayer([\n  chart(drawn)\n    .flow(scatter({ x: \"cyl\", y: \"mpg\" }))\n    .mark(circle({ r: 2, fill: \"vs\" })),\n  chart(drawn)\n    .flow(\n      group({ by: \"draw\" }),\n      group({ by: \"vs\" }),\n      scatter({\n        by: \"cyl\",\n        x: \"cyl\",\n        y: field(\"mpg\").mean(),\n      }),\n    )\n    .mark(line({ stroke: \"vs\" })),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10; both layers read one sample (seed = 4)","fit":"fits","verdict":"warning: 3.2, each mean line joins rows of different cells along a per-cell draw key, so it shows one possible world only if the cells are independent","v1_fit":"does-not-fit","note":"The mean lines are the means of the drawn points shown (seed = 4). The lines group the drawn rows by vs, which the points do not, so version 1 could not write it. In version 2 both charts read one sample. Each vertex is a mean over the cars of one draw, not a summary per cell, so rule 3.2 warns.","r":"ggplot(uncertain_mtcars, aes(cyl, mpg)) + geom_point_sample(seed = 4) +\n  aes(colour = dist_transformed(vs, factor, as.numeric)) +\n  stat_summary_sample(fun = mean, geom = \"line\", seed = 4) +\n  labs(colour = \"factor(vs)\")"},{"id":"ggdibbler-101","pkg":"ggdibbler","num":"101","title":"Binary vs and am, heavy overplotting","source":"Rd stat_unique_sample","img":"catalog/img/ggdibbler-101-unique-overplot.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"vs\", y: \"am\" }),\n  )\n  .mark(circle({ r: 2, opacity: 0.01 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Four possible points, painted over each other 320 times at alpha 0.01.","r":"ggplot(uncertain_mtcars, aes(vs, am)) + geom_point_sample(alpha = 0.01)"},{"id":"ggdibbler-102","pkg":"ggdibbler","num":"102","title":"Binary vs and am, unique per draw","source":"Rd stat_unique_sample","img":"catalog/img/ggdibbler-102-unique.png","more":[],"gofish":"chart(sample(uncertainMtcars, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    group({ by: \"vs\" }),\n    scatter({ by: \"am\", x: \"vs\", y: \"am\" }),\n  )\n  .mark(circle({ r: 2, opacity: 0.01 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stat_unique per draw is one mark per distinct (vs, am) per draw, which is what grouping by both does. With blend: \"mean\" the opacity of each point would be the probability that some car lands there; at alpha 0.01 over 10 draws it is close to a count.","r":"ggplot(uncertain_mtcars, aes(vs, am)) +\n  geom_point_sample(alpha = 0.01, stat = \"unique_sample\")"},{"id":"ggdibbler-103","pkg":"ggdibbler","num":"103","title":"Density of 15 uncertain heights","source":"paper Fig 1c (reconstructed)","img":"catalog/img/ggdibbler-103-paper-fig1c-density.png","more":[],"gofish":"const height = dist.normal({ mean: \"x\", sd: \"sigma\" });\nchart(sample(heights, { n: 100 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(density({ x: height, opacity: 0.3 })); // gap: KDE","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 100","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"The paper's motivating example: a density of 15 heights per draw. Missing: a KDE stat.","r":"# reconstructed: 15 heights with measurement error (paper Section 2)\nset.seed(15)\nheights <- data.frame(x = round(rnorm(15, 165, 7)), sigma = runif(15, 5, 20))\n\nheights |> mutate(height = dist_normal(x, sigma)) |>\n  ggplot(aes(height)) + geom_density_sample(times = 100, alpha = 0.3)"},{"id":"ggdibbler-104","pkg":"ggdibbler","num":"104","title":"Density plot as the measurement error shrinks","source":"paper Fig 3 top row (reconstructed)","img":"catalog/img/ggdibbler-104-paper-fig3-convergence.png","more":[],"gofish":"const height = dist.normal({ mean: \"x\", sd: \"sigma\" });\n// one panel per scale k of the sd: 1, 0.3, 0.05, 0\nchart(sample(heights, { n: 100 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(density({ x: height, opacity: 0.3 })); // gap: KDE","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 100","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"As the sd goes to 0 every draw is the same table, so the overlay is the plain density plot. This is the convergence the grammar keeps because draws are placed by ordinary steps.","r":"# reconstructed: 15 heights with measurement error (paper Section 2)\nset.seed(15)\nheights <- data.frame(x = round(rnorm(15, 165, 7)), sigma = runif(15, 5, 20))\n\npanel <- function(k) heights |> mutate(height = dist_normal(x, sigma * k)) |>\n  ggplot(aes(height)) + geom_density_sample(times = 100, alpha = 0.3) +\n  ggtitle(paste0(\"sd x \", k)) + theme_void() + theme(plot.title = element_text(size = 8))\npanel(1) | panel(0.3) | panel(0.05) | panel(0)"},{"id":"ggdibbler-105","pkg":"ggdibbler","num":"105","title":"Lines at quantiles of a random intercept","source":"paper Fig 6a (reconstructed; quantile contrast panel)","img":"catalog/img/ggdibbler-105-paper-fig6a-quantile-intercept.png","more":[],"gofish":"const intercept = dist.normal({ mean: 0, sd: 1 });\nchart(sample([{}], { n: 50, at: \"quantiles\" }))\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    abline({\n      intercept,\n      slope: 1,\n      stroke: \"level\",\n      opacity: 0.6,\n    }),\n  ); // gap: abline","uses_up":"group({ by: \"draw\" }) over 50 evenly spaced levels (at: \"quantiles\"), colored by level","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A contrast panel, not ggdibbler output. at: \"quantiles\" gives exactly the 50 evenly spaced quantiles, which version 1 could not pick. One cell, so nothing is joined across cells. Missing: abline.","r":"# reconstructed: paper Fig 6. Lines y = a + b x, coloured by the marginal\n# quantile of the intercept. ggdibbler draws (b) and (d); (a) and (c) are the\n# paper's quantile contrast, drawn here with ggplot2.\nset.seed(6)\nqcol <- scale_colour_viridis_c(option = \"magma\", guide = \"none\")\n\np <- ppoints(50)\nggplot(data.frame(a = qnorm(p), p = p)) +\n  geom_abline(aes(intercept = a, slope = 1, colour = p), alpha = 0.6) + qcol +\n  xlim(-2, 2) + ylim(-2, 2)"},{"id":"ggdibbler-106","pkg":"ggdibbler","num":"106","title":"Lines at draws of a random intercept","source":"paper Fig 6b (reconstructed)","img":"catalog/img/ggdibbler-106-paper-fig6b-sample-intercept.png","more":[],"gofish":"const intercept = dist.normal({ mean: 0, sd: 1 });\nchart(sample([{}], { n: 50 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    abline({\n      intercept,\n      slope: 1,\n      stroke: \"level\",\n      opacity: 0.6,\n    }),\n  ); // gap: abline","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 50, colored by level","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Lines at random draws, colored by each draw's level. The paper colors by rank / 51; level is the exact CDF of the draw, which is close. Version 1 needed a sort in a value channel, which is not legal; level is an ordinary column. Missing: abline.","r":"# reconstructed: paper Fig 6. Lines y = a + b x, coloured by the marginal\n# quantile of the intercept. ggdibbler draws (b) and (d); (a) and (c) are the\n# paper's quantile contrast, drawn here with ggplot2.\nset.seed(6)\nqcol <- scale_colour_viridis_c(option = \"magma\", guide = \"none\")\n\nd <- data.frame(a = rnorm(50))\nd$p <- rank(d$a) / 51\nggplot(d) + geom_abline(aes(intercept = a, slope = 1, colour = p), alpha = 0.6) + qcol +\n  xlim(-2, 2) + ylim(-2, 2)"},{"id":"ggdibbler-107","pkg":"ggdibbler","num":"107","title":"Lines at paired marginal quantiles of a joint intercept and slope","source":"paper Fig 6c (reconstructed; quantile contrast panel)","img":"catalog/img/ggdibbler-107-paper-fig6c-quantile-joint.png","more":[],"gofish":"// Two independent marginal cells. at: \"quantiles\" gives draw k the\n// level (k - 0.5) / 50 in every cell, so each line pairs the k-th\n// quantile of the intercept with the k-th quantile of the slope.\nconst a = dist.normal({ mean: 0, sd: 1 });\nconst b = dist.normal({ mean: 0, sd: 1 });\nchart(sample([{}], { n: 50, at: \"quantiles\" }))\n  .flow(group({ by: \"draw\" }))\n  .mark(\n    abline({\n      intercept: a,\n      slope: b,\n      stroke: \"level\",\n      opacity: 0.6,\n    }),\n  ); // gap: abline","uses_up":"group({ by: \"draw\" }) over 50 evenly spaced levels shared by both cells","fit":"gofish-gap","verdict":"ok","v1_fit":"does-not-fit","note":"The paper's anti-example: paired marginal quantiles make a fan through one point. Version 1 could not write it, which was the right result. Version 2 writes it with no warning: at: \"quantiles\" gives every cell of a row the same level at draw k, and one mark reads two cells of one row, which rule 3.2 (about rows of different cells) does not cover. With the paper's joint cell, dist.mvnormal, at: \"quantiles\" has no meaning, because a pair has no single level. This is a place where version 2 is worse than version 1. Missing: abline.","r":"# reconstructed: paper Fig 6. Lines y = a + b x, coloured by the marginal\n# quantile of the intercept. ggdibbler draws (b) and (d); (a) and (c) are the\n# paper's quantile contrast, drawn here with ggplot2.\nset.seed(6)\nqcol <- scale_colour_viridis_c(option = \"magma\", guide = \"none\")\n\np <- ppoints(50)\nggplot(data.frame(a = qnorm(p), b = qnorm(p), p = p)) +\n  geom_abline(aes(intercept = a, slope = b, colour = p), alpha = 0.6) + qcol +\n  xlim(-2, 2) + ylim(-2, 2)"},{"id":"ggdibbler-108","pkg":"ggdibbler","num":"108","title":"Lines at draws of a joint intercept and slope","source":"paper Fig 6d (reconstructed)","img":"catalog/img/ggdibbler-108-paper-fig6d-sample-joint.png","more":[],"gofish":"const p = dist.mvnormal({\n  mean: { a: 0, b: 0 },\n  sd: { a: 1, b: 1 },\n  cor: -0.8,\n});\nchart(sample([{}], { n: 50 }))\n  .flow(group({ by: \"draw\" }))\n  .mark(abline({ intercept: p.a, slope: p.b })); // gap: abline","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 50","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Joint draws of slope and intercept, one line per draw. The joint is exactly what dist.mvnormal adds over ggdibbler. Missing: abline (and color by rank, as in Fig 6b).","r":"# reconstructed: paper Fig 6. Lines y = a + b x, coloured by the marginal\n# quantile of the intercept. ggdibbler draws (b) and (d); (a) and (c) are the\n# paper's quantile contrast, drawn here with ggplot2.\nset.seed(6)\nqcol <- scale_colour_viridis_c(option = \"magma\", guide = \"none\")\n\nab <- generate(dist_multivariate_normal(list(c(0, 0)),\n  list(matrix(c(1, -0.8, -0.8, 1), 2))), 50)[[1]]\nd <- data.frame(a = ab[, 1], b = ab[, 2])\nd$p <- rank(d$a) / 51\nggplot(d) + geom_abline(aes(intercept = a, slope = b, colour = p), alpha = 0.6) + qcol +\n  xlim(-2, 2) + ylim(-2, 2)"},{"id":"ggdibbler-109","pkg":"ggdibbler","num":"109","title":"One smooth over all draws pooled (group without draw)","source":"paper Fig 7a (reconstructed)","img":"catalog/img/ggdibbler-109-paper-fig7a-smooth-pooled.png","more":[],"gofish":"const drawn = sample(uncertainMpg, { n: 10 });\nlayer([\n  chart(drawn)\n    .flow(scatter({ x: \"displ\", y: \"hwy\" }))\n    .mark(circle({ r: 0.5, opacity: 0.05 })),\n  // one smooth over every drawn row: no group by draw\n  chart(drawn).mark(\n    smooth({\n      x: \"displ\",\n      y: \"hwy\",\n      method: \"loess\",\n      band: true,\n    }),\n  ), // gap: smoothing stat\n]);","uses_up":"nothing: the smooth pools every drawn row, n = 10","fit":"gofish-gap","verdict":"warning: 3.3, one smoother is fitted to the draws of every car at once, so n draws count as n times as much data and the band shrinks as n grows","v1_fit":"gofish-gap","note":"The paper's wrong version. Version 1 had no rule for it; rule 3.3 now warns. The fix is entry 67: fit once per draw.","r":"draws <- sample_expand(uncertain_mpg, times = 10)\nggplot(draws, aes(displ, hwy)) + geom_point(alpha = 0.05, size = 0.2) + geom_smooth()"},{"id":"ggdibbler-110","pkg":"ggdibbler","num":"110","title":"Horizontal stack_stack","source":"paper Fig 8b (reconstructed)","img":"catalog/img/ggdibbler-110-paper-fig8b-stack-stack.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"y\" }),\n    stack({ by: \"draw\", dir: \"x\" }),\n    stack({ by: \"drv\", dir: \"x\" }),\n  )\n  .mark(rect({ w: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"stack({ by: \"draw\" }), n = 10","fit":"fits","verdict":"error: 3.4, stack({ by: \"draw\" }) adds counts of alternative draws","v1_fit":"fits","note":"The paper's own example of why draws must not stack. Same reasoning as entry 85.","r":"ggplot(uncertain_mpg, aes(y = class)) + geom_bar_sample(aes(fill = drv), position = \"stack\")"},{"id":"ggdibbler-111","pkg":"ggdibbler","num":"111","title":"Horizontal stack_dodge","source":"paper Fig 8c (reconstructed)","img":"catalog/img/ggdibbler-111-paper-fig8c-stack-dodge.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"y\" }),\n    spread({ by: \"draw\", dir: \"y\", spacing: 0 }),\n    stack({ by: \"drv\", dir: \"x\" }),\n  )\n  .mark(rect({ w: field(\"drv\").count(), fill: \"drv\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_dodge on the y axis.","r":"ggplot(uncertain_mpg, aes(y = class)) +\n  geom_bar_sample(aes(fill = drv), position = \"stack_dodge\")"},{"id":"ggdibbler-112","pkg":"ggdibbler","num":"112","title":"Horizontal stack_identity","source":"paper Fig 8d (reconstructed)","img":"catalog/img/ggdibbler-112-paper-fig8d-stack-identity.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }))\n  .flow(\n    spread({ by: \"class\", dir: \"y\" }),\n    group({ by: \"draw\" }),\n    stack({ by: \"drv\", dir: \"x\" }),\n  )\n  .mark(\n    rect({\n      w: field(\"drv\").count(),\n      fill: \"drv\",\n      opacity: 0.15,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_identity on the y axis.","r":"ggplot(uncertain_mpg, aes(y = class)) +\n  geom_bar_sample(aes(fill = drv), position = \"stack_identity\", alpha = 0.15)"},{"id":"ggdibbler-113","pkg":"ggdibbler","num":"113","title":"Random category as text, overlaid","source":"paper Fig 9a (reconstructed)","img":"catalog/img/ggdibbler-113-paper-fig9a-text-transparency.png","more":[],"gofish":"chart(sample(grid, { n: 10 }))\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" } }),\n    group({ by: \"draw\" }),\n  )\n  .mark(\n    text({\n      text: \"mode\",\n      textAnchor: \"middle\",\n      opacity: 0.2,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A random category as text, painted in place at alpha 0.15 per draw: the more certain the word, the more legible.","r":"# reconstructed: a 5 x 5 grid of cells, each with a random category and a\n# random value (paper Fig 9)\nset.seed(9)\ngrid <- expand.grid(col = 1:5, row = 1:5)\ngrid$mode <- dist_categorical(lapply(seq_len(25), function(i) {\n  p <- runif(3)^3; p / sum(p) }), list(c(\"Bus\", \"Cycle\", \"Drive\")))\ngrid$value <- dist_normal(runif(25, 0, 10), runif(25, 0.2, 3))\n\nggplot(grid, aes(col, row, lab = mode)) +\n  geom_text_sample(aes(label = after_stat(lab)), alpha = 0.2, position = \"identity\", size = 2.5) + theme_void()"},{"id":"ggdibbler-114","pkg":"ggdibbler","num":"114","title":"Random category as text, jittered","source":"paper Fig 9b (reconstructed)","img":"catalog/img/ggdibbler-114-paper-fig9b-text-jitter.png","more":[],"gofish":"chart(sample(grid, { n: 10 }))\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" } }), // gap: jitter on both axes\n    scatter({ overlap: Overlap.jitter() }),\n  )\n  .mark(text({ text: \"mode\" }));","uses_up":"no step reads the draw key: every drawn row is painted, which is the plain overlay, n = 10 (an error at n = Infinity, rule 3.1)","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"Draws jittered around the cell. The draw part fits; 2D jitter is missing.","r":"# reconstructed: a 5 x 5 grid of cells, each with a random category and a\n# random value (paper Fig 9)\nset.seed(9)\ngrid <- expand.grid(col = 1:5, row = 1:5)\ngrid$mode <- dist_categorical(lapply(seq_len(25), function(i) {\n  p <- runif(3)^3; p / sum(p) }), list(c(\"Bus\", \"Cycle\", \"Drive\")))\ngrid$value <- dist_normal(runif(25, 0, 10), runif(25, 0.2, 3))\n\nggplot(grid, aes(col, row, lab = mode)) +\n  geom_text_sample(aes(label = after_stat(lab)), position = position_jitter(0.3, 0.3), size = 2.5) + theme_void()"},{"id":"ggdibbler-115","pkg":"ggdibbler","num":"115","title":"Random value as tile color, dodged","source":"paper Fig 9c (reconstructed)","img":"catalog/img/ggdibbler-115-paper-fig9c-colour-dodge.png","more":[],"gofish":"chart(sample(grid, { n: 10 }))\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" }, spacing: 4 }),\n    spread({ by: \"draw\", dir: \"x\", spacing: 0 }),\n  )\n  .mark(rect({ fill: \"value\" }));","uses_up":"spread({ by: \"draw\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Tile color with the draws as strips.","r":"# reconstructed: a 5 x 5 grid of cells, each with a random category and a\n# random value (paper Fig 9)\nset.seed(9)\ngrid <- expand.grid(col = 1:5, row = 1:5)\ngrid$mode <- dist_categorical(lapply(seq_len(25), function(i) {\n  p <- runif(3)^3; p / sum(p) }), list(c(\"Bus\", \"Cycle\", \"Drive\")))\ngrid$value <- dist_normal(runif(25, 0, 10), runif(25, 0.2, 3))\n\nggplot(grid, aes(col, row, fill = value)) +\n  geom_tile_sample(position = \"identity_dodge\") + theme_void()"},{"id":"ggdibbler-116","pkg":"ggdibbler","num":"116","title":"Random value as tile color, overlaid","source":"paper Fig 9d (reconstructed)","img":"catalog/img/ggdibbler-116-paper-fig9d-colour-transparency.png","more":[],"gofish":"chart(sample(grid, { n: 10 }))\n  .flow(\n    table({ by: { x: \"col\", y: \"row\" }, spacing: 4 }),\n    group({ by: \"draw\" }),\n  )\n  .mark(rect({ fill: \"value\", opacity: 0.15 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Colors painted over each other, which the paper notes can leave the palette. blend: \"mean\" would average colors and has the same issue; its limit is the expected color.","r":"# reconstructed: a 5 x 5 grid of cells, each with a random category and a\n# random value (paper Fig 9)\nset.seed(9)\ngrid <- expand.grid(col = 1:5, row = 1:5)\ngrid$mode <- dist_categorical(lapply(seq_len(25), function(i) {\n  p <- runif(3)^3; p / sum(p) }), list(c(\"Bus\", \"Cycle\", \"Drive\")))\ngrid$value <- dist_normal(runif(25, 0, 10), runif(25, 0.2, 3))\n\nggplot(grid, aes(col, row, fill = value)) +\n  geom_tile_sample(position = \"identity\", alpha = 0.15) + theme_void()"},{"id":"ggdibbler-117","pkg":"ggdibbler","num":"117","title":"Pie chart of a random class, blended","source":"paper Fig 10b (reconstructed)","img":"catalog/img/ggdibbler-117-paper-fig10b-pie.png","more":[],"gofish":"chart(sample(uncertainMpg, { n: 10 }), {\n  coord: Coord.clock(),\n})\n  .flow(\n    group({ by: \"draw\" }),\n    stack({ by: \"class\", dir: \"theta\" }),\n  )\n  .mark(\n    rect({\n      w: field(\"class\").count(),\n      fill: \"class\",\n      opacity: 0.15,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"A pie per draw, painted over each other, so the boundaries blur.","r":"ggplot(uncertain_mpg, aes(x = \"\", fill = class)) +\n  geom_bar_sample(width = 1, position = \"stack_identity\", alpha = 0.15) +\n  coord_polar(theta = \"y\") + theme_void()"},{"id":"ggdibbler-118","pkg":"ggdibbler","num":"118","title":"Histogram of carat filled by cut, overlaid","source":"paper Fig 10c (reconstructed)","img":"catalog/img/ggdibbler-118-paper-fig10c-histogram.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }))\n  .flow(\n    group({ by: \"draw\" }),\n    partition({\n      by: field(\"carat\").bin(Bin.thresholds(30)),\n      dir: \"x\",\n    }),\n    stack({ by: \"cut\", dir: \"y\" }),\n  )\n  .mark(\n    rect({\n      h: field(\"carat\").count(),\n      fill: \"cut\",\n      opacity: 0.15,\n    }),\n  );","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Stacked histogram per draw, painted over each other.","r":"ggplot(smaller_uncertain_diamonds, aes(carat, fill = cut)) +\n  geom_histogram_sample(position = \"stack_identity\", alpha = 0.15)"},{"id":"ggdibbler-119","pkg":"ggdibbler","num":"119","title":"Choropleth with subdivided regions","source":"paper Fig 10d (reconstructed; Iowa counties stand in for Australia)","img":"catalog/img/ggdibbler-119-paper-fig10d-map.png","more":[],"gofish":"chart(sample(counties, { n: 25 }), { coord: Coord.geo() })\n  .flow(subdivide({ by: \"draw\", region: \"geometry\" })) // gap\n  .mark(region({ fill: temp }));","uses_up":"subdivide by \"draw\" (missing operator), n = 25","fit":"gofish-gap","verdict":"ok","v1_fit":"gofish-gap","note":"A pixel map. Same polygon subdivision gap.","r":"ggplot(toy_temp_dist) +\n  geom_sf_sample(aes(geometry = county_geometry, fill = temp_dist), linewidth = 0, times = 25) +\n  scale_fill_viridis_c(option = \"magma\") + theme_void()"},{"id":"ggdibbler-120","pkg":"ggdibbler","num":"120","title":"Network with uncertain edges","source":"paper Fig 10f (reconstructed)","img":"catalog/img/ggdibbler-120-paper-fig10f-network.png","more":[],"gofish":"const present = dist.bernoulli({ p: \"p\" });\nlayer([\n  chart(nodes)\n    .flow(scatter({ by: \"id\", x: \"x\", y: \"y\" }))\n    .mark(circle({ r: 3 }).name(\"nodes\")),\n  chart(sample(edges, { n: 30 }))\n    .flow(\n      filter(present.between(1, 1)),\n      group({ by: \"draw\" }),\n      resolve([\"from\", \"to\"], { from: selectAll(\"nodes\") }),\n    )\n    .mark(\n      line({\n        from: \"from\",\n        to: \"to\",\n        stroke: \"firebrick\",\n        strokeWidth: 2,\n        opacity: 0.08,\n      }),\n    ),\n]);","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 30","fit":"fits","verdict":"ok","v1_fit":"fits","note":"Each edge is present in a draw with probability p. filter keeps the present edges, and each present edge is painted at alpha 0.08, as ggdibbler's alpha scale does. filter reads the Dist expression on a drawn row, which is the same rule as a channel reading it; today's filter takes a field. Each edge is one cell, and its line joins fixed nodes, so rule 3.2 does not fire.","r":"nodes <- data.frame(id = 1:5, x = c(0, 1.2, 1, 2, 0.7), y = c(0, 1, -1, 0.2, 0.3))\nedges <- data.frame(from = c(1, 1, 2, 2, 3, 3, 5, 5), to = c(2, 5, 4, 5, 4, 5, 4, 1),\n  p = c(0.2, 0.9, 0.6, 0.8, 0.3, 0.95, 0.7, 0.4))\nedges <- edges |> mutate(x = nodes$x[from], y = nodes$y[from],\n  xend = nodes$x[to], yend = nodes$y[to], present = dist_bernoulli(p))\nggplot() +\n  geom_segment_sample(data = edges, aes(x, y, xend = xend, yend = yend,\n    alpha = present), colour = \"firebrick\", linewidth = 1, times = 30) +\n  scale_alpha_continuous(range = c(0, 0.08), guide = \"none\") +\n  geom_point(data = nodes, aes(x, y)) + theme_void()"},{"id":"ggdibbler-121","pkg":"ggdibbler","num":"121","title":"Pie chart of clarity (stack_dodge default)","source":"paper Fig 11b","img":"catalog/img/ggdibbler-121-paper-fig11b-pie.png","more":[],"gofish":"chart(sample(smallerUncertainDiamonds, { n: 10 }), {\n  coord: Coord.clock(),\n})\n  .flow(\n    spread({ by: \"draw\", dir: \"r\", spacing: 0 }),\n    stack({ by: \"clarity\", dir: \"theta\" }),\n  )\n  .mark(\n    rect({ w: field(\"clarity\").count(), fill: \"clarity\" }),\n  );","uses_up":"spread({ by: \"draw\", dir: \"r\" }), n = 10","fit":"fits","verdict":"ok","v1_fit":"fits","note":"stack_dodge in polar: the draws are rings, each a full pie, which gives the jagged edge.","r":"ggplot(smaller_uncertain_diamonds, aes(x = \"\", fill = clarity)) +\n  geom_bar_sample(width = 1) +\n  coord_polar(theta = \"y\")"},{"id":"ggdibbler-122","pkg":"ggdibbler","num":"122","title":"Scatter of mpg and wt as times grows","source":"paper Fig 13 (reconstructed)","img":"catalog/img/ggdibbler-122-paper-fig13-times.png","more":[],"gofish":"// one panel per n: 10, 100, 1000 (n: Infinity is the limit)\nchart(sample(uncertainMtcars, { n: 100 }))\n  .flow(\n    group({ by: \"draw\" }),\n    scatter({ x: \"mpg\", y: \"wt\" }),\n  )\n  .mark(circle({ r: 2, fill: \"cyl\", opacity: 0.3 }));","uses_up":"group({ by: \"draw\" }), the plain overlay, n = 100","fit":"fits","verdict":"ok","v1_fit":"fits","note":"The paper's panels at times = 10, 100 and 1000. As an overlay at fixed alpha the cloud saturates as n grows; with blend: \"mean\" it would converge to each car's density as n goes to Infinity, which is the limit the paper describes.","r":"panel <- function(n) ggplot(uncertain_mtcars,\n    aes(mpg, wt, colour = dist_transformed(cyl, factor, as.numeric))) +\n  geom_point_sample(times = n, alpha = 0.3, size = 0.6) +\n  ggtitle(paste(\"times =\", n)) + theme(legend.position = \"none\",\n    plot.title = element_text(size = 8))\npanel(10) | panel(100) | panel(1000)"}];
var CSS = "\n#p-catalog p, #p-catalog li { max-width: 72ch; }\n#p-catalog .tw { overflow-x: auto; }\n#p-catalog table.cov { width: auto; min-width: 360px; border-collapse: collapse; font-size: 0.88rem; margin: 8px 0 14px; }\n#p-catalog table.cov th, #p-catalog table.cov td { padding: 4px 10px; border-bottom: 1px solid var(--rule); text-align: right; }\n#p-catalog table.cov th:first-child, #p-catalog table.cov td:first-child,\n#p-catalog table.cov th:nth-child(2), #p-catalog table.cov td:nth-child(2) { text-align: left; }\n#p-catalog .ct-filters { display: flex; flex-wrap: wrap; gap: 6px 18px; margin: 12px 0; align-items: center; }\n#p-catalog .ct-group { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; }\n#p-catalog .ct-group span.lab { font-size: 0.82rem; color: var(--muted); margin-right: 2px; }\n#p-catalog .ct-filters button { font: inherit; font-size: 0.8rem; padding: 3px 9px; border-radius: 4px; border: 1px solid var(--rule); background: var(--surface); color: var(--ink); cursor: pointer; }\n#p-catalog .ct-filters button[aria-pressed=\"true\"] { background: var(--accent-soft); color: var(--accent); border-color: var(--accent); }\n#p-catalog .ct-count { font-size: 0.85rem; color: var(--muted); margin: 0 0 6px; }\n#p-catalog .ct-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(380px, 1fr)); gap: 14px; margin: 10px 0 18px; }\n#p-catalog .ct-card { background: var(--surface); border: 1px solid var(--rule); border-radius: 8px; padding: 10px 12px; min-width: 0; }\n#p-catalog .ct-card h4 { margin: 0 0 2px; font-size: 0.95rem; }\n#p-catalog .ct-src { margin: 0 0 6px; font-size: 0.78rem; color: var(--muted); }\n#p-catalog .ct-badge { display: inline-block; margin: 0 4px 6px 0; padding: 2px 8px; border-radius: 4px; font-size: 0.74rem; font-weight: 600; }\n#p-catalog .ct-badge.fits, #p-catalog .ct-badge.ok { background: var(--accent-soft); color: var(--accent); }\n#p-catalog .ct-badge.gofish-gap, #p-catalog .ct-badge.warning { background: var(--warn-soft); color: var(--warn); }\n#p-catalog .ct-badge.does-not-fit, #p-catalog .ct-badge.error { background: var(--warn); color: var(--surface); }\n#p-catalog .ct-badge.v1 { background: none; border: 1px solid var(--rule); color: var(--muted); font-weight: 400; }\n#p-catalog .ct-use { margin: 0 0 8px; font-size: 0.82rem; }\n#p-catalog .ct-use b { font-weight: 600; }\n#p-catalog .ct-verd { margin: 0 0 8px; font-size: 0.82rem; color: var(--muted); }\n#p-catalog figure { margin: 0; }\n#p-catalog .ct-card img { width: 100%; height: auto; display: block; background: #fff; border: 1px solid var(--rule); border-radius: 6px; margin: 0 0 4px; }\n#p-catalog figcaption { font-size: 0.76rem; color: var(--muted); margin: 0 0 6px; }\n#p-catalog .ct-card pre { margin: 8px 0 6px; font-size: 0.74rem; overflow-x: auto; max-width: 100%; }\n#p-catalog .ct-note { margin: 6px 0; font-size: 0.82rem; color: var(--muted); }\n#p-catalog details { margin: 6px 0 0; }\n#p-catalog details summary { cursor: pointer; color: var(--muted); font-size: 0.85rem; }\n#p-catalog details pre { font-size: 0.74rem; max-height: 420px; overflow: auto; }\n";
var LEDE = "\n<h2>Catalog</h2>\n<p>This tab lists every chart the grammar in <a href=\"#grammar\">GoFish over draws</a> was checked against. The selection rule is fixed. For ggdist it is every plotted chunk of the four vignettes installed with ggdist 3.3.3: slabinterval, dotsinterval, lineribbon and freq-uncertainty-vis. For ggdibbler it is the README, every plotted help-page example of each exported <code>geom_*_sample</code>, <code>stat_*_sample</code> and <code>position_*</code> function, and every figure in the ggdibbler paper that shows a ggdibbler chart.</p>\n<p>Charts were merged only when they differ in theme, color or labels, or when the code is the same. ggdist has one merge: <code>stat_lineribbon_gradient_rampbar</code> is merged into entry 73. ggdibbler has eight: entry 02 (README raster, help example 1, paper Fig 5c), 03 (README raster with more error, Fig 5d), 05 (README stack_identity, help example 3), 06 (README stack_dodge, help example 4), 11 (abline coef example, Fig 10a), 25 (geom_count_sample, Figs 14a and 10e), 31 (geom_dotplot_sample, Fig 14 middle panel) and 67 (geom_smooth_sample, Fig 7b). That gives 96 ggdist entries and 122 ggdibbler entries.</p>\n<p>Each card shows the package's own render, made in R from the code in the card. Paper figures with no published code were reconstructed, and their source says so; two ggdibbler contrast panels (105, 107) are plain ggplot2, not ggdibbler output. The GoFish spec uses version 2 of the grammar. The specs call <code>slab</code>, <code>interval</code>, <code>lineribbon</code>, <code>gradientinterval</code> and <code>ccdf</code>. These are not built-in marks. They are ordinary user code, defined in a few lines each in section 1 of the <a href=\"#grammar\">GoFish over draws</a> tab. A comment <code>gap:</code> marks a piece today's GoFish lacks, written as the call it would most likely be; it is not existing syntax. The fit class says whether the chart fits, fits except for a GoFish piece that has nothing to do with draws (<code>gofish-gap</code>), or cannot be written (<code>does-not-fit</code>). The verdict is what rules 3.1 to 3.4 say about the spec. The specs, the R code and two summaries are in the <code>catalog/</code> folder.</p>\n";
var root = document.getElementById("p-catalog");
function esc(s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;"); }
function vkind(v) { return v.split(":")[0]; }
var FITS = ["fits", "gofish-gap", "does-not-fit"];
var VERDS = ["ok", "warning", "error"];
var PKGS = ["ggdist", "ggdibbler"];
function coverage() {
  var h = '<div class="tw"><table class="cov"><thead><tr><th>Package</th><th>Fit class</th><th>v1</th><th>v2</th></tr></thead><tbody>';
  PKGS.forEach(function (p) {
    FITS.forEach(function (f, i) {
      var v1 = DATA.filter(function (e) { return e.pkg === p && e.v1_fit === f; }).length;
      var v2 = DATA.filter(function (e) { return e.pkg === p && e.fit === f; }).length;
      h += "<tr><td>" + (i ? "" : p) + "</td><td><code>" + f + "</code></td><td>" + v1 + "</td><td>" + v2 + "</td></tr>";
    });
  });
  h += '</tbody></table></div><div class="tw"><table class="cov"><thead><tr><th>Package</th><th>Verdict (v2)</th><th>entries</th></tr></thead><tbody>';
  PKGS.forEach(function (p) {
    VERDS.forEach(function (v, i) {
      var n = DATA.filter(function (e) { return e.pkg === p && vkind(e.verdict) === v; }).length;
      h += "<tr><td>" + (i ? "" : p) + "</td><td><code>" + v + "</code></td><td>" + n + "</td></tr>";
    });
  });
  return h + "</tbody></table></div>";
}
function card(e) {
  var vk = vkind(e.verdict);
  var cap = e.pkg === "ggdist" ? "ggdist render" : /contrast panel/.test(e.source) ? "plain ggplot2 render, not ggdibbler output" : "ggdibbler render";
  var h = '<div class="ct-card">';
  h += "<h4>" + esc(e.pkg + " " + e.num + ". " + e.title) + "</h4>";
  h += '<p class="ct-src">' + esc(e.source) + "</p>";
  h += '<span class="ct-badge ' + e.fit + '">' + e.fit + '</span><span class="ct-badge ' + vk + '">' + vk + "</span>";
  if (e.v1_fit !== e.fit) h += '<span class="ct-badge v1">v1: ' + e.v1_fit + "</span>";
  if (vk !== "ok") h += '<p class="ct-verd">' + esc(e.verdict) + "</p>";
  h += '<p class="ct-use"><b>Uses up the draws:</b> ' + esc(e.uses_up) + "</p>";
  h += '<figure><img loading="lazy" src="' + esc(e.img) + '" alt="' + esc(cap + ": " + e.title) + '">';
  e.more.forEach(function (m) { h += '<img loading="lazy" src="' + esc(m) + '" alt="' + esc(cap + ", merged chunk") + '">'; });
  h += "<figcaption>" + cap + " of the R code below</figcaption></figure>";
  h += '<pre><code class="language-js">' + esc(e.gofish) + "</code></pre>";
  h += '<p class="ct-note">' + esc(e.note) + "</p>";
  h += '<details><summary>R code</summary><pre><code class="language-r">' + esc(e.r) + "</code></pre></details>";
  return h + "</div>";
}
var state = { pkg: "all", fit: "all", verdict: "all" };
function match(e) {
  return (state.pkg === "all" || e.pkg === state.pkg) && (state.fit === "all" || e.fit === state.fit) && (state.verdict === "all" || vkind(e.verdict) === state.verdict);
}
function hl() {
  if (!window.hljs) return;
  root.querySelectorAll("pre code[class^=language-]").forEach(function (el) {
    if (!el.dataset.highlighted) window.hljs.highlightElement(el);
  });
}
function group(key, label, values) {
  var h = '<div class="ct-group"><span class="lab">' + label + "</span>";
  ["all"].concat(values).forEach(function (v) {
    h += '<button type="button" data-key="' + key + '" data-val="' + v + '" aria-pressed="' + (state[key] === v) + '">' + v + "</button>";
  });
  return h + "</div>";
}
function renderCards() {
  var sel = DATA.filter(match);
  var dnf = sel.filter(function (e) { return e.fit === "does-not-fit"; });
  var h = '<p class="ct-count">' + sel.length + " of " + DATA.length + " entries shown.</p>";
  if (dnf.length) h += "<h3>Does not fit (" + dnf.length + ')</h3><div class="ct-grid">' + dnf.map(card).join("") + "</div>";
  h += "<h3>All entries (" + sel.length + ')</h3><div class="ct-grid">' + sel.map(card).join("") + "</div>";
  document.getElementById("ct-cards").innerHTML = h;
  hl();
}
function renderFilters() {
  document.getElementById("ct-filters").innerHTML = group("pkg", "Package", PKGS) + group("fit", "Fit", FITS) + group("verdict", "Verdict", VERDS);
}
root.innerHTML = "<style>" + CSS + "</style>" + LEDE + "<h3>Coverage</h3>" + coverage() + '<div class="ct-filters" id="ct-filters"></div><div id="ct-cards"></div>';
root.addEventListener("click", function (ev) {
  var b = ev.target.closest("button[data-key]");
  if (!b) return;
  state[b.dataset.key] = b.dataset.val;
  renderFilters();
  renderCards();
});
renderFilters();
renderCards();
if (document.readyState !== "complete") window.addEventListener("load", hl);
})();
